{
  "name": "ScreenMind2",
  "description": "Локальный умный записной ноутбук с ИИ-автоматизацией и графом знаний для анализа текстов и документов.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface Note {
  id: string;
  title: string;
  content: string;
  tags: string[];
  category: string;
  summary: string;
  links: string[];
  createdAt: string;
  updatedAt: string;
}

export enum AIProvider {
  Ollama = 'Ollama',
  LMStudio = 'LM Studio',
  OpenRouter = 'OpenRouter'
}

export interface Settings {
  provider: AIProvider;
  url: string;
  model: string;
  apiKey: string;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  sources?: string[];
}

import { get, set, keys, del } from 'https://cdn.jsdelivr.net/npm/idb-keyval@6/+esm';
import { Note, Settings, AIProvider } from '../types';

const NOTES_KEY = 'screenmind_notes';
const SETTINGS_KEY = 'screenmind_settings';

export const saveNotes = async (notes: Note[]) => {
  await set(NOTES_KEY, notes);
};

export const getNotes = async (): Promise<Note[]> => {
  const notes = await get(NOTES_KEY);
  return notes || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  provider: AIProvider.Ollama,
  url: 'http://localhost:11434',
  model: 'mistral',
  apiKey: ''
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return settings || getDefaultSettings();
};

import { Settings, AIProvider } from '../types';

export const testConnection = async (settings: Settings): Promise<boolean> => {
  try {
    const endpoint = settings.provider === AIProvider.Ollama 
      ? `${settings.url}/api/tags` 
      : `${settings.url}/models`;

    const response = await fetch(endpoint, {
      method: 'GET',
      headers: settings.apiKey ? { 'Authorization': `Bearer ${settings.apiKey}` } : {}
    });
    return response.ok;
  } catch (e) {
    return false;
  }
};

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `Проанализируй следующий текст и верни ТОЛЬКО JSON без пояснений:
{
  "tags": ["tag1", "tag2"],
  "category": "CategoryName",
  "summary": "Brief summary"
}
Текст: ${text}`;

  let url = '';
  let body: any = {};
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };

  if (settings.provider === AIProvider.Ollama) {
    url = `${settings.url}/api/generate`;
    body = {
      model: settings.model,
      prompt,
      stream: false,
      format: 'json'
    };
  } else {
    url = `${settings.url}/chat/completions`;
    headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
    body = {
      model: settings.model,
      messages: [{ role: 'user', content: prompt }],
      response_format: { type: 'json_object' }
    };
  }

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(body)
    });
    const data = await response.json();

    let resultStr = '';
    if (settings.provider === AIProvider.Ollama) {
      resultStr = data.response;
    } else {
      resultStr = data.choices[0].message.content;
    }

    return JSON.parse(resultStr);
  } catch (e) {
    console.error('AI Analysis Error:', e);
    return { tags: ['ошибка'], category: 'Нераспознанное', summary: 'Не удалось проанализировать текст через ИИ.' };
  }
};

export const chatWithNotes = async (question: string, context: string, settings: Settings) => {
  const prompt = `Ты — ScreenMind2 AI. Твоя база знаний состоит из следующих заметок:
---
${context}
---
Ответь на вопрос пользователя, используя эти данные. Если информации нет, скажи об этом.
Вопрос: ${question}`;

  let url = '';
  let body: any = {};
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };

  if (settings.provider === AIProvider.Ollama) {
    url = `${settings.url}/api/generate`;
    body = { model: settings.model, prompt, stream: false };
  } else {
    url = `${settings.url}/chat/completions`;
    headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
    body = {
      model: settings.model,
      messages: [{ role: 'user', content: prompt }]
    };
  }

  const response = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  const data = await response.json();

  if (settings.provider === AIProvider.Ollama) return data.response;
  return data.choices[0].message.content;
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Note, Settings, AIProvider } from '../types';
import * as storage from '../utils/storage';
import * as ai from '../utils/aiAdapter';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  addNote: (content: string, title?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      setIsLoading(false);
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string): Promise<Note> => {
    const analysis = await ai.analyzeText(content, settings);
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 30).trim() + (content.length > 30 ? '...' : ''),
      content,
      tags: analysis.tags || [],
      category: analysis.category || 'Общее',
      summary: analysis.summary || '',
      links: [],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    const updatedNotes = [newNote, ...notes];
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
    return newNote;
  };

  const updateNote = async (updatedNote: Note) => {
    const updatedNotes = notes.map(n => n.id === updatedNote.id ? { ...updatedNote, updatedAt: new Date().toISOString() } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const deleteNote = async (id: string) => {
    const updatedNotes = notes.filter(n => n.id !== id);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const processLargeText = async (text: string) => {
    // Basic splitting by semantic boundaries (double newline)
    const blocks = text.split(/\n\s*\n/).filter(b => b.trim().length > 20);
    for (const block of blocks) {
      await addNote(block);
    }
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    await storage.saveSettings(newSettings);
  };

  return (
    <NotesContext.Provider value={{ notes, settings, isLoading, addNote, updateNote, deleteNote, processLargeText, updateSettings }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const context = useContext(NotesContext);
  if (!context) throw new Error('useNotes must be used within NotesProvider');
  return context;
};

