import React, { useState, useCallback } from 'react';
import { useNotes } from '../contexts/NotesContext';
import { Search, Upload as UploadIcon, Trash2, Edit3, Tag as TagIcon } from 'lucide-react';
import { Link } from 'react-router-dom';

const NotesPage: React.FC = () => {
  const { notes, processLargeText, deleteNote } = useNotes();
  const [search, setSearch] = useState('');
  const [isDragging, setIsDragging] = useState(false);

  const filteredNotes = notes.filter(n => 
    n.title.toLowerCase().includes(search.toLowerCase()) || 
    n.content.toLowerCase().includes(search.toLowerCase()) ||
    n.tags.some(t => t.toLowerCase().includes(search.toLowerCase()))
  );

  const handleDrop = useCallback(async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = Array.from(e.dataTransfer.files);

    for (const file of files) {
      if (file.type.startsWith('text/') || file.name.endsWith('.md')) {
        const text = await file.text();
        await processLargeText(text);
      } else if (file.type.startsWith('image/')) {
        await processLargeText("OCR Result placeholder for image analysis...");
      } else if (file.type.startsWith('audio/')) {
        await processLargeText("Audio transcript placeholder for transcription...");
      }
    }
  }, [processLargeText]);

  return (
    <div className="p-8 max-w-7xl mx-auto min-h-screen">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-2xl font-bold">Мои знания</h2>
        <div className="relative w-72">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="Поиск по заметкам..."
            className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        className={`mb-8 border-2 border-dashed rounded-xl p-12 transition-all flex flex-col items-center justify-center gap-4 ${
          isDragging ? 'border-blue-500 bg-blue-50' : 'border-gray-300 bg-white'
        }`}
      >
        <div className="p-4 bg-blue-100 text-blue-600 rounded-full">
          <UploadIcon size={32} />
        </div>
        <div className="text-center">
          <p className="text-lg font-medium">Перетащите файлы сюда</p>
          <p className="text-sm text-gray-500">.txt, .md, изображения (OCR) или аудио (Транскрибация)</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredNotes.map((note) => (
          <div 
            key={note.id}
            className="group bg-white p-5 rounded-xl border border-gray-200 hover:shadow-xl transition-all hover:-translate-y-1 flex flex-col h-64"
          >
            <div className="flex justify-between items-start mb-3">
              <span className="text-xs font-semibold text-blue-600 uppercase tracking-wider bg-blue-50 px-2 py-1 rounded">
                {note.category}
              </span>
              <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <Link to={`/editor/${note.id}`} className="p-1 hover:text-blue-600"><Edit3 size={16}/></Link>
                <button onClick={() => deleteNote(note.id)} className="p-1 hover:text-red-600"><Trash2 size={16}/></button>
              </div>
            </div>

            <h3 className="font-bold text-lg mb-2 line-clamp-1">{note.title}</h3>
            <p className="text-sm text-gray-600 mb-4 line-clamp-4 flex-1">{note.content}</p>

            <div className="flex flex-wrap gap-2 mt-auto">
              {note.tags.slice(0, 3).map(tag => (
                <span key={tag} className="text-[10px] bg-gray-100 text-gray-700 px-2 py-0.5 rounded flex items-center gap-1">
                  <TagIcon size={10} /> {tag}
                </span>
              ))}
              <span className="text-[10px] text-gray-400 ml-auto self-center">
                {new Date(note.createdAt).toLocaleDateString('ru-RU')}
              </span>
            </div>
          </div>
        ))}
      </div>

      {filteredNotes.length === 0 && (
        <div className="text-center py-20 text-gray-400">
          Заметок пока нет. Начните с создания новой или загрузки файла.
        </div>
      )}
    </div>
  );
};

export default NotesPage;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext';
import { ChevronLeft, Save, Sparkles } from 'lucide-react';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (id && id !== 'new') {
      const note = notes.find(n => n.id === id);
      if (note) {
        setTitle(note.title);
        setContent(note.content);
      }
    }
  }, [id, notes]);

  const handleSave = async () => {
    setIsSaving(true);
    if (id === 'new') {
      await addNote(content, title);
    } else {
      const existing = notes.find(n => n.id === id);
      if (existing) {
        await updateNote({ ...existing, title, content });
      }
    }
    setIsSaving(false);
    navigate('/');
  };

  return (
    <div className="h-screen flex flex-col bg-white">
      <div className="flex items-center justify-between p-4 border-b">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate(-1)} className="p-2 hover:bg-gray-100 rounded-full">
            <ChevronLeft size={20} />
          </button>
          <input
            type="text"
            placeholder="Заголовок заметки"
            className="text-xl font-bold focus:outline-none w-96"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
        </div>
        <div className="flex gap-3">
          <button 
            disabled={isSaving}
            onClick={handleSave}
            className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50"
          >
            <Save size={18} />
            {isSaving ? 'Сохранение...' : 'Сохранить'}
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 p-8 overflow-y-auto border-r">
          <textarea
            placeholder="Вставьте текст или начните печатать... Поддерживаются $формулы$ и `код`."
            className="w-full h-full resize-none focus:outline-none text-lg leading-relaxed font-mono"
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
        </div>

        <div className="w-1/3 p-8 bg-gray-50 overflow-y-auto prose max-w-none">
          <div className="flex items-center gap-2 mb-4 text-gray-500 uppercase text-xs font-bold tracking-widest">
            <Sparkles size={14} />
            Предпросмотр
          </div>
          {/* Mock Markdown/KaTeX/Prism renderer */}
          <div className="whitespace-pre-wrap font-sans text-gray-800">
            {content || <span className="text-gray-400 italic">Здесь будет результат рендеринга...</span>}
          </div>
        </div>
      </div>
    </div>
  );
};

export default NoteEditor;

import React, { useEffect, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext';
import * as d3 from 'https://cdn.jsdelivr.net/npm/d3@7/+esm';
import { useNavigate } from 'react-router-dom';

const GraphView: React.FC = () => {
  const { notes } = useNotes();
  const navigate = useNavigate();
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || notes.length === 0) return;

    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const nodes = notes.map(n => ({ id: n.id, title: n.title, group: n.category }));
    // Simple links based on common tags or shared categories for visualization
    const links: any[] = [];
    notes.forEach((n, i) => {
      notes.slice(i + 1).forEach(m => {
        const commonTags = n.tags.filter(t => m.tags.includes(t));
        if (commonTags.length > 0 || n.category === m.category) {
          links.push({ source: n.id, target: m.id, value: commonTags.length + 1 });
        }
      });
    });

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const simulation = d3.forceSimulation(nodes as any)
      .force("link", d3.forceLink(links).id((d: any) => d.id).distance(100))
      .force("charge", d3.forceManyBody().strength(-150))
      .force("center", d3.forceCenter(width / 2, height / 2));

    const g = svg.append("g");

    svg.call(d3.zoom<SVGSVGElement, unknown>()
      .extent([[0, 0], [width, height]])
      .scaleExtent([0.1, 4])
      .on("zoom", (event) => g.attr("transform", event.transform)));

    const link = g.append("g")
      .attr("stroke", "#e5e7eb")
      .attr("stroke-opacity", 0.6)
      .selectAll("line")
      .data(links)
      .join("line")
      .attr("stroke-width", d => Math.sqrt(d.value));

    const node = g.append("g")
      .attr("stroke", "#fff")
      .attr("stroke-width", 1.5)
      .selectAll("circle")
      .data(nodes)
      .join("circle")
      .attr("r", 8)
      .attr("fill", (d: any) => d3.schemeCategory10[nodes.findIndex(n => n.group === d.group) % 10])
      .on("click", (event, d: any) => navigate(`/editor/${d.id}`))
      .style("cursor", "pointer")
      .call(d3.drag<any, any>()
        .on("start", (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on("drag", (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on("end", (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        }));

    const text = g.append("g")
      .selectAll("text")
      .data(nodes)
      .join("text")
      .attr("dy", -12)
      .attr("text-anchor", "middle")
      .attr("font-size", "10px")
      .attr("fill", "#4b5563")
      .text(d => d.title.slice(0, 15));

    simulation.on("tick", () => {
      link
        .attr("x1", (d: any) => d.source.x)
        .attr("y1", (d: any) => d.source.y)
        .attr("x2", (d: any) => d.target.x)
        .attr("y2", (d: any) => d.target.y);

      node
        .attr("cx", (d: any) => d.x)
        .attr("cy", (d: any) => d.y);

      text
        .attr("x", (d: any) => d.x)
        .attr("y", (d: any) => d.y);
    });

    return () => simulation.stop();
  }, [notes, navigate]);

  return (
    <div className="flex-1 flex flex-col h-screen overflow-hidden">
      <div className="p-6 bg-white border-b flex justify-between items-center">
        <h2 className="text-xl font-bold">Граф знаний</h2>
        <div className="text-sm text-gray-500">Узлы: {notes.length}</div>
      </div>
      <div className="flex-1 relative bg-gray-50">
        <svg ref={svgRef} className="w-full h-full" />
      </div>
    </div>
  );
};

export default GraphView;

import React, { useState, useRef, useEffect } from 'react';
import { useNotes } from '../contexts/NotesContext';
import { Send, Bot, User, Eraser } from 'lucide-react';
import * as ai from '../utils/aiAdapter';
import { ChatMessage } from '../types';

const ChatPage: React.FC = () => {
  const { notes, settings } = useNotes();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage: ChatMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    // Build context from notes
    const context = notes.map(n => `[ID: ${n.id}] ${n.title}: ${n.content}`).join('\n\n');

    try {
      const response = await ai.chatWithNotes(input, context, settings);

      // Match IDs in response to find sources
      const sources = notes.filter(n => response.includes(n.id)).map(n => n.id);

      const aiMessage: ChatMessage = { 
        role: 'assistant', 
        content: response,
        sources: sources.length > 0 ? sources : undefined
      };
      setMessages(prev => [...prev, aiMessage]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'assistant', content: 'Произошла ошибка при получении ответа. Проверьте настройки ИИ.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-screen max-w-4xl mx-auto p-4">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <Bot className="text-blue-600" />
          Интеллектуальный чат
        </h2>
        <button 
          onClick={() => setMessages([])}
          className="text-gray-400 hover:text-red-500 flex items-center gap-1 text-sm transition-colors"
        >
          <Eraser size={16} /> Очистить
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 mb-6 px-2 scroll-smooth">
        {messages.length === 0 && (
