  );

  const handleDrop = useCallback(async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    // Fix: Explicitly cast FileList to File array to ensure proper typing for the iteration variable
    const files = Array.from(e.dataTransfer.files) as File[];

    for (const file of files) {
      // Fix: Accessing 'type' and 'name' properties on the typed File object
      if (file.type.startsWith('text/') || file.name.endsWith('.md')) {
        // Fix: 'file.text()' is a standard method on the File object
        const text = await file.text();
        await processLargeText(text);
