import { GoogleGenAI, Type } from "@google/genai";

const getBaseUrl = (url: string) => url.replace(/\/$/, '');

export const testConnection = async (settings: Settings): Promise<boolean> => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: 'ping',
      });
      return !!response.text;
    }

    const baseUrl = getBaseUrl(settings.url);
    const endpoint = settings.provider === AIProvider.Ollama 
      ? `${baseUrl}/api/tags` 
      : `${baseUrl}/models`;

    const response = await fetch(endpoint, {
      method: 'GET',
      mode: 'cors', // Explicitly request CORS
      headers: settings.apiKey ? { 'Authorization': `Bearer ${settings.apiKey}` } : {}
    });
    return response.ok;
  } catch (e) {
    console.error('Connection test failed:', e);
    return false;
  }
};

export const analyzeText = async (text: string, settings: Settings) => {
  if (settings.provider === AIProvider.Gemini) {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Проанализируй следующий текст и верни структурированные данные в JSON формате:\n\n${text}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              tags: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
                description: 'Список релевантных тегов',
              },
              category: {
                type: Type.STRING,
                description: 'Категория контента',
              },
              summary: {
                type: Type.STRING,
                description: 'Краткое резюме одной фразой',
              }
            },
            required: ["tags", "category", "summary"]
          }
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) {
      console.error('Gemini Analysis Error:', e);
      throw e; // Pass it to the caller
    }
  }

  const baseUrl = getBaseUrl(settings.url);
  const prompt = `Проанализируй следующий текст и верни ТОЛЬКО JSON без пояснений:
{
  "tags": ["tag1", "tag2"],
  "category": "CategoryName",
  "summary": "Brief summary"
}
Текст: ${text}`;

  let url = '';
  let body: any = {};
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };

  if (settings.provider === AIProvider.Ollama) {
    url = `${baseUrl}/api/generate`;
    body = {
      model: settings.model,
      prompt,
      stream: false,
      format: 'json'
    };
  } else {
    url = `${baseUrl}/chat/completions`;
    headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
    body = {
      model: settings.model,
      messages: [{ role: 'user', content: prompt }],
      response_format: { type: 'json_object' }
    };
  }

  try {
    const response = await fetch(url, {
      method: 'POST',
      mode: 'cors',
      headers,
      body: JSON.stringify(body)
    });

    if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
    }

    const data = await response.json();
    let resultStr = '';

    if (settings.provider === AIProvider.Ollama) {
      resultStr = data.response;
    } else {
      resultStr = data.choices[0].message.content;
    }

    return JSON.parse(resultStr);
  } catch (e) {
    console.error('AI Analysis Error:', e);
    throw e;
  }
};

export const chatWithNotes = async (question: string, context: string, settings: Settings) => {
  if (settings.provider === AIProvider.Gemini) {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Ты — ScreenMind2 AI. Твоя база знаний состоит из следующих заметок:\n---\n${context}\n---\nОтветь на вопрос пользователя, используя эти данные. Если информации нет, скажи об этом.\nВопрос: ${question}`,
      });
      return response.text;
    } catch (e) {
      console.error('Gemini Chat Error:', e);
      throw e;
    }
  }

  const baseUrl = getBaseUrl(settings.url);
  const prompt = `Ты — ScreenMind2 AI. Твоя база знаний состоит из следующих заметок:
---
${context}
---
Ответь на вопрос пользователя, используя эти данные. Если информации нет, скажи об этом.
Вопрос: ${question}`;

  let url = '';
  let body: any = {};
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };

  if (settings.provider === AIProvider.Ollama) {
    url = `${baseUrl}/api/generate`;
    body = { model: settings.model, prompt, stream: false };
  } else {
    url = `${baseUrl}/chat/completions`;
    headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
    body = {
      model: settings.model,
      messages: [{ role: 'user', content: prompt }]
    };
  }

  const response = await fetch(url, { method: 'POST', mode: 'cors', headers, body: JSON.stringify(body) });
  if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

  const data = await response.json();
  if (settings.provider === AIProvider.Ollama) return data.response;
  return data.choices[0].message.content;
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Note, Settings, AIProvider } from '../types';
import * as storage from '../utils/storage';
import * as ai from '../utils/aiAdapter';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  addNote: (content: string, title?: string, date?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      setIsLoading(false);
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, date?: string): Promise<Note> => {
    let analysis = { tags: [], category: 'Общее', summary: '' };
    try {
        analysis = await ai.analyzeText(content, settings);
    } catch (e) {
        console.warn('AI analysis failed for note, using defaults:', e);
        analysis = { tags: ['анализ-не-удался'], category: 'Нераспознанное', summary: 'Ошибка ИИ' };
    }

    const createdAt = date ? new Date(date).toISOString() : new Date().toISOString();

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags || [],
      category: analysis.category || 'Общее',
      summary: analysis.summary || '',
      links: [],
      createdAt,
      updatedAt: new Date().toISOString()
    };

    return newNote;
  };

  const updateNote = async (updatedNote: Note) => {
    const updatedNotes = notes.map(n => n.id === updatedNote.id ? { ...updatedNote, updatedAt: new Date().toISOString() } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const deleteNote = async (id: string) => {
    const updatedNotes = notes.filter(n => n.id !== id);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const processLargeText = async (text: string) => {
    setProcessingProgress(0);

    const sectionDelimiter = /={10,}/;
    const parts = text.split(sectionDelimiter);
    const newNotes: Note[] = [];

    for (let i = 0; i < parts.length; i++) {
      const part = parts[i].trim();
      if (!part) continue;

      const dateMatch = part.match(/ДАТА:\s*(\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2})/);

      if (dateMatch) {
        const date = dateMatch[1];
        let content = "";
        let j = i + 1;

        while (j < parts.length) {
            const nextPart = parts[j].trim();
            if (nextPart && !nextPart.includes("ТИП:") && !nextPart.includes("ДАТА:")) {
                content = nextPart;
                i = j; 
                break;
            }
            j++;
        }

        if (content.length > 10) {
            try {
                const note = await addNote(content, undefined, date);
                newNotes.push(note);
            } catch (err) {
                console.error('Failed to add note from batch:', err);
            }
        }
      } else if (part.length > 20 && !part.includes("ТИП:") && !part.includes("ДАТА:")) {
          try {
              const note = await addNote(part);
              newNotes.push(note);
          } catch (err) {
              console.error('Failed to add note from fallback part:', err);
          }
      }

      setProcessingProgress(Math.round(((i + 1) / parts.length) * 100));
    }

    if (newNotes.length > 0) {
        const updatedNotes = [...newNotes, ...notes];
        setNotes(updatedNotes);
        await storage.saveNotes(updatedNotes);
    }
    setProcessingProgress(null);
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    await storage.saveSettings(newSettings);
  };

  return (
    <NotesContext.Provider value={{ 
      notes, settings, isLoading, processingProgress, 
      addNote: async (c, t, d) => {
          const n = await addNote(c, t, d);
          setNotes(prev => [n, ...prev]);
          const latestNotes = await storage.getNotes();
          await storage.saveNotes([n, ...latestNotes]);
          return n;
      }, 
      updateNote, deleteNote, processLargeText, updateSettings 
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const context = useContext(NotesContext);
  if (!context) throw new Error('useNotes must be used within NotesProvider');
  return context;
};

