export const getTagColor = (tag: string) => {
  let hash = 0;
  for (let i = 0; i < tag.length; i++) {
    hash = tag.charCodeAt(i) + ((hash << 5) - hash);
  }

  const h = Math.abs(hash % 360);
  // We want readable colors: medium lightness and saturation
  return {
    bg: `hsla(${h}, 70%, 95%, 1)`,
    text: `hsla(${h}, 70%, 30%, 1)`,
    border: `hsla(${h}, 70%, 85%, 1)`
  };
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Note, Settings, AIProvider } from '../types';
import * as storage from '../utils/storage';
import * as ai from '../utils/aiAdapter';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  addNote: (content: string, title?: string, date?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  processFile: (file: File) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      setIsLoading(false);
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, date?: string): Promise<Note> => {
    let analysis = { tags: [], category: 'Общее', summary: '' };
    try {
        analysis = await ai.analyzeText(content, settings);
    } catch (e) {
        analysis = { tags: ['анализ-не-удался'], category: 'Нераспознанное', summary: 'Ошибка ИИ' };
    }

    const createdAt = date ? new Date(date).toISOString() : new Date().toISOString();

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags || [],
      category: analysis.category || 'Общее',
      summary: analysis.summary || '',
      links: [],
      createdAt,
      updatedAt: new Date().toISOString()
    };

    return newNote;
  };

  const updateNote = async (updatedNote: Note) => {
    const updatedNotes = notes.map(n => n.id === updatedNote.id ? { ...updatedNote, updatedAt: new Date().toISOString() } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const deleteNote = async (id: string) => {
    const updatedNotes = notes.filter(n => n.id !== id);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const processFile = async (file: File) => {
    setProcessingProgress(10);
    const isAudio = file.type.startsWith('audio/');
    const isImage = file.type.startsWith('image/');

    if (isAudio) {
        // Mock transcription process
        setProcessingProgress(40);
        await new Promise(r => setTimeout(r, 1500)); // Simulating processing
        const note = await addNote(`[Транскрибация аудио: ${file.name}]\nВ этой записи обсуждались ключевые идеи по автоматизации рабочих процессов через Telegram и локальные ИИ модели.`, `Аудио: ${file.name}`);
        setNotes(prev => [note, ...prev]);
        await storage.saveNotes([note, ...notes]);
    } else if (isImage) {
        const note = await addNote(`[OCR из изображения: ${file.name}]\nРезультат распознавания текста со скриншота.`, `Скриншот: ${file.name}`);
        setNotes(prev => [note, ...prev]);
        await storage.saveNotes([note, ...notes]);
    } else {
        const text = await file.text();
        await processLargeText(text);
    }
    setProcessingProgress(null);
  }

  const processLargeText = async (text: string) => {
    setProcessingProgress(0);
    const sectionDelimiter = /={10,}/;
    const parts = text.split(sectionDelimiter);
    const newNotes: Note[] = [];

    for (let i = 0; i < parts.length; i++) {
      const part = parts[i].trim();
      if (!part) continue;

      const dateMatch = part.match(/ДАТА:\s*(\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2})/);

      if (dateMatch) {
        const date = dateMatch[1];
        let content = "";
        let j = i + 1;
        while (j < parts.length) {
            const nextPart = parts[j].trim();
            if (nextPart && !nextPart.includes("ТИП:") && !nextPart.includes("ДАТА:")) {
                content = nextPart;
                i = j; 
                break;
            }
            j++;
        }
        if (content.length > 10) {
            try {
                const note = await addNote(content, undefined, date);
                newNotes.push(note);
            } catch (err) {}
        }
      } else if (part.length > 20 && !part.includes("ТИП:") && !part.includes("ДАТА:")) {
          try {
              const note = await addNote(part);
              newNotes.push(note);
          } catch (err) {}
      }
      setProcessingProgress(Math.round(((i + 1) / parts.length) * 100));
    }

    if (newNotes.length > 0) {
        const updatedNotes = [...newNotes, ...notes];
        setNotes(updatedNotes);
        await storage.saveNotes(updatedNotes);
    }
    setProcessingProgress(null);
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    await storage.saveSettings(newSettings);
  };

  return (
    <NotesContext.Provider value={{ 
      notes, settings, isLoading, processingProgress, 
      addNote: async (c, t, d) => {
          const n = await addNote(c, t, d);
          setNotes(prev => [n, ...prev]);
          const latestNotes = await storage.getNotes();
          await storage.saveNotes([n, ...latestNotes]);
          return n;
      }, 
      updateNote, deleteNote, processLargeText, processFile, updateSettings 
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const context = useContext(NotesContext);
  if (!context) throw new Error('useNotes must be used within NotesProvider');
  return context;
};

import React, { useState, useCallback, useMemo } from 'react';
import { useNotes } from '../contexts/NotesContext';
import { Note } from '../types';
import { getTagColor } from '../utils/tagColors';
import { 
  Search, Upload as UploadIcon, Trash2, Edit3, Tag as TagIcon, 
  FileText, Download, CheckSquare, Square, XCircle, Loader2,
  Calendar, Layers, Sparkles, Filter, Music, Image as ImageIcon
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

const NotesPage: React.FC = () => {
  const { notes, processFile, deleteNote, processingProgress } = useNotes();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [activeTag, setActiveTag] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Aggregate all tags for the filter cloud
  const allTags = useMemo(() => {
    const tags = new Set<string>();
    notes.forEach(n => n.tags.forEach(t => tags.add(t)));
    return Array.from(tags).sort();
  }, [notes]);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const query = search.toLowerCase();
    const matchesSearch = n.title.toLowerCase().includes(query) || 
                         n.content.toLowerCase().includes(query) ||
                         n.category.toLowerCase().includes(query) ||
                         n.tags.some(t => t.toLowerCase().includes(query));
    const matchesTag = !activeTag || n.tags.includes(activeTag);
    return matchesSearch && matchesTag;
  }), [notes, search, activeTag]);

  const toggleSelect = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedIds(newSelected);
  };

  const handleDrop = useCallback(async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = Array.from(e.dataTransfer.files) as File[];
    for (const file of files) {
      await processFile(file);
    }
  }, [processFile]);

  const exportMarkdown = () => {
    const selectedNotes = notes.filter(n => selectedIds.has(n.id));
    const content = selectedNotes.map(n => `# ${n.title}\n\n**Категория:** ${n.category}\n**Теги:** ${n.tags.join(', ')}\n\n${n.content}\n\n---`).join('\n\n');
    const blob = new Blob([content], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ScreenMind_Export_${new Date().toISOString().slice(0,10)}.md`;
    a.click();
    setSelectedIds(new Set());
  };

  const exportPDF = async () => {
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF();
    const selectedNotes = notes.filter(n => selectedIds.has(n.id));
    selectedNotes.forEach((n, index) => {
      if (index > 0) doc.addPage();
      doc.setFontSize(22);
      doc.text(n.title, 10, 20);
      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(`Категория: ${n.category} | Создано: ${new Date(n.createdAt).toLocaleDateString()}`, 10, 30);
      doc.setTextColor(0);
      doc.setFontSize(12);
      const splitText = doc.splitTextToSize(n.content, 180);
      doc.text(splitText, 10, 45);
    });
    doc.save(`ScreenMind_Export.pdf`);
    setSelectedIds(new Set());
  };

  const batchDelete = async () => {
    if (!confirm(`Удалить ${selectedIds.size} заметок?`)) return;
    for (const id of Array.from(selectedIds)) {
      await deleteNote(id);
    }
    setSelectedIds(new Set());
  };

  return (
    <div className="p-8 max-w-7xl mx-auto min-h-screen relative pb-32">
      {/* Dynamic Header */}
      <div className="flex flex-col md:flex-row items-end justify-between gap-6 mb-8">
        <div className="space-y-1">
            <div className="flex items-center gap-2 text-blue-600 font-bold text-sm uppercase tracking-widest">
                <Sparkles size={16} /> ScreenMind AI
            </div>
            <h2 className="text-4xl font-black text-gray-900">База Знаний</h2>
            <div className="flex gap-4 text-sm text-gray-500 font-medium">
                <span className="flex items-center gap-1"><Layers size={14}/> {notes.length} объектов</span>
            </div>
        </div>

        <div className="relative w-full md:w-96 group">
          <div className="absolute inset-0 bg-blue-500/10 blur-2xl rounded-full opacity-0 group-focus-within:opacity-100 transition-opacity"></div>
          <div className="relative glass border border-gray-200/50 rounded-2xl shadow-xl flex items-center transition-all focus-within:ring-2 focus-within:ring-blue-500/20">
            <Search className="ml-4 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Поиск по архивам..."
              className="w-full px-4 py-4 bg-transparent rounded-2xl focus:outline-none text-gray-800 font-medium placeholder:text-gray-400"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            {search && (
              <button onClick={() => setSearch('')} className="mr-3 p-1 hover:bg-gray-100 rounded-full text-gray-400 transition-colors">
                <XCircle size={18} />
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Tag Cloud */}
      <div className="flex flex-wrap gap-2 mb-10 pb-4 border-b border-gray-100 items-center">
        <div className="flex items-center gap-2 text-xs font-bold text-gray-400 uppercase tracking-widest mr-4">
            <Filter size={14} /> Фильтр:
        </div>
        <button 
            onClick={() => setActiveTag(null)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${!activeTag ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-white text-gray-500 hover:bg-gray-50 border border-gray-100'}`}
        >
            Bce
        </button>
        {allTags.map(tag => {
            const colors = getTagColor(tag);
            const isActive = activeTag === tag;
            return (
                <button 
                    key={tag}
                    onClick={() => setActiveTag(isActive ? null : tag)}
                    style={{ 
                        backgroundColor: isActive ? colors.text : colors.bg,
                        color: isActive ? 'white' : colors.text,
                        borderColor: colors.border
                    }}
                    className="px-4 py-2 rounded-xl text-xs font-bold border transition-all hover:scale-105"
                >
                    #{tag}
                </button>
            );
        })}
      </div>

      {/* Processing State */}
      {processingProgress !== null ? (
        <div className="mb-12 p-8 glass border-blue-200/50 rounded-3xl shadow-2xl overflow-hidden relative">
          <div className="absolute top-0 left-0 h-1 bg-blue-500 transition-all duration-500" style={{ width: `${processingProgress}%` }}></div>
          <div className="flex items-center gap-6">
            <div className="p-4 bg-blue-600 text-white rounded-2xl animate-bounce shadow-lg shadow-blue-500/40">
              <Loader2 className="animate-spin" size={32} />
            </div>
            <div className="flex-1">
              <h3 className="text-xl font-bold text-gray-900 mb-1">Обработка данных...</h3>
              <p className="text-gray-500 font-medium">Транскрибация или OCR ({processingProgress}%)</p>
            </div>
            <div className="text-3xl font-black text-blue-600">{processingProgress}%</div>
          </div>
        </div>
      ) : (
        <div
          onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={handleDrop}
          className={`mb-12 border-2 border-dashed rounded-[2.5rem] p-12 transition-all flex flex-col items-center justify-center gap-6 group relative overflow-hidden ${
            isDragging ? 'border-blue-500 bg-blue-50/50 scale-[0.98]' : 'border-gray-200 bg-white hover:border-blue-300 hover:shadow-2xl hover:shadow-blue-500/5'
          }`}
        >
          <div className="absolute inset-0 bg-gradient-to-br from-blue-50/0 to-blue-50/40 opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <div className="relative p-6 bg-white shadow-2xl rounded-3xl text-blue-600 group-hover:scale-110 transition-transform duration-500 flex gap-4">
            <UploadIcon size={40} />
            <Music size={40} className="text-purple-400" />
            <ImageIcon size={40} className="text-green-400" />
          </div>
          <div className="relative text-center space-y-2">
            <p className="text-2xl font-black text-gray-800">Перетащите файлы</p>
            <p className="text-gray-400 font-medium max-w-sm">Текст, изображения (OCR) или Аудио (Транскрибация)</p>
          </div>
        </div>
      )}

      {/* Note Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredNotes.map((note) => (
          <div 
            key={note.id}
            onClick={() => selectedIds.size > 0 ? toggleSelect(note.id) : navigate(`/editor/${note.id}`)}
            className={`group bg-white p-7 rounded-[2rem] border transition-all cursor-pointer relative flex flex-col h-[22rem] ${
              selectedIds.has(note.id) 
                ? 'border-blue-500 ring-4 ring-blue-500/10 shadow-2xl scale-[1.02]' 
                : 'border-gray-100 hover:border-blue-200 hover:shadow-[0_20px_50px_rgba(0,0,0,0.05)] shadow-sm'
            }`}
          >
            {/* Multi-select check */}
            <div className={`absolute top-6 right-6 z-10 transition-all duration-300 ${selectedIds.size > 0 ? 'scale-100 opacity-100' : 'scale-50 opacity-0 group-hover:scale-100 group-hover:opacity-100'}`}>
              <button 
                onClick={(e) => toggleSelect(note.id, e)}
                className={`w-10 h-10 rounded-2xl flex items-center justify-center transition-all ${
                    selectedIds.has(note.id) 
                        ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/40' 
                        : 'bg-white border-2 border-gray-100 text-gray-300 hover:border-blue-400 hover:text-blue-500 shadow-sm'
                }`}
              >
                {selectedIds.has(note.id) ? <CheckSquare size={20} /> : <Square size={20} />}
              </button>
            </div>

            <div className="mb-5 flex items-center gap-3">
              <span className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] bg-blue-50 px-4 py-1.5 rounded-xl border border-blue-100/50">
                {note.category}
              </span>
              <span className="text-[10px] text-gray-400 font-bold bg-gray-50 px-3 py-1.5 rounded-xl">
                {new Date(note.createdAt).toLocaleDateString('ru-RU')}
              </span>
            </div>

            <h3 className="font-extrabold text-xl text-gray-900 mb-4 line-clamp-2 leading-tight group-hover:text-blue-600 transition-colors">
                {note.title}
            </h3>

            <div className="relative flex-1 overflow-hidden">
                <p className="text-sm text-gray-500 leading-relaxed line-clamp-5">
                    {note.summary ? (
                        <span className="italic text-gray-400 block mb-2">"{note.summary}"</span>
                    ) : null}
                    {note.content}
                </p>
                <div className="absolute bottom-0 left-0 right-0 h-12 bg-gradient-to-t from-white to-transparent"></div>
            </div>

            <div className="flex flex-wrap gap-2 mt-6 pt-5 border-t border-gray-50">
              {note.tags.slice(0, 3).map(tag => {
                const colors = getTagColor(tag);
                return (
                    <span 
                        key={tag} 
                        style={{ backgroundColor: colors.bg, color: colors.text, borderColor: colors.border }}
                        className="text-[9px] px-3 py-1.5 rounded-lg border font-bold flex items-center gap-1.5 transition-colors"
                    >
                        <TagIcon size={10} /> {tag}
                    </span>
                );
              })}
              <div className="ml-auto flex gap-1 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
                <button onClick={(e) => { e.stopPropagation(); deleteNote(note.id); }} className="p-2.5 bg-gray-50 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all hover:-rotate-6"><Trash2 size={16}/></button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Float Selection Bar */}
      {selectedIds.size > 0 && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 glass border border-white/50 shadow-[0_30px_100px_rgba(0,0,0,0.15)] rounded-[2.5rem] px-10 py-5 flex items-center gap-10 animate-slide-up z-50">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Объектов</span>
            <span className="text-3xl font-black text-gray-900">{selectedIds.size}</span>
          </div>
          <div className="h-12 w-px bg-gray-200/50"></div>
          <div className="flex gap-4">
            <button onClick={exportMarkdown} className="flex items-center gap-3 bg-gray-900 text-white px-7 py-3.5 rounded-2xl hover:bg-black transition-all shadow-xl shadow-gray-900/10 active:scale-95 group">
              <FileText size={20} className="group-hover:rotate-12 transition-transform" />
              <span className="font-bold">Export MD</span>
            </button>
            <button onClick={exportPDF} className="flex items-center gap-3 bg-blue-600 text-white px-7 py-3.5 rounded-2xl hover:bg-blue-700 transition-all shadow-xl shadow-blue-500/20 active:scale-95 group">
              <Download size={20} className="group-hover:-translate-y-1 transition-transform" />
              <span className="font-bold">Export PDF</span>
            </button>
            <div className="flex gap-2">
                <button onClick={batchDelete} className="p-4 text-red-500 hover:bg-red-50 rounded-2xl transition-all hover:scale-110"><Trash2 size={24} /></button>
                <button onClick={() => setSelectedIds(new Set())} className="p-4 text-gray-400 hover:bg-gray-100 rounded-2xl transition-all hover:rotate-90"><XCircle size={24} /></button>
            </div>
          </div>
        </div>
      )}

      {filteredNotes.length === 0 && !processingProgress && (
        <div className="text-center py-40">
          <div className="inline-block p-10 bg-gray-100/50 text-gray-200 rounded-[3rem] mb-6 animate-pulse">
            <Layers size={80} />
          </div>
          <h3 className="text-2xl font-black text-gray-300">Ничего не найдено</h3>
          <p className="text-gray-400 font-medium mt-2">Попробуйте загрузить файл или изменить фильтры</p>
        </div>
      )}
    </div>
  );
};

