import { getTagColor } from '../utils/tagColors';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, deleteNote, splitNote } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [note, setNote] = useState<any>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
      }
    }
  }, [id, notes]);

  const handleSave = async () => {
    setIsSaving(true);
    if (id === 'new') {
      await addNote(content, title);
    } else {
      if (note) {
        await updateNote({ ...note, title, content });
      }
    }
    setIsSaving(false);
    navigate('/');
  };

  const handleSplit = async () => {
    if (!id || id === 'new') return;
    if (confirm("Разбить эту заметку на части с помощью ИИ? Это создаст новые карточки.")) {
        await splitNote(id);
        navigate('/');
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white">
      <div className="flex items-center justify-between px-8 py-5 border-b border-gray-100">
        <div className="flex items-center gap-8">
