            <ChevronLeft size={24} />
          </button>
          <div className="space-y-1">
             <input
                type="text"
                placeholder="Заголовок заметки"
                className="text-2xl font-black focus:outline-none w-[32rem] placeholder:text-gray-200"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
              />
              <div className="flex items-center gap-3">
                {note?.tags.map((tag: string) => {
                    const colors = getTagColor(tag);
                    return (
                        <span key={tag} style={{ color: colors.text }} className="text-[10px] font-bold">#{tag}</span>
                    )
                })}
              </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          {id !== 'new' && (
            <div className="flex gap-2 mr-4 border-r pr-6 border-gray-100">
                <button 
                    onClick={handleSplit}
                    className="p-3 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-2xl transition-all"
                    title="Разбить заметку ИИ"
                >
                    <Scissors size={20} />
                </button>
                <button 
                    onClick={() => { deleteNote(id!); navigate('/'); }}
                    className="p-3 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all"
                >
                    <Trash2 size={20} />
                </button>
            </div>
          )}
          <button 
            disabled={isSaving}
            onClick={handleSave}
            className="flex items-center gap-3 bg-blue-600 text-white px-8 py-4 rounded-[1.5rem] hover:bg-blue-700 transition-all shadow-xl shadow-blue-500/20 active:scale-95 font-black uppercase tracking-widest text-xs"
          >
            <Save size={18} />
            {isSaving ? 'Сохранение...' : 'Сохранить'}
          </button>
