import React, { useEffect, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext';
import * as d3 from 'https://cdn.jsdelivr.net/npm/d3@7/+esm';
import { useNavigate } from 'react-router-dom';
import { getTagColor } from '../utils/tagColors';

const GraphView: React.FC = () => {
  const { notes } = useNotes();
  const navigate = useNavigate();
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || notes.length === 0) return;

    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const nodes = notes.map(n => ({ 
        id: n.id, 
        title: n.title, 
        group: n.category,
        isRead: n.isRead,
        isUsed: n.isUsed,
        color: getTagColor(n.category).text
    }));

    const links: any[] = [];
    notes.forEach((n, i) => {
      notes.slice(i + 1).forEach(m => {
        const commonTags = n.tags.filter(t => m.tags.includes(t));
        if (commonTags.length > 0) {
          links.push({ source: n.id, target: m.id, value: commonTags.length + 2 });
        } else if (n.category === m.category) {
          links.push({ source: n.id, target: m.id, value: 1 });
        }
      });
    });

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const simulation = d3.forceSimulation(nodes as any)
      .force("link", d3.forceLink(links).id((d: any) => d.id).distance(150))
      .force("charge", d3.forceManyBody().strength(-300))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(40));

    const g = svg.append("g");

    svg.call(d3.zoom<SVGSVGElement, unknown>()
      .extent([[0, 0], [width, height]])
      .scaleExtent([0.1, 8])
      .on("zoom", (event) => g.attr("transform", event.transform)));

    const link = g.append("g")
      .attr("stroke", "#e5e7eb")
      .attr("stroke-opacity", 0.3)
      .selectAll("line")
      .data(links)
      .join("line")
      .attr("stroke-width", d => Math.sqrt(d.value) * 1.5);

    const nodeContainer = g.append("g")
      .selectAll("g")
      .data(nodes)
      .join("g")
      .attr("cursor", "pointer")
      .on("click", (event, d: any) => navigate(`/editor/${d.id}`))
      .call(d3.drag<any, any>()
        .on("start", (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on("drag", (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on("end", (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        }));

    nodeContainer.append("circle")
      .attr("r", (d: any) => d.isUsed ? 6 : 10)
      .attr("fill", (d: any) => d.color)
      .attr("stroke", "#fff")
      .attr("stroke-width", 3)
      .attr("opacity", (d: any) => d.isRead ? 0.4 : 1)
      .attr("class", "node-circle shadow-xl shadow-blue-500/20");

    nodeContainer.append("text")
      .attr("dy", 22)
      .attr("text-anchor", "middle")
      .attr("font-size", "10px")
      .attr("font-weight", "800")
      .attr("fill", "#111827")
      .text(d => d.title.length > 20 ? d.title.slice(0, 18) + '...' : d.title);

    simulation.on("tick", () => {
      link
        .attr("x1", (d: any) => d.source.x)
        .attr("y1", (d: any) => d.source.y)
        .attr("x2", (d: any) => d.target.x)
        .attr("y2", (d: any) => d.target.y);

      nodeContainer.attr("transform", (d: any) => `translate(${d.x},${d.y})`);
    });

    return () => simulation.stop();
  }, [notes, navigate]);

  return (
    <div className="flex-1 flex flex-col h-screen overflow-hidden bg-white">
      <div className="px-12 py-8 flex justify-between items-center relative z-10 border-b border-gray-50">
        <div>
            <h2 className="text-3xl font-black text-gray-900 leading-none mb-1">Граф Знаний</h2>
            <p className="text-gray-400 text-sm font-bold uppercase tracking-widest">Визуализация нейронных связей</p>
        </div>
        <div className="flex gap-4">
            <div className="bg-gray-50 px-6 py-3 rounded-2xl text-xs font-bold text-gray-500 flex items-center gap-3">
                <span className="w-2 h-2 rounded-full bg-blue-500"></span> {notes.length} Узлов
            </div>
        </div>
      </div>
      <div className="flex-1 relative bg-[radial-gradient(#f1f5f9_1px,transparent_1px)] [background-size:24px_24px]">
        <svg ref={svgRef} className="w-full h-full" />
      </div>
    </div>
  );
};

