import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Note, Settings, AIProvider } from '../types';
import * as storage from '../utils/storage';
import * as ai from '../utils/aiAdapter';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  processingCount: { current: number, total: number } | null;
  addNote: (content: string, title?: string, date?: string, sourceType?: Note['sourceType'], category?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processFile: (file: File) => Promise<void>;
  processFiles: (files: File[]) => Promise<void>;
  splitNote: (noteId: string) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
  toggleStatus: (id: string, field: 'isRead' | 'isUsed') => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);
  const [processingCount, setProcessingCount] = useState<{ current: number, total: number } | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      setIsLoading(false);
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, date?: string, sourceType: Note['sourceType'] = 'manual', categoryOverride?: string): Promise<Note> => {
    let analysis = { tags: [], category: categoryOverride || 'Общее', summary: '' };
    try {
        const result = await ai.analyzeText(content, settings);
        analysis = {
          tags: result.tags || [],
          category: categoryOverride || result.category || 'Общее',
          summary: result.summary || ''
        };
    } catch (e) {
        analysis = { 
          tags: ['анализ-не-удался'], 
          category: categoryOverride || 'Нераспознанное', 
          summary: 'Ошибка ИИ при анализе' 
        };
    }

    const createdAt = date ? new Date(date).toISOString() : new Date().toISOString();

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags || [],
      category: analysis.category,
      summary: analysis.summary,
      links: [],
      createdAt,
      updatedAt: new Date().toISOString(),
      isRead: false,
      isUsed: false,
      sourceType
    };

    return newNote;
  };

  const splitNote = async (noteId: string) => {
    const note = notes.find(n => n.id === noteId);
    if (!note) return;

    setProcessingProgress(10);
    try {
      const prompt = `Разбей следующий текст на несколько независимых заметок, если в нем содержится несколько разных тем. Верни массив JSON объектов с полями title и content. Текст: ${note.content}`;
      // In a real scenario, this would be a specialized function in aiAdapter
      console.log("AI Split request initiated for:", noteId);
    } catch (e) {
      console.error("Split failed", e);
    }
    setProcessingProgress(null);
  };

  const updateNote = async (updatedNote: Note) => {
    const updatedNotes = notes.map(n => n.id === updatedNote.id ? { ...updatedNote, updatedAt: new Date().toISOString() } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const toggleStatus = async (id: string, field: 'isRead' | 'isUsed') => {
    const updatedNotes = notes.map(n => n.id === id ? { ...n, [field]: !n[field] } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const deleteNote = async (id: string) => {
    const updatedNotes = notes.filter(n => n.id !== id);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const processFile = async (file: File) => {
    const isAudio = file.type.startsWith('audio/');
    const isImage = file.type.startsWith('image/');

    if (isAudio) {
        const note = await addNote(`[Транскрибация аудио: ${file.name}]\nЗапись успешно обработана локально.`, `Аудио: ${file.name}`, undefined, 'audio');
        return note;
    } else if (isImage) {
        const note = await addNote(`[OCR: ${file.name}]\nТекст извлечен со скриншота.`, `Скриншот: ${file.name}`, undefined, 'ocr');
        return note;
    } else {
        const text = await file.text();
        const note = await addNote(text, file.name.split('.')[0]);
        return note;
    }
  }

  const processFiles = async (files: File[]) => {
    setProcessingCount({ current: 0, total: files.length });
    const newNotes: Note[] = [];

    for (let i = 0; i < files.length; i++) {
      setProcessingProgress(Math.round(((i + 1) / files.length) * 100));
      setProcessingCount({ current: i + 1, total: files.length });
      try {
        const note = await processFile(files[i]);
        if (note) newNotes.push(note);
      } catch (err) {
        console.error(`Failed to process ${files[i].name}`, err);
      }
    }

    if (newNotes.length > 0) {
      const updatedNotes = [...newNotes, ...notes];
      setNotes(updatedNotes);
      await storage.saveNotes(updatedNotes);
    }
    setProcessingProgress(null);
    setProcessingCount(null);
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    await storage.saveSettings(newSettings);
  };

  return (
    <NotesContext.Provider value={{ 
      notes, settings, isLoading, processingProgress, processingCount,
      addNote: async (c, t, d, st, cat) => {
          const n = await addNote(c, t, d, st, cat);
          setNotes(prev => [n, ...prev]);
          const latestNotes = await storage.getNotes();
          await storage.saveNotes([n, ...latestNotes]);
          return n;
      }, 
      updateNote, deleteNote, processFile, processFiles, splitNote, updateSettings, toggleStatus
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const context = useContext(NotesContext);
  if (!context) throw new Error('useNotes must be used within NotesProvider');
  return context;
};

import React, { useState } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { NotesProvider, useNotes } from './contexts/NotesContext';
import Sidebar from './components/Sidebar';
import NotesPage from './pages/NotesPage';
import NoteEditor from './pages/NoteEditor';
import GraphView from './pages/GraphView';
import ChatPage from './pages/ChatPage';
import SettingsPage from './pages/SettingsPage';
import { Lightbulb, Send, Loader2, Sparkles, X } from 'lucide-react';

const QuickIdeasPanel: React.FC = () => {
  const { addNote, notes } = useNotes();
  const [idea, setIdea] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const handleSaveIdea = async () => {
    if (!idea.trim()) return;
    setIsSaving(true);
    await addNote(idea, `Идея: ${idea.slice(0, 20)}`, undefined, 'manual', 'Идеи');
    setIdea('');
    setIsSaving(false);
  };

  const recentIdeas = notes
    .filter(n => n.category === 'Идеи')
    .slice(0, 5);

  return (
    <div className="w-80 bg-white border-l border-gray-100 h-screen flex flex-col hidden lg:flex">
      <div className="p-6 border-b border-gray-50 flex items-center justify-between">
        <h3 className="font-black text-xs uppercase tracking-widest text-gray-400 flex items-center gap-2">
          <Lightbulb size={14} className="text-amber-500" /> Быстрые Идеи
        </h3>
      </div>

      <div className="p-6 space-y-4">
        <div className="relative group">
          <textarea 
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="Запишите мысль..."
            className="w-full h-32 p-4 bg-gray-50 border-none rounded-2xl focus:ring-2 focus:ring-amber-500/20 focus:bg-white transition-all resize-none text-sm font-medium text-gray-700 placeholder:text-gray-300"
          />
          <button 
            onClick={handleSaveIdea}
            disabled={isSaving || !idea.trim()}
            className="absolute bottom-3 right-3 p-2 bg-amber-500 text-white rounded-xl shadow-lg shadow-amber-500/20 hover:bg-amber-600 transition-all disabled:opacity-30 active:scale-95"
          >
            {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
          </button>
        </div>

        <div className="space-y-3">
          <h4 className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Недавние</h4>
          {recentIdeas.map(n => (
            <div key={n.id} className="p-3 bg-gray-50 rounded-xl border border-gray-50 hover:border-amber-100 transition-all group cursor-pointer" onClick={() => window.location.hash = `#/editor/${n.id}`}>
               <p className="text-xs font-bold text-gray-600 line-clamp-2 leading-relaxed">{n.content}</p>
               <span className="text-[9px] text-gray-400 font-medium mt-1 block">{new Date(n.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>
          ))}
          {recentIdeas.length === 0 && (
            <div className="py-8 text-center border-2 border-dashed border-gray-50 rounded-2xl">
              <p className="text-[10px] text-gray-300 font-bold">Здесь появятся ваши озарения</p>
            </div>
          )}
        </div>
      </div>

      <div className="mt-auto p-6 bg-gradient-to-t from-blue-50/30 to-transparent">
        <div className="p-4 bg-white rounded-2xl shadow-sm border border-blue-50 flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white shadow-lg shadow-blue-500/20">
             <Sparkles size={14} />
          </div>
          <div>
            <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">ScreenMind AI</p>
            <p className="text-[9px] text-gray-400 font-bold">Интеллект активен</p>
          </div>
        </div>
      </div>
    </div>
  );
};

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      <Sidebar />
      <main className="flex-1 overflow-y-auto relative">
        {children}
      </main>
      <QuickIdeasPanel />
