export default App;

import React, { useState, useMemo } from 'react';
import { useNotes } from '../contexts/NotesContext';
import { Note } from '../types';
import { getTagColor } from '../utils/tagColors';
import { 
  Search, Upload as UploadIcon, Trash2, Edit3, Tag as TagIcon, 
  FileText, Download, CheckSquare, Square, XCircle, Loader2,
  Calendar, Layers, Sparkles, Filter, Music, Image as ImageIcon,
  CheckCircle2, Circle, Eye, EyeOff, Bot, ChevronRight
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const NotesPage: React.FC = () => {
  const { notes, processFiles, deleteNote, processingProgress, processingCount, toggleStatus } = useNotes();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [activeTag, setActiveTag] = useState<string | null>(null);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const allTags = useMemo(() => {
    const tags = new Set<string>();
    notes.forEach(n => n.tags.forEach(t => tags.add(t)));
    return Array.from(tags).sort();
  }, [notes]);

  const allCategories = useMemo(() => {
    const cats = new Set<string>();
    notes.forEach(n => cats.add(n.category));
    return Array.from(cats).sort();
  }, [notes]);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const query = search.toLowerCase();
    const matchesSearch = n.title.toLowerCase().includes(query) || 
                         n.content.toLowerCase().includes(query) ||
                         n.category.toLowerCase().includes(query) ||
                         n.tags.some(t => t.toLowerCase().includes(query));
    const matchesTag = !activeTag || n.tags.includes(activeTag);
    const matchesCat = !activeCategory || n.category === activeCategory;
    return matchesSearch && matchesTag && matchesCat;
  }), [notes, search, activeTag, activeCategory]);

  const toggleSelect = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedIds(newSelected);
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = Array.from(e.dataTransfer.files) as File[];
    await processFiles(files);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto min-h-screen relative pb-32">
      {/* Search and Title */}
      <div className="flex flex-col md:flex-row items-end justify-between gap-6 mb-12">
        <div className="space-y-1">
            <div className="flex items-center gap-2 text-blue-600 font-bold text-xs uppercase tracking-widest">
                <Sparkles size={16} /> ScreenMind AI
            </div>
            <h2 className="text-4xl font-black text-gray-900 leading-none">База Знаний</h2>
            <p className="text-gray-400 font-medium">Ваш интеллектуальный второй мозг</p>
        </div>

        <div className="relative w-full md:w-96 group">
          <div className="absolute inset-0 bg-blue-500/5 blur-2xl rounded-3xl opacity-0 group-focus-within:opacity-100 transition-opacity"></div>
          <div className="relative bg-white border border-gray-100 rounded-[1.5rem] shadow-sm flex items-center transition-all focus-within:ring-2 focus-within:ring-blue-500/20">
            <Search className="ml-5 text-gray-300" size={18} />
            <input
              type="text"
              placeholder="Умный поиск..."
              className="w-full px-4 py-4 bg-transparent rounded-[1.5rem] focus:outline-none text-gray-800 font-bold text-sm placeholder:text-gray-300"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Filters Cloud */}
      <div className="space-y-6 mb-12 animate-slide-up">
        <div className="flex flex-wrap gap-2 items-center">
            <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest mr-4">
                <Filter size={12} /> Темы:
            </div>
            <button 
                onClick={() => setActiveCategory(null)}
                className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${!activeCategory ? 'bg-gray-900 text-white shadow-lg' : 'bg-white text-gray-400 hover:bg-gray-50 border border-gray-100'}`}
            >
                Bce
            </button>
            {allCategories.map(cat => (
                <button 
                    key={cat}
                    onClick={() => setActiveCategory(activeCategory === cat ? null : cat)}
                    className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border transition-all ${activeCategory === cat ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-500/20' : 'bg-white border-gray-100 text-gray-500 hover:border-blue-200'}`}
                >
                    {cat}
                </button>
            ))}
        </div>

        <div className="flex flex-wrap gap-2 items-center">
            <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest mr-4">
                <TagIcon size={12} /> Теги:
            </div>
            {allTags.slice(0, 15).map(tag => {
                const colors = getTagColor(tag);
                const isActive = activeTag === tag;
                return (
                    <button 
                        key={tag}
                        onClick={() => setActiveTag(isActive ? null : tag)}
                        style={{ 
                            backgroundColor: isActive ? colors.text : 'white',
                            color: isActive ? 'white' : colors.text,
                            borderColor: isActive ? colors.text : colors.border
                        }}
                        className="px-3 py-1.5 rounded-xl text-[10px] font-black border transition-all hover:scale-105"
                    >
                        #{tag}
                    </button>
                );
            })}
        </div>
      </div>

      {/* Upload Progress */}
      {processingProgress !== null && (
        <div className="mb-12 p-8 bg-blue-600 text-white rounded-[2.5rem] shadow-2xl shadow-blue-500/30 overflow-hidden relative">
          <div className="absolute bottom-0 left-0 h-1 bg-white/30 transition-all duration-500" style={{ width: `${processingProgress}%` }}></div>
          <div className="flex items-center gap-8">
            <div className="p-4 bg-white/10 rounded-3xl backdrop-blur-md">
              <Loader2 className="animate-spin" size={32} />
            </div>
            <div className="flex-1">
              <h3 className="text-xl font-black mb-1">Идет обработка...</h3>
              <p className="text-blue-100 font-bold text-sm">
                Файл {processingCount?.current} из {processingCount?.total} ({processingProgress}%)
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Main Grid */}
      <div 
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 transition-all ${isDragging ? 'scale-95 opacity-50 blur-sm' : ''}`}
      >
        {filteredNotes.map((note) => {
          const isSelected = selectedIds.has(note.id);
          const colors = getTagColor(note.category);
          return (
            <div 
              key={note.id}
              onClick={() => selectedIds.size > 0 ? toggleSelect(note.id) : navigate(`/editor/${note.id}`)}
              className={`group bg-white p-8 rounded-[2rem] border transition-all cursor-pointer relative flex flex-col h-[24rem] ${
                isSelected 
                  ? 'border-blue-500 ring-4 ring-blue-500/5 shadow-2xl scale-[1.02]' 
                  : 'border-gray-100 hover:border-blue-300 hover:shadow-[0_20px_50px_rgba(0,0,0,0.04)] shadow-sm'
              } ${note.isRead ? 'opacity-70 grayscale-[0.3]' : ''}`}
            >
              {/* Controls */}
              <div className="absolute top-6 right-6 z-10 flex gap-1 opacity-0 group-hover:opacity-100 transition-all">
                <button 
                  onClick={(e) => { e.stopPropagation(); toggleStatus(note.id, 'isRead'); }}
                  className={`p-2 rounded-xl border transition-all ${note.isRead ? 'bg-blue-50 border-blue-100 text-blue-600' : 'bg-white border-gray-50 text-gray-300'}`}
                >
                  <Eye size={16} />
                </button>
                <button 
                  onClick={(e) => toggleSelect(note.id, e)}
                  className={`p-2 rounded-xl border transition-all ${isSelected ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-gray-50 text-gray-300'}`}
                >
                  <CheckSquare size={16} />
                </button>
              </div>

              <div className="mb-6 flex items-center gap-3">
                <span 
                  style={{ backgroundColor: colors.bg, color: colors.text, borderColor: colors.border }}
                  className="text-[9px] font-black uppercase tracking-widest px-3 py-1.5 rounded-xl border"
                >
                  {note.category}
                </span>
                <span className="text-[9px] text-gray-300 font-bold flex items-center gap-1">
                   <Calendar size={10} /> {new Date(note.createdAt).toLocaleDateString('ru-RU')}
                </span>
              </div>

              <h3 className="font-extrabold text-xl text-gray-900 mb-4 line-clamp-2 leading-tight group-hover:translate-x-1 transition-transform">
                  {note.title}
              </h3>

              <div className="relative flex-1 overflow-hidden">
                  <p className="text-sm text-gray-500 leading-relaxed line-clamp-5">
                      {note.summary && <span className="italic text-gray-400 block mb-2 border-l-2 border-blue-50 pl-3">"{note.summary}"</span>}
                      {note.content}
                  </p>
                  <div className="absolute bottom-0 left-0 right-0 h-16 bg-gradient-to-t from-white to-transparent"></div>
              </div>

              <div className="flex flex-wrap gap-1.5 mt-8 pt-6 border-t border-gray-50">
                {note.tags.slice(0, 4).map(tag => {
                  const tColors = getTagColor(tag);
                  return (
                      <span 
                          key={tag} 
                          style={{ color: tColors.text }}
                          className="text-[9px] font-black transition-colors hover:underline"
                      >
                          #{tag}
                      </span>
                  );
                })}
                <div className="ml-auto flex items-center text-gray-300 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
                   <span className="text-[10px] font-black uppercase tracking-widest mr-1">Читать</span>
                   <ChevronRight size={14} />
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Floating Action Bar */}
      {selectedIds.size > 0 && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-gray-900 text-white shadow-[0_30px_100px_rgba(0,0,0,0.3)] rounded-[2.5rem] px-12 py-6 flex items-center gap-12 animate-slide-up z-50">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Объектов</span>
            <span className="text-3xl font-black">{selectedIds.size}</span>
          </div>
          <div className="h-10 w-px bg-white/10"></div>
          <div className="flex gap-4">
            <button className="flex items-center gap-3 bg-blue-600 px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black text-xs uppercase tracking-widest">
              Действия
            </button>
            <button onClick={() => setSelectedIds(new Set())} className="p-3 text-white/50 hover:text-white transition-all">
                <XCircle size={24} />
            </button>
          </div>
        </div>
      )}

      {/* Drag overlay hint */}
      {isDragging && (
        <div className="fixed inset-0 z-50 pointer-events-none flex items-center justify-center bg-blue-600/10 backdrop-blur-sm border-4 border-dashed border-blue-600 m-8 rounded-[4rem]">
            <div className="bg-white p-12 rounded-[3rem] shadow-2xl flex flex-col items-center gap-6 animate-bounce">
                <UploadIcon size={64} className="text-blue-600" />
                <p className="text-2xl font-black text-gray-900 uppercase tracking-tight">Бросьте файлы здесь</p>
            </div>
        </div>
      )}
    </div>
  );
};

