import React, { useEffect, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext';
import * as d3 from 'https://cdn.jsdelivr.net/npm/d3@7/+esm';
import { useNavigate } from 'react-router-dom';
import { getTagColor } from '../utils/tagColors';
import { BrainCircuit, Maximize2, RotateCcw } from 'lucide-react';

const GraphView: React.FC = () => {
  const { notes } = useNotes();
  const navigate = useNavigate();
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current || notes.length === 0) return;

    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const nodes = notes.map(n => ({ 
        id: n.id, 
        title: n.title, 
        group: n.category,
        isRead: n.isRead,
        isUsed: n.isUsed,
        tags: n.tags,
        color: getTagColor(n.category).text
    }));

    const links: any[] = [];
    notes.forEach((n, i) => {
      notes.slice(i + 1).forEach(m => {
        const commonTags = n.tags.filter(t => m.tags.includes(t));
        if (commonTags.length > 0) {
          links.push({ source: n.id, target: m.id, value: commonTags.length + 3 });
        } else if (n.category === m.category) {
          links.push({ source: n.id, target: m.id, value: 1.5 });
        }
      });
    });

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    // Definitions for filters and gradients
    const defs = svg.append("defs");
    const glow = defs.append("filter")
        .attr("id", "glow")
        .append("feGaussianBlur")
        .attr("stdDeviation", "2.5")
        .attr("result", "coloredBlur");

    const simulation = d3.forceSimulation(nodes as any)
      .force("link", d3.forceLink(links).id((d: any) => d.id).distance(180))
      .force("charge", d3.forceManyBody().strength(-400))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(60));

    const g = svg.append("g");

    svg.call(d3.zoom<SVGSVGElement, unknown>()
      .extent([[0, 0], [width, height]])
      .scaleExtent([0.1, 8])
      .on("zoom", (event) => g.attr("transform", event.transform)));

    const link = g.append("g")
      .attr("stroke", "#cbd5e1")
      .attr("stroke-opacity", 0.4)
      .selectAll("line")
      .data(links)
      .join("line")
      .attr("stroke-width", d => Math.sqrt(d.value) * 1.5)
      .attr("stroke-dasharray", d => d.value < 2 ? "4 4" : "0");

    const nodeContainer = g.append("g")
      .selectAll("g")
      .data(nodes)
      .join("g")
      .attr("cursor", "pointer")
      .on("click", (event, d: any) => navigate(`/editor/${d.id}`))
      .call(d3.drag<any, any>()
        .on("start", (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on("drag", (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on("end", (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        }));

    // Hover effect background circle
    nodeContainer.append("circle")
      .attr("r", 25)
      .attr("fill", (d: any) => d.color)
      .attr("opacity", 0)
      .attr("class", "hover-ring transition-all group-hover:opacity-10");

    nodeContainer.append("circle")
      .attr("r", (d: any) => d.isUsed ? 7 : 12)
      .attr("fill", (d: any) => d.color)
      .attr("stroke", "#fff")
      .attr("stroke-width", 3)
      .attr("opacity", (d: any) => d.isRead ? 0.3 : 1)
      .attr("filter", "url(#glow)");

    const textGroup = nodeContainer.append("g")
        .attr("transform", "translate(0, 28)");

    textGroup.append("text")
      .attr("text-anchor", "middle")
      .attr("font-size", "11px")
      .attr("font-weight", "900")
      .attr("fill", "#1e293b")
      .text(d => d.title.length > 25 ? d.title.slice(0, 22) + '...' : d.title);

    textGroup.append("text")
      .attr("dy", 12)
      .attr("text-anchor", "middle")
      .attr("font-size", "8px")
      .attr("font-weight", "700")
      .attr("fill", (d: any) => d.color)
      .attr("class", "uppercase tracking-widest")
      .text(d => d.group);

    simulation.on("tick", () => {
      link
        .attr("x1", (d: any) => d.source.x)
        .attr("y1", (d: any) => d.source.y)
        .attr("x2", (d: any) => d.target.x)
        .attr("y2", (d: any) => d.target.y);

      nodeContainer.attr("transform", (d: any) => `translate(${d.x},${d.y})`);
    });

    return () => simulation.stop();
  }, [notes, navigate]);

  return (
    <div className="flex-1 flex flex-col h-screen overflow-hidden bg-white">
      <div className="px-12 py-10 flex justify-between items-end relative z-10">
        <div className="space-y-1">
            <h2 className="text-3xl font-black text-gray-900 leading-none">Нейронная Сеть</h2>
            <p className="text-gray-400 text-[10px] font-black uppercase tracking-[0.2em]">Матрица связей ваших знаний</p>
        </div>
        <div className="flex gap-4">
            <button className="p-3 bg-gray-50 text-gray-400 hover:text-gray-900 rounded-2xl transition-all"><RotateCcw size={18} /></button>
            <button className="p-3 bg-gray-50 text-gray-400 hover:text-gray-900 rounded-2xl transition-all"><Maximize2 size={18} /></button>
            <div className="bg-blue-600 px-6 py-3 rounded-2xl text-[10px] font-black text-white flex items-center gap-3 shadow-xl shadow-blue-500/20 uppercase tracking-widest">
                <BrainCircuit size={16} /> {notes.length} объектов
            </div>
        </div>
      </div>
      <div className="flex-1 relative bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] [background-size:32px_32px]">
        <svg ref={svgRef} className="w-full h-full" />
      </div>
    </div>
  );
};

