import { Settings, AIProvider } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

const getBaseUrl = (url: string) => url.replace(/\/$/, '');

/**
 * Extracts JSON from a string that might contain other text or markdown blocks.
 */
const extractJSON = (str: string) => {
  try {
    // Attempt direct parse first
    return JSON.parse(str);
  } catch (e) {
    // Try to find JSON block in markdown
    const match = str.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (innerE) {
        throw new Error("Не удалось извлечь валидный JSON из ответа ИИ");
      }
    }
    throw new Error("Ответ ИИ не содержит JSON");
  }
};

export const testConnection = async (settings: Settings): Promise<boolean> => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: 'ping',
      });
      return !!response.text;
    }

    const baseUrl = getBaseUrl(settings.url);
    const endpoint = settings.provider === AIProvider.Ollama 
      ? `${baseUrl}/api/tags` 
      : `${baseUrl}/models`;

    const response = await fetch(endpoint, {
      method: 'GET',
      mode: 'cors',
      headers: settings.apiKey ? { 'Authorization': `Bearer ${settings.apiKey}` } : {}
    });
    return response.ok;
  } catch (e: any) {
    console.error('Connection test failed:', e);
    return false;
  }
};

export const analyzeText = async (text: string, settings: Settings) => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Проанализируй следующий текст и верни структурированные данные в JSON формате. 
        Не добавляй никаких пояснений, только JSON.
        Текст для анализа:\n\n${text}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              tags: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
                description: 'Список релевантных тегов',
              },
              category: {
                type: Type.STRING,
                description: 'Категория контента',
              },
              summary: {
                type: Type.STRING,
                description: 'Краткое резюме одной фразой',
              }
            },
            required: ["tags", "category", "summary"]
          }
        }
      });
      return extractJSON(response.text || '{}');
    }

    const baseUrl = getBaseUrl(settings.url);
    const prompt = `Проанализируй следующий текст и верни ТОЛЬКО JSON без пояснений и без markdown разметки:
{
  "tags": ["тег1", "тег2"],
  "category": "НазваниеКатегории",
  "summary": "Краткое содержание"
}
Текст: ${text}`;

    let url = '';
    let body: any = {};
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };

    if (settings.provider === AIProvider.Ollama) {
      url = `${baseUrl}/api/generate`;
      body = {
        model: settings.model,
        prompt,
        stream: false,
        format: 'json'
      };
    } else {
      url = `${baseUrl}/chat/completions`;
      headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
      body = {
        model: settings.model,
        messages: [{ role: 'system', content: 'You are a helpful assistant that only outputs JSON.' }, { role: 'user', content: prompt }],
        response_format: { type: 'json_object' }
      };
    }

    const response = await fetch(url, {
      method: 'POST',
      mode: 'cors',
      headers,
      body: JSON.stringify(body)
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Ошибка сервера (${response.status}): ${errorText.slice(0, 100)}`);
    }

    const data = await response.json();
    let resultStr = '';

    if (settings.provider === AIProvider.Ollama) {
      resultStr = data.response;
    } else {
      resultStr = data.choices[0].message.content;
    }

    return extractJSON(resultStr);
  } catch (e: any) {
    if (e.name === 'TypeError' && e.message === 'Failed to fetch') {
      throw new Error('Не удалось подключиться к ИИ-серверу. Проверьте, запущен ли сервис (Ollama/LM Studio) и настроен ли CORS (OLLAMA_ORIGINS="*").');
    }
    console.error('AI Analysis Error:', e);
    throw e;
  }
};

export const chatWithNotes = async (question: string, context: string, settings: Settings) => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Ты — ScreenMind2 AI. Твоя база знаний состоит из следующих заметок:\n---\n${context}\n---\nОтветь на вопрос пользователя, используя эти данные. Если информации нет, скажи об этом.\nВопрос: ${question}`,
      });
      return response.text;
    }

    const baseUrl = getBaseUrl(settings.url);
    const prompt = `Ты — ScreenMind2 AI. Твоя база знаний состоит из следующих заметок:
---
${context}
---
Ответь на вопрос пользователя, используя эти данные. Если информации нет, скажи об этом.
Вопрос: ${question}`;

    let url = '';
    let body: any = {};
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };

    if (settings.provider === AIProvider.Ollama) {
      url = `${baseUrl}/api/generate`;
      body = { model: settings.model, prompt, stream: false };
    } else {
      url = `${baseUrl}/chat/completions`;
      headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
      body = {
        model: settings.model,
        messages: [{ role: 'user', content: prompt }]
      };
    }

    const response = await fetch(url, { method: 'POST', mode: 'cors', headers, body: JSON.stringify(body) });
    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Ошибка чата (${response.status}): ${errorText.slice(0, 100)}`);
    }

    const data = await response.json();
    if (settings.provider === AIProvider.Ollama) return data.response;
    return data.choices[0].message.content;
  } catch (e: any) {
    if (e.name === 'TypeError' && e.message === 'Failed to fetch') {
      throw new Error('Ошибка подключения к ИИ для чата. Проверьте настройки URL и CORS.');
    }
    throw e;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { useNotes } from '../contexts/NotesContext';
import { Send, Bot, User, Eraser, AlertCircle } from 'lucide-react';
import * as ai from '../utils/aiAdapter';
import { ChatMessage } from '../types';

const ChatPage: React.FC = () => {
  const { notes, settings } = useNotes();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage: ChatMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    const context = notes.map(n => `[ID: ${n.id}] ${n.title}: ${n.content}`).join('\n\n');

    try {
      const response = await ai.chatWithNotes(input, context, settings);

      const sources = notes.filter(n => response.includes(n.id)).map(n => n.id);

      const aiMessage: ChatMessage = { 
        role: 'assistant', 
        content: response || 'Пустой ответ от ИИ.',
        sources: sources.length > 0 ? sources : undefined
      };
      setMessages(prev => [...prev, aiMessage]);
    } catch (e: any) {
      setMessages(prev => [...prev, { 
        role: 'assistant', 
        content: `Ошибка: ${e.message || 'Произошла непредвиденная ошибка при обращении к ИИ.'}` 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-screen max-w-4xl mx-auto p-4">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <Bot className="text-blue-600" />
          Интеллектуальный чат
        </h2>
        <button 
          onClick={() => setMessages([])}
          className="text-gray-400 hover:text-red-500 flex items-center gap-1 text-sm transition-colors"
        >
          <Eraser size={16} /> Очистить
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 mb-6 px-2 scroll-smooth">
        {messages.length === 0 && (
          <div className="text-center py-20 text-gray-400 font-medium">
            <p>Задайте вопрос по вашей базе знаний.</p>
            <p className="text-sm mt-2 italic text-gray-300">Например: "Какие идеи у меня были на прошлой неделе?"</p>
          </div>
        )}

        {messages.map((m, i) => (
          <div key={i} className={`flex gap-4 ${m.role === 'assistant' ? 'flex-row' : 'flex-row-reverse'}`}>
            <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${
              m.role === 'assistant' ? 'bg-blue-50 text-blue-600' : 'bg-gray-100 text-gray-600'
            }`}>
              {m.role === 'assistant' ? <Bot size={18} /> : <User size={18} />}
            </div>
            <div className={`max-w-[85%] rounded-[1.5rem] px-5 py-4 ${
              m.role === 'assistant' 
                ? 'bg-white border border-gray-100 shadow-sm text-gray-800' 
                : 'bg-blue-600 text-white shadow-lg shadow-blue-500/20'
            }`}>
              {m.content.startsWith('Ошибка:') ? (
                <div className="flex items-start gap-2 text-red-500 font-medium">
                  <AlertCircle size={18} className="shrink-0 mt-0.5" />
                  <p className="whitespace-pre-wrap leading-relaxed">{m.content}</p>
                </div>
              ) : (
                <p className="whitespace-pre-wrap leading-relaxed">{m.content}</p>
              )}

              {m.sources && (
                <div className="mt-4 pt-4 border-t border-gray-100">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Источники знаний</span>
                  <div className="flex flex-wrap gap-2">
                    {m.sources.map(sId => {
                      const n = notes.find(note => note.id === sId);
                      return n ? (
                        <span key={sId} className="text-[10px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-lg border border-blue-100/50">
                          {n.title}
                        </span>
                      ) : null;
                    })}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex gap-4 animate-pulse">
            <div className="w-8 h-8 rounded-xl bg-blue-50 flex items-center justify-center text-blue-600">
              <Bot size={18} />
            </div>
            <div className="bg-white border border-gray-100 px-6 py-4 rounded-[1.5rem] flex gap-1.5 shadow-sm">
              <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></span>
              <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.2s]"></span>
              <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.4s]"></span>
            </div>
          </div>
        )}
      </div>

      <div className="relative group">
        <div className="absolute inset-0 bg-blue-500/5 blur-xl rounded-[2rem] opacity-0 group-focus-within:opacity-100 transition-opacity"></div>
        <textarea
          className="w-full bg-white border border-gray-100 rounded-[2rem] pl-6 pr-16 py-5 focus:outline-none focus:ring-2 focus:ring-blue-500/20 shadow-xl shadow-gray-200/20 resize-none font-medium text-gray-800 placeholder:text-gray-300"
          placeholder="Спросите ScreenMind AI..."
