          className="absolute right-4 top-1/2 -translate-y-1/2 p-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-500/20 active:scale-95 disabled:opacity-30 disabled:pointer-events-none"
        >
          <Send size={20} />
        </button>
      </div>
    </div>
  );
