import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Note, Settings, AIProvider } from '../types';
import * as storage from '../utils/storage';
import * as ai from '../utils/aiAdapter';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  processingCount: { current: number, total: number } | null;
  addNote: (content: string, title?: string, date?: string, sourceType?: Note['sourceType'], category?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  // Fix: processFile should return Promise<Note> to match internal implementation and allow consumers to access the result
  processFile: (file: File) => Promise<Note>;
  processFiles: (files: File[]) => Promise<void>;
  splitNote: (noteId: string) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
  toggleStatus: (id: string, field: 'isRead' | 'isUsed') => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);
  const [processingCount, setProcessingCount] = useState<{ current: number, total: number } | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      setIsLoading(false);
    };
    init();
  }, []);

  // Use internal naming to prevent shadowing during context value definition
  const addNoteInternal = async (content: string, title?: string, date?: string, sourceType: Note['sourceType'] = 'manual', categoryOverride?: string): Promise<Note> => {
    let analysis = { tags: [], category: categoryOverride || 'Общее', summary: '' };
    try {
        const result = await ai.analyzeText(content, settings);
        analysis = {
          tags: result.tags || [],
          category: categoryOverride || result.category || 'Общее',
          summary: result.summary || ''
        };
    } catch (e) {
        analysis = { 
          tags: ['анализ-не-удался'], 
          category: categoryOverride || 'Нераспознанное', 
          summary: 'Ошибка ИИ при анализе' 
        };
    }

    const createdAt = date ? new Date(date).toISOString() : new Date().toISOString();

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags || [],
      category: analysis.category,
      summary: analysis.summary,
      links: [],
      createdAt,
      updatedAt: new Date().toISOString(),
      isRead: false,
      isUsed: false,
      sourceType
    };

    return newNote;
  };

  const splitNote = async (noteId: string) => {
    const note = notes.find(n => n.id === noteId);
    if (!note) return;

    setProcessingProgress(10);
    try {
      const prompt = `Разбей следующий текст на несколько независимых заметок, если в нем содержится несколько разных тем. Верни массив JSON объектов with fields title and content. Текст: ${note.content}`;
      // In a real scenario, this would be a specialized function in aiAdapter
      console.log("AI Split request initiated for:", noteId);
    } catch (e) {
      console.error("Split failed", e);
    }
    setProcessingProgress(null);
  };

  const updateNote = async (updatedNote: Note) => {
    const updatedNotes = notes.map(n => n.id === updatedNote.id ? { ...updatedNote, updatedAt: new Date().toISOString() } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const toggleStatus = async (id: string, field: 'isRead' | 'isUsed') => {
    const updatedNotes = notes.map(n => n.id === id ? { ...n, [field]: !n[field] } : n);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  const deleteNote = async (id: string) => {
    const updatedNotes = notes.filter(n => n.id !== id);
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
  };

  // Use internal naming to prevent shadowing
  const processFileInternal = async (file: File) => {
    const isAudio = file.type.startsWith('audio/');
    const isImage = file.type.startsWith('image/');

    if (isAudio) {
        const note = await addNoteInternal(`[Транскрибация аудио: ${file.name}]\nЗапись успешно обработана локально.`, `Аудио: ${file.name}`, undefined, 'audio');
        return note;
    } else if (isImage) {
        const note = await addNoteInternal(`[OCR: ${file.name}]\nТекст извлечен со скриншота.`, `Скриншот: ${file.name}`, undefined, 'ocr');
        return note;
    } else {
        const text = await file.text();
        const note = await addNoteInternal(text, file.name.split('.')[0]);
        return note;
    }
  }

  const processFiles = async (files: File[]) => {
    setProcessingCount({ current: 0, total: files.length });
    const newNotes: Note[] = [];

    for (let i = 0; i < files.length; i++) {
      setProcessingProgress(Math.round(((i + 1) / files.length) * 100));
      setProcessingCount({ current: i + 1, total: files.length });
      try {
        const note = await processFileInternal(files[i]);
        if (note) newNotes.push(note);
      } catch (err) {
        console.error(`Failed to process ${files[i].name}`, err);
      }
    }

    if (newNotes.length > 0) {
      const updatedNotes = [...newNotes, ...notes];
      setNotes(updatedNotes);
      await storage.saveNotes(updatedNotes);
    }
    setProcessingProgress(null);
    setProcessingCount(null);
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    await storage.saveSettings(newSettings);
  };

  return (
    <NotesContext.Provider value={{ 
      notes, settings, isLoading, processingProgress, processingCount,
      addNote: async (c, t, d, st, cat) => {
          const n = await addNoteInternal(c, t, d, st, cat);
          setNotes(prev => [n, ...prev]);
          const latestNotes = await storage.getNotes();
          await storage.saveNotes([n, ...latestNotes]);
          return n;
      }, 
      updateNote, 
      deleteNote, 
      // Fix: Wrapping internal processFile to handle state updates and side effects when called individually
      processFile: async (file) => {
          const n = await processFileInternal(file);
          setNotes(prev => [n, ...prev]);
          const latestNotes = await storage.getNotes();
          await storage.saveNotes([n, ...latestNotes]);
          return n;
      },
      processFiles, 
      splitNote, 
      updateSettings, 
      toggleStatus
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const context = useContext(NotesContext);
  if (!context) throw new Error('useNotes must be used within NotesProvider');
  return context;
};

