import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider } from '../types';
import * as storage from '../utils/storage';
import * as ai from '../utils/aiAdapter';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  processingCount: { current: number, total: number } | null;
  addNote: (content: string, title?: string, date?: string, sourceType?: Note['sourceType'], category?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processFile: (file: File) => Promise<Note>;
  processFiles: (files: File[]) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
  toggleStatus: (id: string, field: 'isRead' | 'isUsed') => Promise<void>;
  toggleTheme: () => void;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);
  const [processingCount, setProcessingCount] = useState<{ current: number, total: number } | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      document.documentElement.classList.toggle('dark', storedSettings.theme === 'dark');
      setIsLoading(false);
    };
    init();
  }, []);

  const addNoteInternal = async (content: string, title?: string, date?: string, sourceType: Note['sourceType'] = 'manual', categoryOverride?: string): Promise<Note> => {
    let analysis = { tags: [], category: categoryOverride || 'Общее', summary: '' };
    try {
        const result = await ai.analyzeText(content, settings);
        analysis = {
          tags: result.tags || [],
          category: categoryOverride || result.category || 'Общее',
          summary: result.summary || ''
        };
    } catch (e) {
        analysis = { 
          tags: ['анализ-не-удался'], 
          category: categoryOverride || 'Нераспознанное', 
          summary: 'Ошибка ИИ при анализе' 
        };
    }

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags,
      category: analysis.category,
      summary: analysis.summary,
      links: [],
      createdAt: date || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      isRead: false,
      isUsed: false,
      sourceType
    };
    return newNote;
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    document.documentElement.classList.toggle('dark', newSettings.theme === 'dark');
    await storage.saveSettings(newSettings);
  };

  const toggleTheme = () => {
    const newTheme = settings.theme === 'light' ? 'dark' : 'light';
    updateSettings({ ...settings, theme: newTheme });
  };

  const processFileInternal = async (file: File) => {
    if (file.type.startsWith('image/')) {
        return await addNoteInternal(`[OCR: ${file.name}]\nТекст извлечен со скриншота.`, `Скриншот: ${file.name}`, undefined, 'ocr');
    } else if (file.type.startsWith('audio/')) {
        return await addNoteInternal(`[Аудио: ${file.name}]\nТранскрибация будет доступна после обработки моделью ${settings.transcriptionModel}.`, `Запись: ${file.name}`, undefined, 'audio');
    }
    const text = await file.text();
    return await addNoteInternal(text, file.name.split('.')[0]);
  }

  const value: NotesContextType = {
    notes, settings, isLoading, processingProgress, processingCount,
    addNote: async (c, t, d, st, cat) => {
      const n = await addNoteInternal(c, t, d, st, cat);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    updateNote: async (n) => {
      const updated = notes.map(x => x.id === n.id ? { ...n, updatedAt: new Date().toISOString() } : x);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    deleteNote: async (id) => {
      const updated = notes.filter(x => x.id !== id);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    processFile: async (f) => {
      const n = await processFileInternal(f);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    processFiles: async (files) => {
      setProcessingCount({ current: 0, total: files.length });
      const newOnes: Note[] = [];
      for (let i = 0; i < files.length; i++) {
        setProcessingProgress(Math.round(((i + 1) / files.length) * 100));
        setProcessingCount({ current: i + 1, total: files.length });
        try {
          const n = await processFileInternal(files[i]);
          newOnes.push(n);
        } catch (e) { console.error(e); }
      }
      if (newOnes.length > 0) {
        const up = [...newOnes, ...notes];
        setNotes(up);
        await storage.saveNotes(up);
      }
      setProcessingProgress(null);
      setProcessingCount(null);
    },
    updateSettings,
    toggleStatus: async (id, field) => {
      const up = notes.map(n => n.id === id ? { ...n, [field]: !n[field] } : n);
      setNotes(up);
      await storage.saveNotes(up);
    },
    toggleTheme
  };

  return <NotesContext.Provider value={value}>{children}</NotesContext.Provider>;
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error('useNotes must be used within NotesProvider');
  return c;
};

