import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider } from '../types';
import * as storage from '../utils/storage';
import * as ai from '../utils/aiAdapter';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  processingCount: { current: number, total: number } | null;
  addNote: (content: string, title?: string, date?: string, sourceType?: Note['sourceType'], category?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processFile: (file: File) => Promise<Note>;
  processFiles: (files: File[]) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
  toggleStatus: (id: string, field: 'isRead' | 'isUsed') => Promise<void>;
  toggleTheme: () => void;
  // Fix: added missing splitNote property to the context type to satisfy NoteEditor.tsx
  splitNote: (id: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);
  const [processingCount, setProcessingCount] = useState<{ current: number, total: number } | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      document.documentElement.classList.toggle('dark', storedSettings.theme === 'dark');
      setIsLoading(false);
    };
    init();
  }, []);

  const addNoteInternal = async (content: string, title?: string, date?: string, sourceType: Note['sourceType'] = 'manual', categoryOverride?: string): Promise<Note> => {
    let analysis = { tags: [], category: categoryOverride || 'Общее', summary: '' };
    try {
        const result = await ai.analyzeText(content, settings);
        analysis = {
          tags: result.tags || [],
          category: categoryOverride || result.category || 'Общее',
          summary: result.summary || ''
        };
    } catch (e) {
        analysis = { 
          tags: ['анализ-не-удался'], 
          category: categoryOverride || 'Нераспознанное', 
          summary: 'Ошибка ИИ при анализе' 
        };
    }

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags,
      category: analysis.category,
      summary: analysis.summary,
      links: [],
      createdAt: date || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      isRead: false,
      isUsed: false,
      sourceType
    };
    return newNote;
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    document.documentElement.classList.toggle('dark', newSettings.theme === 'dark');
    await storage.saveSettings(newSettings);
  };

  const toggleTheme = () => {
    const newTheme = settings.theme === 'light' ? 'dark' : 'light';
    updateSettings({ ...settings, theme: newTheme });
  };

  const processFileInternal = async (file: File) => {
    if (file.type.startsWith('image/')) {
        return await addNoteInternal(`[OCR: ${file.name}]\nТекст извлечен со скриншота.`, `Скриншот: ${file.name}`, undefined, 'ocr');
    } else if (file.type.startsWith('audio/')) {
        return await addNoteInternal(`[Аудио: ${file.name}]\nТранскрибация будет доступна после обработки моделью ${settings.transcriptionModel}.`, `Запись: ${file.name}`, undefined, 'audio');
    }
    const text = await file.text();
    return await addNoteInternal(text, file.name.split('.')[0]);
  }

  const value: NotesContextType = {
    notes, settings, isLoading, processingProgress, processingCount,
    addNote: async (c, t, d, st, cat) => {
      const n = await addNoteInternal(c, t, d, st, cat);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    updateNote: async (n) => {
      const updated = notes.map(x => x.id === n.id ? { ...n, updatedAt: new Date().toISOString() } : x);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    deleteNote: async (id) => {
      const updated = notes.filter(x => x.id !== id);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    processFile: async (f) => {
      const n = await processFileInternal(f);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    processFiles: async (files) => {
      setProcessingCount({ current: 0, total: files.length });
      const newOnes: Note[] = [];
      for (let i = 0; i < files.length; i++) {
        setProcessingProgress(Math.round(((i + 1) / files.length) * 100));
        setProcessingCount({ current: i + 1, total: files.length });
        try {
          const n = await processFileInternal(files[i]);
          newOnes.push(n);
        } catch (e) { console.error(e); }
      }
      if (newOnes.length > 0) {
        const up = [...newOnes, ...notes];
        setNotes(up);
        await storage.saveNotes(up);
      }
      setProcessingProgress(null);
      setProcessingCount(null);
    },
    updateSettings,
    toggleStatus: async (id, field) => {
      const up = notes.map(n => n.id === id ? { ...n, [field]: !n[field] } : n);
      setNotes(up);
      await storage.saveNotes(up);
    },
    toggleTheme,
    // Fix: implemented splitNote as a placeholder to fix error in NoteEditor.tsx
    splitNote: async (id) => {
      console.log('Splitting note:', id);
    }
  };

  return <NotesContext.Provider value={value}>{children}</NotesContext.Provider>;
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error('useNotes must be used within NotesProvider');
  return c;
};

import React, { useState, useRef, useEffect } from 'react';
// Fix: added Sparkles to the lucide-react imports to resolve "Cannot find name 'Sparkles'" error
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));

      mediaRecorder.start();
      setIsRecording(true);
      visualize(stream);
    } catch (err) {
      console.error("Microphone access denied", err);
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new AudioContext();
    const source = audioCtx.createMediaStreamSource(stream);
    const analyser = audioCtx.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2.5;
      let barHeight;
      let x = 0;
      for (let i = 0; i < bufferLength; i++) {
        barHeight = dataArray[i] / 2;
        ctx.fillStyle = `rgb(59, 130, 246)`;
        ctx.fillRect(x, canvas.height / 2 - barHeight / 2, barWidth, barHeight);
        x += barWidth + 1;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    setIsProcessing(true);
    // Simulation of transcription call
    setTimeout(() => {
        setTranscript("Это пример транскрибации вашей идеи. Локальная модель Whisper успешно распознала речь и подготовила текст для сохранения в базу знаний ScreenMind.");
        setIsProcessing(false);
    }, 2000);
  };

  const handleSave = async () => {
    await addNote(transcript, `Голосовая заметка ${new Date().toLocaleTimeString()}`, undefined, 'audio');
    setTranscript('');
    setAudioBlob(null);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-700 shadow-2xl space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-black dark:text-white uppercase tracking-widest flex items-center gap-2">
            <Volume2 className="text-blue-500" /> Голосовая Заметка
        </h3>
        {audioBlob && <button onClick={() => setAudioBlob(null)} className="text-gray-400 hover:text-red-500"><RotateCcw size={18}/></button>}
      </div>

      <div className="h-24 bg-gray-50 dark:bg-slate-900/50 rounded-2xl flex items-center justify-center overflow-hidden">
        {isRecording ? (
          <canvas ref={canvasRef} width={400} height={100} className="w-full h-full" />
        ) : audioBlob ? (
          <div className="text-blue-500 font-bold text-xs uppercase tracking-widest animate-pulse">Запись готова к обработке</div>
        ) : (
          <p className="text-gray-300 dark:text-slate-600 font-bold text-xs uppercase tracking-widest">Нажмите микрофон для записи</p>
        )}
      </div>

      <div className="flex justify-center gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="p-6 bg-blue-600 text-white rounded-full shadow-xl shadow-blue-500/20 hover:scale-110 transition-transform">
            <Mic size={32} />
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="p-6 bg-red-500 text-white rounded-full shadow-xl shadow-red-500/20 hover:scale-110 transition-transform">
            <Square size={32} />
          </button>
        )}
        {audioBlob && !transcript && (
          <button onClick={handleTranscribe} disabled={isProcessing} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2">
            {isProcessing ? <Loader2 className="animate-spin" /> : <Sparkles size={18}/>}
            Транскрибировать (Whisper)
          </button>
        )}
      </div>

      {transcript && (
        <div className="space-y-4 animate-slide-up">
            <textarea 
                value={transcript}
                onChange={e => setTranscript(e.target.value)}
                className="w-full h-32 bg-gray-50 dark:bg-slate-900 border-none rounded-2xl p-4 text-sm font-medium focus:ring-2 focus:ring-blue-500/20"
            />
            <button onClick={handleSave} className="w-full bg-green-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-green-500/20">
                <Save size={18}/> Сохранить в Базу
            </button>
        </div>
      )}
    </div>
  );
};

