import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  processingCount: { current: number, total: number } | null;
  addNote: (content: string, title?: string, date?: string, sourceType?: Note['sourceType'], category?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processFile: (file: File) => Promise<Note>;
  processFiles: (files: File[]) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
  toggleStatus: (id: string, field: 'isRead' | 'isUsed') => Promise<void>;
  toggleTheme: () => void;
  splitNote: (id: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);
  const [processingCount, setProcessingCount] = useState<{ current: number, total: number } | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      document.documentElement.classList.toggle('dark', storedSettings.theme === 'dark');
      setIsLoading(false);
    };
    init();
  }, []);

  const addNoteInternal = async (content: string, title?: string, date?: string, sourceType: Note['sourceType'] = 'manual', categoryOverride?: string): Promise<Note> => {
    let analysis = { tags: [], category: categoryOverride || 'Общее', summary: '' };
    try {
        const result = await ai.analyzeText(content, settings);
        analysis = {
          tags: result.tags || [],
          category: categoryOverride || result.category || 'Общее',
          summary: result.summary || ''
        };
    } catch (e) {
        analysis = { 
          tags: ['анализ-не-удался'], 
          category: categoryOverride || 'Нераспознанное', 
          summary: 'Ошибка ИИ при анализе' 
        };
    }

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags,
      category: analysis.category,
      summary: analysis.summary,
      links: [],
      createdAt: date || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      isRead: false,
      isUsed: false,
      sourceType
    };
    return newNote;
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    document.documentElement.classList.toggle('dark', newSettings.theme === 'dark');
    await storage.saveSettings(newSettings);
  };

  const toggleTheme = () => {
    const newTheme = settings.theme === 'light' ? 'dark' : 'light';
    updateSettings({ ...settings, theme: newTheme });
  };

  const processFileInternal = async (file: File) => {
    if (file.type.startsWith('image/')) {
        return await addNoteInternal(`[OCR: ${file.name}]\nТекст извлечен со скриншота.`, `Скриншот: ${file.name}`, undefined, 'ocr');
    } else if (file.type.startsWith('audio/')) {
        return await addNoteInternal(`[Аудио: ${file.name}]\nТранскрибация будет доступна после обработки моделью ${settings.transcriptionModel}.`, `Запись: ${file.name}`, undefined, 'audio');
    }
    const text = await file.text();
    return await addNoteInternal(text, file.name.split('.')[0]);
  }

  const value: NotesContextType = {
    notes, settings, isLoading, processingProgress, processingCount,
    addNote: async (c, t, d, st, cat) => {
      const n = await addNoteInternal(c, t, d, st, cat);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    updateNote: async (n) => {
      const updated = notes.map(x => x.id === n.id ? { ...n, updatedAt: new Date().toISOString() } : x);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    deleteNote: async (id) => {
      const updated = notes.filter(x => x.id !== id);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    processFile: async (f) => {
      const n = await processFileInternal(f);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    processFiles: async (files) => {
      setProcessingCount({ current: 0, total: files.length });
      const newOnes: Note[] = [];
      for (let i = 0; i < files.length; i++) {
        setProcessingProgress(Math.round(((i + 1) / files.length) * 100));
        setProcessingCount({ current: i + 1, total: files.length });
        try {
          const n = await processFileInternal(files[i]);
          newOnes.push(n);
        } catch (e) { console.error(e); }
      }
      if (newOnes.length > 0) {
        const up = [...newOnes, ...notes];
        setNotes(up);
        await storage.saveNotes(up);
      }
      setProcessingProgress(null);
      setProcessingCount(null);
    },
    updateSettings,
    toggleStatus: async (id, field) => {
      const up = notes.map(n => n.id === id ? { ...n, [field]: !n[field] } : n);
      setNotes(up);
      await storage.saveNotes(up);
    },
    toggleTheme,
    splitNote: async (id) => {
      console.log('Splitting note:', id);
    }
  };

  return <NotesContext.Provider value={value}>{children}</NotesContext.Provider>;
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error('useNotes must be used within NotesProvider');
  return c;
};

import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const getBaseUrl = (url: string) => url.replace(/\/$/, '');

/**
 * Extracts JSON from a string that might contain other text or markdown blocks.
 */
const extractJSON = (str: string) => {
  try {
    // Attempt direct parse first
    return JSON.parse(str);
  } catch (e) {
    // Try to find JSON block in markdown
    const match = str.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (innerE) {
        throw new Error("Не удалось извлечь валидный JSON из ответа ИИ");
      }
    }
    throw new Error("Ответ ИИ не содержит JSON");
  }
};

export const testConnection = async (settings: Settings): Promise<boolean> => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: 'ping',
      });
      return !!response.text;
    }

    const baseUrl = getBaseUrl(settings.url);
    const endpoint = settings.provider === AIProvider.Ollama 
      ? `${baseUrl}/api/tags` 
      : `${baseUrl}/models`;

    const response = await fetch(endpoint, {
      method: 'GET',
      mode: 'cors',
      headers: settings.apiKey ? { 'Authorization': `Bearer ${settings.apiKey}` } : {}
    });
    return response.ok;
  } catch (e: any) {
    console.error('Connection test failed:', e);
    return false;
  }
};

export const analyzeText = async (text: string, settings: Settings) => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Проанализируй следующий текст и верни структурированные данные в JSON формате. 
        Не добавляй никаких пояснений, только JSON.
        Текст для анализа:\n\n${text}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              tags: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
                description: 'Список релевантных тегов',
              },
              category: {
                type: Type.STRING,
                description: 'Категория контента',
              },
              summary: {
                type: Type.STRING,
                description: 'Краткое резюме одной фразой',
              }
            },
            required: ["tags", "category", "summary"]
          }
        }
      });
      return extractJSON(response.text || '{}');
    }

    const baseUrl = getBaseUrl(settings.url);
    const prompt = `Проанализируй следующий текст и верни ТОЛЬКО JSON без пояснений и без markdown разметки:
{
  "tags": ["тег1", "тег2"],
  "category": "НазваниеКатегории",
  "summary": "Краткое содержание"
}
Текст: ${text}`;

    let url = '';
    let body: any = {};
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };

    if (settings.provider === AIProvider.Ollama) {
      url = `${baseUrl}/api/generate`;
      body = {
        model: settings.model,
        prompt,
        stream: false,
        format: 'json'
      };
    } else {
      url = `${baseUrl}/chat/completions`;
      headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
      body = {
        model: settings.model,
        messages: [{ role: 'system', content: 'You are a helpful assistant that only outputs JSON.' }, { role: 'user', content: prompt }],
        response_format: { type: 'json_object' }
      };
    }

    const response = await fetch(url, {
      method: 'POST',
      mode: 'cors',
      headers,
      body: JSON.stringify(body)
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Ошибка сервера (${response.status}): ${errorText.slice(0, 100)}`);
    }

    const data = await response.json();
    let resultStr = '';

    if (settings.provider === AIProvider.Ollama) {
      resultStr = data.response;
    } else {
      resultStr = data.choices[0].message.content;
    }

    return extractJSON(resultStr);
  } catch (e: any) {
    if (e.name === 'TypeError' && e.message === 'Failed to fetch') {
      throw new Error('Не удалось подключиться к ИИ-серверу. Проверьте, запущен ли сервис (Ollama/LM Studio) и настроен ли CORS (OLLAMA_ORIGINS="*").');
    }
    console.error('AI Analysis Error:', e);
    throw e;
  }
};

export const chatWithNotes = async (question: string, context: string, settings: Settings) => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Ты — ScreenMind2 AI. Твоя база знаний состоит из следующих заметок:\n---\n${context}\n---\nОтветь на вопрос пользователя, используя эти данные. Если информации нет, скажи об этом.\nВопрос: ${question}`,
      });
      return response.text;
    }

    const baseUrl = getBaseUrl(settings.url);
    const prompt = `Ты — ScreenMind2 AI. Твоя база знаний состоит из следующих заметок:
---
${context}
---
Ответь на вопрос пользователя, используя эти данные. Если информации нет, скажи об этом.
Вопрос: ${question}`;

    let url = '';
    let body: any = {};
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };

    if (settings.provider === AIProvider.Ollama) {
      url = `${baseUrl}/api/generate`;
      body = { model: settings.model, prompt, stream: false };
    } else {
      url = `${baseUrl}/chat/completions`;
      headers['Authorization'] = `Bearer ${settings.apiKey || 'lm-studio'}`;
      body = {
        model: settings.model,
        messages: [{ role: 'user', content: prompt }]
      };
    }

    const response = await fetch(url, { method: 'POST', mode: 'cors', headers, body: JSON.stringify(body) });
    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Ошибка чата (${response.status}): ${errorText.slice(0, 100)}`);
    }

    const data = await response.json();
    if (settings.provider === AIProvider.Ollama) return data.response;
    return data.choices[0].message.content;
  } catch (e: any) {
    if (e.name === 'TypeError' && e.message === 'Failed to fetch') {
      throw new Error('Ошибка подключения к ИИ для чата. Проверьте настройки URL и CORS.');
    }
    throw e;
  }
};

