  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [activeTag, setActiveTag] = useState<string | null>(null);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const allTags = useMemo(() => {
    const tags = new Set<string>();
    notes.forEach(n => n.tags.forEach(t => tags.add(t)));
    return Array.from(tags).sort();
  }, [notes]);

  const allCategories = useMemo(() => {
    const cats = new Set<string>();
    notes.forEach(n => cats.add(n.category));
    return Array.from(cats).sort();
  }, [notes]);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const query = search.toLowerCase();
    const matchesSearch = n.title.toLowerCase().includes(query) || 
                         n.content.toLowerCase().includes(query) ||
                         n.category.toLowerCase().includes(query) ||
                         n.tags.some(t => t.toLowerCase().includes(query));
    const matchesTag = !activeTag || n.tags.includes(activeTag);
    const matchesCat = !activeCategory || n.category === activeCategory;
    return matchesSearch && matchesTag && matchesCat;
  }), [notes, search, activeTag, activeCategory]);

