                    <Trash2 size={20} />
                </button>
            </div>
          )}
          <button 
            disabled={isSaving}
            onClick={handleSave}
            className="flex items-center gap-3 bg-blue-600 text-white px-8 py-4 rounded-[1.5rem] hover:bg-blue-700 transition-all shadow-xl shadow-blue-500/20 active:scale-95 font-black uppercase tracking-widest text-xs"
          >
            <Save size={18} />
            {isSaving ? 'Сохранение...' : 'Сохранить'}
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 p-12 overflow-y-auto">
          <textarea
            autoFocus
            placeholder="Пишите свои мысли здесь... ИИ автоматически проанализирует их после сохранения."
            className="w-full h-full resize-none focus:outline-none text-xl leading-relaxed font-medium text-gray-700 placeholder:text-gray-200 scrollbar-hide"
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
        </div>

        <div className="w-[30%] p-12 bg-gray-50/50 overflow-y-auto border-l border-gray-100">
          <div className="flex items-center gap-3 mb-8 text-gray-400 uppercase text-[10px] font-black tracking-[0.2em]">
