import React, { useEffect, useRef, useState } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import * as d3 from 'https://cdn.jsdelivr.net/npm/d3@7/+esm';
import { useNavigate } from 'react-router-dom';
import { getTagColor } from '../utils/tagColors.ts';
import { BrainCircuit, Layers, Share2, RotateCcw } from 'lucide-react';

const GraphView: React.FC = () => {
  const { notes } = useNotes();
  const navigate = useNavigate();
  const svgRef = useRef<SVGSVGElement>(null);
  const [mode, setMode] = useState<'neural' | 'tree'>('neural');

  useEffect(() => {
    if (!svgRef.current || notes.length === 0) return;

    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    const nodes = notes.map(n => ({ 
        id: n.id, 
        title: n.title, 
        group: n.category,
        isRead: n.isRead,
        isUsed: n.isUsed,
        color: getTagColor(n.category).text
    }));

    const links: any[] = [];
    notes.forEach((n, i) => {
      notes.slice(i + 1).forEach(m => {
        const commonTags = n.tags.filter(t => m.tags.includes(t));
        if (commonTags.length > 0) {
          links.push({ source: n.id, target: m.id, value: commonTags.length + 3 });
        } else if (n.category === m.category) {
          links.push({ source: n.id, target: m.id, value: 1 });
        }
      });
    });

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const g = svg.append("g");
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 8])
      .on("zoom", (event) => g.attr("transform", event.transform));

    svg.call(zoom);

    if (mode === 'neural') {
        const simulation = d3.forceSimulation(nodes as any)
            .force("link", d3.forceLink(links).id((d: any) => d.id).distance(150))
            .force("charge", d3.forceManyBody().strength(-300))
            .force("center", d3.forceCenter(width / 2, height / 2))
            .force("collision", d3.forceCollide().radius(50));

        const link = g.append("g")
            .attr("stroke", "#cbd5e1")
            .attr("stroke-opacity", 0.3)
            .selectAll("line")
            .data(links)
            .join("line")
            .attr("stroke-width", d => Math.sqrt(d.value) * 1.5);

        const node = g.append("g")
            .selectAll("g")
            .data(nodes)
            .join("g")
            .attr("cursor", "pointer")
            .on("click", (e, d: any) => navigate(`/editor/${d.id}`))
            .call(d3.drag<any, any>()
                .on("start", (e, d) => { if (!e.active) simulation.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; })
                .on("drag", (e, d) => { d.fx = e.x; d.fy = e.y; })
                .on("end", (e, d) => { if (!e.active) simulation.alphaTarget(0); d.fx = null; d.fy = null; }));

        node.append("circle").attr("r", 12).attr("fill", (d: any) => d.color).attr("stroke", "#fff").attr("stroke-width", 2);
        node.append("text").attr("dy", 25).attr("text-anchor", "middle").attr("font-size", "10px").attr("font-weight", "800").text(d => d.title.slice(0, 15));

        simulation.on("tick", () => {
            link.attr("x1", (d: any) => d.source.x).attr("y1", (d: any) => d.source.y).attr("x2", (d: any) => d.target.x).attr("y2", (d: any) => d.target.y);
            node.attr("transform", (d: any) => `translate(${d.x},${d.y})`);
        });
    } else {
        // Simple Hierarchical Mode (Group by Category)
        const categories = Array.from(new Set(notes.map(n => n.category)));
        const catNodes = categories.map((cat, i) => ({ id: `cat-${i}`, title: cat, isCat: true, color: getTagColor(cat).text }));
        const allNodes = [...catNodes, ...nodes];
        const catLinks = notes.map(n => ({ source: `cat-${categories.indexOf(n.category)}`, target: n.id, value: 1 }));

        const simulation = d3.forceSimulation(allNodes as any)
            .force("link", d3.forceLink(catLinks).id((d: any) => d.id).distance(80))
            .force("charge", d3.forceManyBody().strength(-200))
            .force("center", d3.forceCenter(width / 2, height / 2));

        const link = g.append("g").attr("stroke", "#e2e8f0").selectAll("line").data(catLinks).join("line").attr("stroke-width", 1);
        const node = g.append("g").selectAll("g").data(allNodes).join("g").attr("cursor", "pointer")
            .on("click", (e, d: any) => !d.isCat && navigate(`/editor/${d.id}`));

        node.append("circle").attr("r", (d: any) => d.isCat ? 20 : 8).attr("fill", (d: any) => d.color);
        node.append("text").attr("dy", 30).attr("text-anchor", "middle").attr("font-size", (d: any) => d.isCat ? "12px" : "8px").attr("font-weight", "bold").text(d => d.title);

        simulation.on("tick", () => {
            link.attr("x1", (d: any) => d.source.x).attr("y1", (d: any) => d.source.y).attr("x2", (d: any) => d.target.x).attr("y2", (d: any) => d.target.y);
            node.attr("transform", (d: any) => `translate(${d.x},${d.y})`);
        });
    }
  }, [notes, navigate, mode]);

  return (
    <div className="flex-1 flex flex-col h-screen overflow-hidden bg-white dark:bg-slate-900 transition-colors">
      <div className="px-12 py-10 flex justify-between items-end relative z-10">
        <div>
            <h2 className="text-3xl font-black text-gray-900 dark:text-white leading-none">Карта Сознания</h2>
            <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mt-2">Визуализация {mode === 'neural' ? 'ассоциаций' : 'структуры'}</p>
        </div>
        <div className="flex gap-2 bg-gray-50 dark:bg-slate-800 p-2 rounded-2xl">
            <button onClick={() => setMode('neural')} className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${mode === 'neural' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-gray-600'}`}>
                <Share2 size={14} /> Нейронная
            </button>
            <button onClick={() => setMode('tree')} className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${mode === 'tree' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-gray-600'}`}>
                <Layers size={14} /> Дерево
            </button>
        </div>
      </div>
      <div className="flex-1 relative bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] dark:bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:32px_32px]">
        <svg ref={svgRef} className="w-full h-full" />
      </div>
    </div>
  );
};

export default GraphView;

import React, { useState, useRef, useEffect } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Send, Bot, User, Eraser, AlertCircle } from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';
import { ChatMessage } from '../types.ts';

const ChatPage: React.FC = () => {
  const { notes, settings } = useNotes();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage: ChatMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    const context = notes.map(n => `[ID: ${n.id}] ${n.title}: ${n.content}`).join('\n\n');

    try {
      const response = await ai.chatWithNotes(input, context, settings);

      const sources = notes.filter(n => response.includes(n.id)).map(n => n.id);

      const aiMessage: ChatMessage = { 
        role: 'assistant', 
        content: response || 'Пустой ответ от ИИ.',
        sources: sources.length > 0 ? sources : undefined
      };
      setMessages(prev => [...prev, aiMessage]);
    } catch (e: any) {
      setMessages(prev => [...prev, { 
        role: 'assistant', 
        content: `Ошибка: ${e.message || 'Произошла непредвиденная ошибка при обращении к ИИ.'}` 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-screen max-w-4xl mx-auto p-4">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <Bot className="text-blue-600" />
          Интеллектуальный чат
        </h2>
        <button 
          onClick={() => setMessages([])}
          className="text-gray-400 hover:text-red-500 flex items-center gap-1 text-sm transition-colors"
        >
          <Eraser size={16} /> Очистить
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 mb-6 px-2 scroll-smooth">
        {messages.length === 0 && (
          <div className="text-center py-20 text-gray-400 font-medium">
            <p>Задайте вопрос по вашей базе знаний.</p>
            <p className="text-sm mt-2 italic text-gray-300">Например: "Какие идеи у меня были на прошлой неделе?"</p>
          </div>
        )}

        {messages.map((m, i) => (
          <div key={i} className={`flex gap-4 ${m.role === 'assistant' ? 'flex-row' : 'flex-row-reverse'}`}>
            <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${
              m.role === 'assistant' ? 'bg-blue-50 text-blue-600' : 'bg-gray-100 text-gray-600'
            }`}>
              {m.role === 'assistant' ? <Bot size={18} /> : <User size={18} />}
            </div>
            <div className={`max-w-[85%] rounded-[1.5rem] px-5 py-4 ${
