              {m.content.startsWith('Ошибка:') ? (
                <div className="flex items-start gap-2 text-red-500 font-medium">
                  <AlertCircle size={18} className="shrink-0 mt-0.5" />
                  <p className="whitespace-pre-wrap leading-relaxed">{m.content}</p>
                </div>
              ) : (
                <p className="whitespace-pre-wrap leading-relaxed">{m.content}</p>
              )}

              {m.sources && (
                <div className="mt-4 pt-4 border-t border-gray-100">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Источники знаний</span>
                  <div className="flex flex-wrap gap-2">
                    {m.sources.map(sId => {
                      const n = notes.find(note => note.id === sId);
                      return n ? (
