  return notes || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  provider: AIProvider.Ollama,
  url: 'http://localhost:11434',
  model: 'mistral',
  transcriptionModel: 'whisper-large-v3',
  apiKey: '',
  theme: 'light'
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return settings || getDefaultSettings();
};

export const exportData = async () => {
  const notes = await getNotes();
  const settings = await getSettings();
  const data = JSON.stringify({ notes, settings, version: '2.5', exportedAt: new Date().toISOString() }, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `screenmind_backup_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  processingProgress: number | null;
  processingCount: { current: number, total: number } | null;
  addNote: (content: string, title?: string, date?: string, sourceType?: Note['sourceType'], category?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  processFile: (file: File) => Promise<Note>;
  processFiles: (files: File[]) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
  toggleStatus: (id: string, field: 'isRead' | 'isUsed') => Promise<void>;
  toggleTheme: () => void;
  splitNote: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);
  const [processingCount, setProcessingCount] = useState<{ current: number, total: number } | null>(null);

  useEffect(() => {
    const init = async () => {
      const [storedNotes, storedSettings] = await Promise.all([
        storage.getNotes(),
        storage.getSettings()
      ]);
      setNotes(storedNotes);
      setSettings(storedSettings);
      document.documentElement.classList.toggle('dark', storedSettings.theme === 'dark');
      setIsLoading(false);
    };
    init();
  }, []);

  const analyzeSingleNote = async (content: string, currentSettings: Settings) => {
    if (!content || content.length < 5) {
        return { tags: ['short'], category: 'Черновики', summary: 'Слишком короткий текст для анализа' };
    }
    try {
        const result = await ai.analyzeText(content, currentSettings);
        return {
          tags: result.tags || [],
          category: result.category || 'Общее',
          summary: result.summary || ''
        };
    } catch (e) {
        return { 
          tags: ['ошибка-анализа'], 
          category: 'Нераспознанное', 
          summary: 'Не удалось получить ответ от ИИ' 
        };
    }
  };

  const addNoteInternal = async (content: string, title?: string, date?: string, sourceType: Note['sourceType'] = 'manual', categoryOverride?: string): Promise<Note> => {
    const analysis = await analyzeSingleNote(content, settings);

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags,
      category: categoryOverride || analysis.category,
      summary: analysis.summary,
      links: [],
      createdAt: date || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      isRead: false,
      isUsed: false,
      sourceType
    };
    return newNote;
  };

  const reanalyzeAll = async () => {
    setProcessingCount({ current: 0, total: notes.length });
    const updatedNotes = [...notes];
    for (let i = 0; i < updatedNotes.length; i++) {
        setProcessingProgress(Math.round(((i + 1) / notes.length) * 100));
        setProcessingCount({ current: i + 1, total: notes.length });
        const analysis = await analyzeSingleNote(updatedNotes[i].content, settings);
        updatedNotes[i] = {
            ...updatedNotes[i],
            tags: analysis.tags,
            category: analysis.category,
            summary: analysis.summary,
            updatedAt: new Date().toISOString()
        };
    }
    setNotes(updatedNotes);
    await storage.saveNotes(updatedNotes);
    setProcessingProgress(null);
    setProcessingCount(null);
  };

  const updateSettings = async (newSettings: Settings) => {
    setSettings(newSettings);
    document.documentElement.classList.toggle('dark', newSettings.theme === 'dark');
    await storage.saveSettings(newSettings);
  };

  const toggleTheme = () => {
    const newTheme = settings.theme === 'light' ? 'dark' : 'light';
    updateSettings({ ...settings, theme: newTheme });
  };

  const value: NotesContextType = {
    notes, settings, isLoading, processingProgress, processingCount,
    addNote: async (c, t, d, st, cat) => {
      const n = await addNoteInternal(c, t, d, st, cat);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    updateNote: async (n) => {
      const updated = notes.map(x => x.id === n.id ? { ...n, updatedAt: new Date().toISOString() } : x);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    deleteNote: async (id) => {
      const updated = notes.filter(x => x.id !== id);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    processFile: async (f) => {
      if (f.type.startsWith('image/')) {
          const n = await addNoteInternal(`[OCR: ${f.name}]\nТекст извлечен со скриншота.`, `Скриншот: ${f.name}`, undefined, 'ocr');
          setNotes(prev => [n, ...prev]);
          const latest = await storage.getNotes();
          await storage.saveNotes([n, ...latest]);
          return n;
      }
      const text = await f.text();
      const n = await addNoteInternal(text, f.name.split('.')[0]);
      setNotes(prev => [n, ...prev]);
      const latest = await storage.getNotes();
      await storage.saveNotes([n, ...latest]);
      return n;
    },
    processFiles: async (files) => {
      setProcessingCount({ current: 0, total: files.length });
      const newOnes: Note[] = [];
      for (let i = 0; i < files.length; i++) {
        setProcessingProgress(Math.round(((i + 1) / files.length) * 100));
        setProcessingCount({ current: i + 1, total: files.length });
        try {
          const text = await files[i].text();
          const n = await addNoteInternal(text, files[i].name.split('.')[0]);
          newOnes.push(n);
        } catch (e) { console.error(e); }
      }
      if (newOnes.length > 0) {
        const up = [...newOnes, ...notes];
        setNotes(up);
        await storage.saveNotes(up);
      }
      setProcessingProgress(null);
      setProcessingCount(null);
    },
    updateSettings,
    toggleStatus: async (id, field) => {
      const up = notes.map(n => n.id === id ? { ...n, [field]: !n[field] } : n);
      setNotes(up);
      await storage.saveNotes(up);
    },
    toggleTheme,
    splitNote: async (id) => {
      console.log('Splitting note:', id);
    },
    reanalyzeAll
  };

  return <NotesContext.Provider value={value}>{children}</NotesContext.Provider>;
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error('useNotes must be used within NotesProvider');
  return c;
};

