import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  processingProgress: number | null;
  processingCount: { current: number, total: number } | null;
  addNote: (content: string, title?: string, date?: string, sourceType?: Note['sourceType'], category?: string) => Promise<Note>;
  updateNote: (note: Note) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  updateSettings: (newSettings: Settings) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  toggleTheme: () => void;
  reanalyzeAll: () => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  clearLogs: () => void;
  // Added missing methods used in NoteEditor
  splitNote: (id: string) => Promise<void>;
  toggleStatus: (id: string, field: 'isRead' | 'isUsed') => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [processingProgress, setProcessingProgress] = useState<number | null>(null);
  const [processingCount, setProcessingCount] = useState<{ current: number, total: number } | null>(null);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    const newLog: AppLog = {
      id: crypto.randomUUID(),
      timestamp: new Date().toISOString(),
      level,
      message,
      details
    };
    setLogs(prev => [newLog, ...prev].slice(0, 100));
  };

  useEffect(() => {
    const init = async () => {
      try {
        const [storedNotes, storedSettings] = await Promise.all([
          storage.getNotes(),
          storage.getSettings()
        ]);
        setNotes(storedNotes);
        setSettings(storedSettings);
        document.documentElement.classList.toggle('dark', storedSettings.theme === 'dark');
        addLog('info', 'Система ScreenMind2 запущена успешно');
      } catch (e) {
        addLog('error', 'Ошибка инициализации хранилища', String(e));
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  const analyzeSingleNote = async (content: string, currentSettings: Settings) => {
    if (!content || content.length < 5) {
      return { tags: ['short'], category: 'Черновики', summary: 'Слишком короткий текст' };
    }
    try {
      const result = await ai.analyzeText(content, currentSettings);
      return {
        tags: result.tags || [],
        category: result.category || 'Общее',
        summary: result.summary || ''
      };
    } catch (e) {
      addLog('error', 'Ошибка анализа ИИ', String(e));
      return { 
        tags: ['анализ-провален'], 
        category: 'Нераспознанное', 
        summary: 'Не удалось получить ответ от ИИ' 
      };
    }
  };

  const addNoteInternal = async (content: string, title?: string, date?: string, sourceType: Note['sourceType'] = 'manual', categoryOverride?: string): Promise<Note> => {
    const analysis = await analyzeSingleNote(content, settings);
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40).replace(/\n/g, ' ').trim() + (content.length > 40 ? '...' : ''),
      content,
      tags: analysis.tags,
      category: categoryOverride || analysis.category,
      summary: analysis.summary,
      links: [],
      createdAt: date || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      status: 'new',
      sourceType
    };
    return newNote;
  };

  const value: NotesContextType = {
    notes, settings, isLoading, logs, processingProgress, processingCount,
    addNote: async (c, t, d, st, cat) => {
      const n = await addNoteInternal(c, t, d, st, cat);
      const updated = [n, ...notes];
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('info', `Добавлена новая заметка: ${n.title}`);
      return n;
    },
    updateNote: async (n) => {
      const updated = notes.map(x => x.id === n.id ? { ...n, updatedAt: new Date().toISOString() } : x);
      setNotes(updated);
      await storage.saveNotes(updated);
    },
    deleteNote: async (id) => {
      const updated = notes.filter(x => x.id !== id);
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('info', `Заметка удалена (ID: ${id})`);
    },
    updateSettings: async (s) => {
      setSettings(s);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
      await storage.saveSettings(s);
      addLog('info', 'Настройки обновлены');
    },
    setNoteStatus: async (id, status) => {
      const updated = notes.map(n => n.id === id ? { ...n, status, updatedAt: new Date().toISOString() } : n);
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('info', `Статус изменен: ${status}`, `ID: ${id}`);
    },
    toggleTheme: () => {
      const newTheme = settings.theme === 'light' ? 'dark' : 'light';
      value.updateSettings({ ...settings, theme: newTheme });
    },
    reanalyzeAll: async () => {
      setProcessingCount({ current: 0, total: notes.length });
      const updatedNotes = [...notes];
      for (let i = 0; i < updatedNotes.length; i++) {
        setProcessingProgress(Math.round(((i + 1) / notes.length) * 100));
        setProcessingCount({ current: i + 1, total: notes.length });
        const analysis = await analyzeSingleNote(updatedNotes[i].content, settings);
        updatedNotes[i] = {
          ...updatedNotes[i],
          tags: analysis.tags,
          category: analysis.category,
          summary: analysis.summary,
          updatedAt: new Date().toISOString()
        };
      }
      setNotes(updatedNotes);
      await storage.saveNotes(updatedNotes);
      setProcessingProgress(null);
      setProcessingCount(null);
      addLog('info', 'Полный переанализ базы завершен');
    },
    addLog,
    clearLogs: () => setLogs([]),
    // Implementation of toggleStatus to handle isRead and isUsed toggling
    toggleStatus: async (id, field) => {
      const updated = notes.map(n => {
        if (n.id === id) {
          const newVal = !n[field];
          const updates: any = { [field]: newVal, updatedAt: new Date().toISOString() };
          // Sync status with isRead for convenience
          if (field === 'isRead') {
            updates.status = newVal ? 'read' : 'new';
          }
          return { ...n, ...updates };
        }
        return n;
      });
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('info', `Статус ${field} обновлен для заметки`, `ID: ${id}`);
    },
    // Implementation of splitNote to break content into multiple notes
    splitNote: async (id) => {
      const noteToSplit = notes.find(n => n.id === id);
      if (!noteToSplit) return;

      addLog('info', `Запуск разделения заметки: ${noteToSplit.title}`);

      try {
        // Splitting by double newline as a logical separator for blocks
        const parts = noteToSplit.content.split('\n\n').filter(p => p.trim().length > 10);
        if (parts.length > 1) {
          for (const part of parts) {
            await value.addNote(part.trim(), undefined, undefined, noteToSplit.sourceType, noteToSplit.category);
          }
          addLog('info', `Заметка успешно разделена на ${parts.length} новых фрагментов`);
        } else {
          addLog('warn', 'Заметка слишком короткая для разделения или не содержит разделителей');
        }
      } catch (e) {
        addLog('error', 'Ошибка при разделении заметки', String(e));
      }
    }
  };

  return <NotesContext.Provider value={value}>{children}</NotesContext.Provider>;
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error('useNotes must be used within NotesProvider');
  return c;
};

