    case 'in-work': return { label: 'В работе', color: 'bg-blue-100 text-blue-600 border-blue-200', icon: PlayCircle };
    case 'read': return { label: 'Прочитано', color: 'bg-slate-100 text-slate-500 border-slate-200', icon: Eye };
    case 'finished': return { label: 'Готово', color: 'bg-green-100 text-green-600 border-green-200', icon: CheckCircle2 };
  }
};

