const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));

      mediaRecorder.start();
      setIsRecording(true);
      visualize(stream);
    } catch (err) {
      console.error("Microphone access denied", err);
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new AudioContext();
    const source = audioCtx.createMediaStreamSource(stream);
    const analyser = audioCtx.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2.5;
      let barHeight;
      let x = 0;
      for (let i = 0; i < bufferLength; i++) {
        barHeight = dataArray[i] / 2;
        ctx.fillStyle = `rgb(59, 130, 246)`;
        ctx.fillRect(x, canvas.height / 2 - barHeight / 2, barWidth, barHeight);
        x += barWidth + 1;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    setIsProcessing(true);
    // Simulation of transcription call
    setTimeout(() => {
        setTranscript("Это пример транскрибации вашей идеи. Локальная модель Whisper успешно распознала речь и подготовила текст для сохранения в базу знаний ScreenMind.");
        setIsProcessing(false);
    }, 2000);
  };

  const handleSave = async () => {
    if (!transcript) return;
    // Fixed: Corrected call signature from (content, title, undefined, sourceType) to (content, title, sourceType)
    await addNote(transcript, `Голосовая заметка ${new Date().toLocaleTimeString()}`, 'audio');
    setTranscript('');
    setAudioBlob(null);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-700 shadow-2xl space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-black dark:text-white uppercase tracking-widest flex items-center gap-2">
            <Volume2 className="text-blue-500" /> Голосовая Заметка
        </h3>
        {audioBlob && <button onClick={() => setAudioBlob(null)} className="text-gray-400 hover:text-red-500"><RotateCcw size={18}/></button>}
      </div>

      <div className="h-24 bg-gray-50 dark:bg-slate-900/50 rounded-2xl flex items-center justify-center overflow-hidden">
        {isRecording ? (
          <canvas ref={canvasRef} width={400} height={100} className="w-full h-full" />
        ) : audioBlob ? (
          <div className="text-blue-500 font-bold text-xs uppercase tracking-widest animate-pulse">Запись готова к обработке</div>
        ) : (
          <p className="text-gray-300 dark:text-slate-600 font-bold text-xs uppercase tracking-widest">Нажмите микрофон для записи</p>
        )}
      </div>

      <div className="flex justify-center gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="p-6 bg-blue-600 text-white rounded-full shadow-xl shadow-blue-500/20 hover:scale-110 transition-transform">
            <Mic size={32} />
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="p-6 bg-red-500 text-white rounded-full shadow-xl shadow-red-500/20 hover:scale-110 transition-transform">
            <Square size={32} />
          </button>
        )}
        {audioBlob && !transcript && (
          <button onClick={handleTranscribe} disabled={isProcessing} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2">
            {isProcessing ? <Loader2 className="animate-spin" /> : <Sparkles size={18}/>}
            Транскрибировать (Whisper)
          </button>
        )}
      </div>

      {transcript && (
        <div className="space-y-4 animate-slide-up">
            <textarea 
                value={transcript}
                onChange={e => setTranscript(e.target.value)}
                className="w-full h-32 bg-gray-50 dark:bg-slate-900 border-none rounded-2xl p-4 text-sm font-medium focus:ring-2 focus:ring-blue-500/20"
            />
            <button onClick={handleSave} className="w-full bg-green-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-green-500/20">
                <Save size={18}/> Сохранить в Базу
            </button>
        </div>
      )}
    </div>
  );
};

