import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], category?: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runSystemCheck: () => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => void;
  updateNoteSize: (id: string, w: number, h: number) => void;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s] = await Promise.all([storage.getNotes(), storage.getSettings()]);
      setNotes(n);
      setSettings(s);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
      addLog('success', 'ScreenMind2: Все системы в норме');
    };
    init();
  }, []);

  const runSystemCheck = async () => {
    addLog('info', 'Запуск комплексной проверки...');
    const aiTest = await ai.testConnection(settings);
    addLog(aiTest.success ? 'success' : 'error', `Тест ИИ (${settings.provider}): ${aiTest.message}`);
    addLog('success', `Локальная база: ${notes.length} объектов. Хранилище IndexedDB активно.`);
  };

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', category?: string) => {
    try {
      addLog('info', 'Анализ новой записи...');
      const analysis = await ai.analyzeText(content, settings);
      const newNote: Note = {
        id: crypto.randomUUID(),
        title: title || content.slice(0, 30) + '...',
        content,
        tags: analysis.tags || [],
        category: category || analysis.category || 'Общее',
        summary: analysis.summary || '',
        status: 'new',
        sourceType,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        links: [],
        position: { x: Math.random() * 200, y: Math.random() * 200 },
        size: { w: 300, h: 250 }
      };
      const updated = [newNote, ...notes];
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('success', `Заметка добавлена: ${newNote.title}`);
    } catch (e: any) {
      addLog('error', 'Ошибка создания', e.message);
    }
  };

  const moveToTrash = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus, updatedAt: new Date().toISOString() } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('warn', `Заметка перемещена в корзину`);
  };

  const restoreNote = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'new' as NoteStatus, updatedAt: new Date().toISOString() } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', `Заметка восстановлена`);
  };

  const hardDelete = async (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('error', `Заметка удалена безвозвратно`);
  };

  const updateNote = async (n: Note) => {
    const updated = notes.map(x => x.id === n.id ? { ...n, updatedAt: new Date().toISOString() } : x);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const updateNotePosition = (id: string, x: number, y: number) => {
    setNotes(prev => prev.map(n => n.id === id ? { ...n, position: { x, y } } : n));
  };

  const updateNoteSize = (id: string, w: number, h: number) => {
    setNotes(prev => prev.map(n => n.id === id ? { ...n, size: { w, h } } : n));
  };

  const reanalyzeAll = async () => {
    addLog('info', 'Переанализ всей базы...');
    const updated = [...notes];
    for (let i = 0; i < updated.length; i++) {
      try {
        const res = await ai.analyzeText(updated[i].content, settings);
        updated[i] = { ...updated[i], tags: res.tags, category: res.category, summary: res.summary };
      } catch (e) {}
    }
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', 'Переанализ завершен');
  };

  return (
    <NotesContext.Provider value={{ 
      notes, settings, isLoading, logs, addNote, updateNote, moveToTrash, restoreNote, hardDelete,
      setNoteStatus, updateSettings, addLog, runSystemCheck, reanalyzeAll, updateNotePosition, updateNoteSize 
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React from 'react';
