import React, { useState, useRef, useEffect } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { useNavigate } from 'react-router-dom';
import { Maximize2, Move, Link2, ExternalLink, Clock, Sparkles } from 'lucide-react';
import { getTagColor } from '../utils/tagColors.ts';

const Workspace: React.FC = () => {
  const { notes, updateNotePosition, updateNoteSize } = useNotes();
  const navigate = useNavigate();
  const containerRef = useRef<HTMLDivElement>(null);
  const [activeNotes] = useState(() => notes.filter(n => n.status !== 'trash' && n.status !== 'archived'));

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if ((e.target as HTMLElement).closest('.resize-handle')) return;
    setDraggingId(id);
    const note = notes.find(n => n.id === id);
    if (note) {
      setOffset({ x: e.clientX - note.position.x, y: e.clientY - note.position.y });
    }
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (draggingId) {
      updateNotePosition(draggingId, e.clientX - offset.x, e.clientY - offset.y);
    }
  };

  const handleMouseUp = () => setDraggingId(null);

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [draggingId, offset]);

  return (
    <div ref={containerRef} className="flex-1 h-screen relative overflow-hidden bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] dark:bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:40px_40px] transition-colors">
      <div className="absolute top-10 left-12 z-10">
        <h2 className="text-3xl font-black dark:text-white">Пространство</h2>
        <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mt-2 flex items-center gap-2">
            <Move size={12} className="text-blue-500" /> Перетаскивайте и связывайте идеи
        </p>
      </div>

      <div className="absolute inset-0">
        {activeNotes.map(note => {
          const colors = getTagColor(note.category);
          return (
            <div
              key={note.id}
              onMouseDown={(e) => handleMouseDown(e, note.id)}
              style={{
                left: note.position.x,
                top: note.position.y,
                width: note.size.w,
                height: note.size.h,
                zIndex: draggingId === note.id ? 100 : 1
              }}
              className="absolute bg-white dark:bg-slate-900 rounded-[2rem] border border-gray-100 dark:border-slate-800 shadow-xl shadow-black/5 flex flex-col group cursor-grab active:cursor-grabbing transition-shadow hover:shadow-2xl overflow-hidden"
            >
              <div className="px-6 py-4 flex items-center justify-between border-b border-gray-50 dark:border-slate-800">
                <span style={{ color: colors.text, backgroundColor: colors.bg }} className="text-[8px] font-black uppercase px-2 py-0.5 rounded-md">
                    {note.category}
                </span>
                <button onClick={() => navigate(`/editor/${note.id}`)} className="p-1.5 text-gray-300 hover:text-blue-500 rounded-lg transition-colors">
                    <Maximize2 size={14} />
                </button>
              </div>

              <div className="p-6 flex-1 overflow-hidden">
                <h3 className="font-extrabold text-sm mb-2 dark:text-white line-clamp-1">{note.title}</h3>
                <p className="text-xs text-gray-500 dark:text-slate-400 leading-relaxed line-clamp-4">{note.content}</p>
              </div>

              <div className="px-6 py-4 bg-gray-50/50 dark:bg-slate-800/50 flex items-center justify-between">
                <div className="flex gap-1">
                    {note.tags.slice(0, 2).map(t => <span key={t} className="text-[8px] text-gray-400 font-bold">#{t}</span>)}
                </div>
                <div className="flex items-center gap-2 text-[8px] font-black text-gray-300 uppercase tracking-widest">
                    <Clock size={10}/> {new Date(note.createdAt).toLocaleDateString()}
                </div>
              </div>

              <div className="absolute bottom-1 right-1 cursor-nwse-resize opacity-0 group-hover:opacity-100 transition-opacity p-1 text-gray-300 resize-handle">
                <Maximize2 size={12} className="rotate-90" />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Workspace;

