import React, { useState, useMemo } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { NotesProvider, useNotes } from './contexts/NotesContext.tsx';
import Sidebar from './components/Sidebar.tsx';
import NotesPage from './pages/NotesPage.tsx';
import NoteEditor from './pages/NoteEditor.tsx';
import GraphView from './pages/GraphView.tsx';
import ChatPage from './pages/ChatPage.tsx';
import SettingsPage from './pages/SettingsPage.tsx';
import IdeasPage from './pages/IdeasPage.tsx';
import TrashPage from './pages/TrashPage.tsx';
import Workspace from './pages/Workspace.tsx';
import AudioRecorder from './components/AudioRecorder.tsx';
import { Lightbulb, Send, Loader2, Sparkles, Mic, X, Hash, BarChart3, Clock, Zap } from 'lucide-react';
import { getTagColor } from './utils/tagColors.ts';

const QuickIdeasPanel: React.FC = () => {
  const { addNote, notes } = useNotes();
  const [idea, setIdea] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRecorder, setShowRecorder] = useState(false);

  const activeNotes = notes.filter(n => n.status !== 'trash');

  const activeTags = useMemo(() => {
    const counts: Record<string, number> = {};
    activeNotes.forEach(n => n.tags.forEach(t => counts[t] = (counts[t] || 0) + 1));
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 8);
  }, [activeNotes]);

  const stats = useMemo(() => ({
    total: activeNotes.length,
    new: activeNotes.filter(n => n.status === 'new').length,
    inWork: activeNotes.filter(n => n.status === 'in-work').length,
    finished: activeNotes.filter(n => n.status === 'finished').length,
  }), [activeNotes]);

  const handleSaveIdea = async () => {
    if (!idea.trim()) return;
    setIsSaving(true);
    await addNote(idea, `Идея: ${idea.slice(0, 20)}`, 'manual', 'Идеи');
    setIdea('');
    setIsSaving(false);
  };

  return (
    <div className="w-80 bg-white dark:bg-slate-900 border-l border-gray-100 dark:border-slate-800 h-screen flex flex-col hidden xl:flex transition-colors shrink-0 z-10">
      <div className="p-6 border-b border-gray-50 dark:border-slate-800">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-black text-[10px] uppercase tracking-widest text-gray-400 flex items-center gap-2">
            <Zap size={14} className="text-amber-500" /> Быстрый фокус
          </h3>
          <button onClick={() => setShowRecorder(true)} className="p-2 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl transition-all">
            <Mic size={18} />
          </button>
        </div>
        <div className="relative group">
          <textarea 
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="Запишите мысль..."
            className="w-full h-28 p-4 bg-gray-50 dark:bg-slate-800/50 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 text-sm font-medium text-gray-700 dark:text-slate-200 placeholder:text-gray-300 dark:placeholder:text-slate-600 resize-none transition-all"
          />
          <button 
            onClick={handleSaveIdea}
            disabled={isSaving || !idea.trim()}
            className="absolute bottom-3 right-3 p-2.5 bg-blue-600 text-white rounded-xl shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-all disabled:opacity-30 active:scale-95"
          >
            {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        <section>
          <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
            <Hash size={12} /> Живые теги
          </h4>
          <div className="flex flex-wrap gap-2">
            {activeTags.map(([tag, count]) => {
              const colors = getTagColor(tag);
              return (
                <div key={tag} style={{ color: colors.text, backgroundColor: colors.bg }} className="px-3 py-1.5 rounded-xl transition-all flex items-center gap-2 group">
                  <span className="text-[10px] font-black italic">#{tag}</span>
                  <span className="text-[8px] font-black bg-white/50 px-1.5 rounded-md">{count}</span>
                </div>
              );
            })}
          </div>
        </section>
      </div>

      <div className="p-6 bg-gray-50 dark:bg-slate-900 border-t border-gray-100 dark:border-slate-800">
        <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
          <BarChart3 size={12} /> Статус Разума
        </h4>
        <div className="grid grid-cols-2 gap-3">
          <div className="p-3 bg-white dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-800 shadow-sm">
            <span className="block text-[8px] font-black text-blue-500 uppercase">Всего</span>
            <span className="text-xl font-black dark:text-white">{stats.total}</span>
          </div>
          <div className="p-3 bg-white dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-800 shadow-sm">
            <span className="block text-[8px] font-black text-green-500 uppercase">Готово</span>
            <span className="text-xl font-black dark:text-white">{stats.finished}</span>
          </div>
        </div>
      </div>

      {showRecorder && (
        <div className="fixed inset-0 z-[100] bg-black/40 backdrop-blur-sm flex items-center justify-center p-6">
            <div className="relative max-w-md w-full animate-slide-up">
                <button onClick={() => setShowRecorder(false)} className="absolute -top-4 -right-4 bg-white dark:bg-slate-800 p-2 rounded-full shadow-xl text-gray-400 hover:text-red-500 z-10"><X size={20}/></button>
                <AudioRecorder onComplete={() => setShowRecorder(false)} />
            </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <NotesProvider>
      <HashRouter>
        <div className="flex h-screen bg-gray-50 dark:bg-slate-950 overflow-hidden transition-colors">
          <Sidebar />
          <main className="flex-1 overflow-y-auto relative">
            <Routes>
              <Route path="/" element={<NotesPage />} />
              <Route path="/workspace" element={<Workspace />} />
              <Route path="/ideas" element={<IdeasPage />} />
              <Route path="/editor/:id" element={<NoteEditor />} />
              <Route path="/graph" element={<GraphView />} />
              <Route path="/chat" element={<ChatPage />} />
              <Route path="/trash" element={<TrashPage />} />
              <Route path="/settings" element={<SettingsPage />} />
            </Routes>
          </main>
          <QuickIdeasPanel />
        </div>
      </HashRouter>
    </NotesProvider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { ChevronLeft, Save, Trash2, ExternalLink, Eye, Edit3, Sparkles, Clock, Globe } from 'lucide-react';
import { getTagColor } from '../utils/tagColors.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, moveToTrash } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [isSaving, setIsSaving] = useState(false);
  const [note, setNote] = useState<any>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
      }
    }
  }, [id, notes]);

  const handleSave = async () => {
    setIsSaving(true);
    if (id === 'new') {
      await addNote(content, title);
    } else if (note) {
      await updateNote({ ...note, title, content });
    }
    setIsSaving(false);
    navigate('/');
  };

  const renderContentWithLinks = (text: string) => {
    const urlRegex = /(https?:\/\/[^\s]+)/g;
    const parts = text.split(urlRegex);
    return parts.map((part, i) => 
      urlRegex.test(part) 
        ? <a key={i} href={part} target="_blank" rel="noopener noreferrer" className="text-blue-500 underline hover:text-blue-600 inline-flex items-center gap-1 font-bold">
            {part} <ExternalLink size={12}/>
          </a> 
        : part
    );
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#0f172a] transition-colors">
      <div className="flex items-center justify-between px-8 py-4 border-b border-gray-100 dark:border-slate-800">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate(-1)} className="p-2 text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"><ChevronLeft/></button>
          <input 
            className="text-xl font-black bg-transparent border-none focus:outline-none dark:text-white w-96 tracking-tight" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок..."
          />
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')}
            className="p-3 bg-gray-50 dark:bg-slate-800 rounded-xl text-gray-500 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest transition-all hover:bg-gray-100 dark:hover:bg-slate-700"
          >
            {viewMode === 'edit' ? <><Eye size={16}/> Просмотр</> : <><Edit3 size={16}/> Правка</>}
          </button>
          {id !== 'new' && (
            <button 
              onClick={() => { if(confirm("Переместить в корзину?")) { moveToTrash(id!); navigate('/'); } }} 
              className="p-3 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-colors"
            >
              <Trash2 size={20}/>
            </button>
          )}
          <button 
            onClick={handleSave} 
            disabled={isSaving}
            className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-blue-700 shadow-xl shadow-blue-500/20 active:scale-95 transition-all"
          >
            {isSaving ? '...' : 'Сохранить'}
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 p-10 overflow-y-auto">
          {viewMode === 'edit' ? (
            <textarea 
              className="w-full h-full bg-transparent border-none focus:outline-none text-lg leading-relaxed dark:text-slate-300 resize-none font-medium"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Начните писать..."
            />
          ) : (
            <div className="prose dark:prose-invert max-w-none whitespace-pre-wrap text-lg leading-relaxed dark:text-slate-300 font-medium">
              {renderContentWithLinks(content)}
            </div>
          )}
        </div>

        <div className="w-80 border-l border-gray-100 dark:border-slate-800 p-8 space-y-8 bg-gray-50/30 dark:bg-slate-900/30 hidden lg:block">
          <section className="space-y-4">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Sparkles size={14} className="text-blue-500"/> ИИ Конспект
            </h4>
            <div className="p-5 bg-white dark:bg-slate-800 rounded-2xl border border-gray-100 dark:border-slate-800 shadow-sm italic text-xs text-gray-500 dark:text-slate-400 leading-relaxed">
              {note?.summary || "Сохраните заметку для автоматического резюме"}
            </div>
          </section>

          <section className="space-y-4">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Globe size={14} className="text-blue-500"/> Метаданные
            </h4>
            <div className="space-y-3 bg-white dark:bg-slate-800 p-5 rounded-2xl border border-gray-100 dark:border-slate-800">
              <div className="flex justify-between items-center">
                <span className="text-[9px] text-gray-400 uppercase font-black">Источник</span>
                <span className="text-[10px] font-black dark:text-white uppercase">{note?.sourceType || 'manual'}</span>
