import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  try {
    return JSON.parse(str);
  } catch (e) {
    const match = str.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (inner) { throw new Error("Invalid JSON structure"); }
    }
    const arrMatch = str.match(/\[[\s\S]*\]/);
    if (arrMatch) {
      try { return JSON.parse(arrMatch[0]); } catch (inner) { throw new Error("Invalid JSON Array structure"); }
    }
    throw new Error("No JSON found in AI response");
  }
};

export const testConnection = async (settings: Settings): Promise<{success: boolean, message: string}> => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: 'ping',
      });
      return { success: !!response.text, message: "Gemini API доступен" };
    }
    const url = settings.url.replace(/\/$/, '');
    const endpoint = settings.provider === AIProvider.Ollama ? `${url}/api/tags` : `${url}/models`;
    const res = await fetch(endpoint, { method: 'GET' });
    return res.ok ? { success: true, message: `Связь с ${settings.provider} установлена` } : { success: false, message: `Ошибка: ${res.status}` };
  } catch (e: any) {
    return { success: false, message: e.message || "Ошибка сети" };
  }
};

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `Проанализируй текст и верни ТОЛЬКО JSON: {"tags": ["тег1"], "category": "Категория", "summary": "Резюме"}. Текст: ${text}`;
  return await callAI(prompt, settings, true);
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Разбей этот большой текст на несколько тематических карточек. Верни ТОЛЬКО массив JSON объектов вида: [{"title": "Заголовок блока", "content": "Текст блока", "category": "Категория", "tags": ["тег"]}]. Текст: ${text}`;
  return await callAI(prompt, settings, true);
};

async function callAI(prompt: string, settings: Settings, isJson: boolean) {
  if (settings.provider === AIProvider.Gemini) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: isJson ? { responseMimeType: "application/json" } : undefined
    });
    return extractJSON(response.text || (isJson ? '[]' : ''));
  }

  const url = settings.url.replace(/\/$/, '') + (settings.provider === AIProvider.Ollama ? '/api/generate' : '/chat/completions');
  const body = settings.provider === AIProvider.Ollama 
    ? { model: settings.model, prompt, stream: false, format: isJson ? 'json' : undefined }
    : { model: settings.model, messages: [{ role: 'user', content: prompt }], response_format: isJson ? { type: 'json_object' } : undefined };

  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(settings.apiKey ? { 'Authorization': `Bearer ${settings.apiKey}` } : {}) },
    body: JSON.stringify(body)
  });
  const data = await res.json();
  const resultStr = settings.provider === AIProvider.Ollama ? data.response : data.choices[0].message.content;
  return isJson ? extractJSON(resultStr) : resultStr;
}

export const chatWithNotes = async (query: string, context: string, settings: Settings): Promise<string> => {
  const prompt = `Контекст:\n${context}\n\nВопрос: ${query}`;
  return await callAI(prompt, settings, false);
};

