export type NoteStatus = 'new' | 'in-work' | 'read' | 'finished' | 'trash' | 'archived';

export interface Note {
  id: string;
  title: string;
  content: string;
  tags: string[];
  category: string;
  summary: string;
  links: string[];
  createdAt: string;
  updatedAt: string;
  status: NoteStatus;
  sourceType?: 'manual' | 'ocr' | 'audio' | 'telegram' | 'split';
  // Add position and size for spatial workspace
  position?: { x: number; y: number };
  size?: { w: number; h: number };
}

export enum AIProvider {
  Ollama = 'Ollama',
  LMStudio = 'LM Studio',
  OpenRouter = 'OpenRouter',
  Gemini = 'Gemini'
}

export interface Settings {
  provider: AIProvider;
  url: string;
  model: string;
  apiKey: string;
  theme: 'light' | 'dark';
  transcriptionModel: string;
}

export interface AppLog {
  id: string;
  timestamp: string;
  level: 'info' | 'error' | 'warn' | 'success';
  message: string;
  details?: string;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  sources?: string[];
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  setFilterTag: (tag: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  // Fix: Add missing methods required by SettingsPage and Workspace
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s] = await Promise.all([storage.getNotes(), storage.getSettings()]);
      setNotes(n);
      setSettings(s);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
      addLog('success', 'ScreenMind Core Ready');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true) => {
    let analysis = { tags: [], category: 'Общее', summary: '' };
    if (useAI) {
      addLog('info', 'ИИ анализирует запись...');
      try { analysis = await ai.analyzeText(content, settings); } catch (e) { addLog('warn', 'ИИ не ответил, сохраняю как черновик'); }
    }

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40) + '...',
      content,
      tags: analysis.tags || [],
      category: analysis.category || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      sourceType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      // Fix: Add default position and size
      position: { x: Math.random() * 400 + 100, y: Math.random() * 400 + 100 },
      size: { w: 300, h: 250 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', `Заметка создана: ${newNote.title}`);
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'Разбиение большого текста на карточки...');
    try {
      const blocks = await ai.splitLargeText(text, settings);
      const newNotes: Note[] = blocks.map((b: any) => ({
        id: crypto.randomUUID(),
        title: b.title,
        content: b.content,
        tags: b.tags || [],
        category: b.category || 'Импорт',
        summary: '',
        status: 'new',
        sourceType: 'split',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        links: [],
        // Fix: Add default position and size for split notes
        position: { x: Math.random() * 400 + 100, y: Math.random() * 400 + 100 },
        size: { w: 300, h: 250 }
      }));
      const updated = [...newNotes, ...notes];
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('success', `Создано ${newNotes.length} тематических карточек`);
    } catch (e) {
      addLog('error', 'Не удалось разбить текст', String(e));
      await addNote(text, 'Необработанный импорт', 'manual', false);
    }
  };

  const runAIAnalysis = async (id: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return;
    addLog('info', `ИИ анализирует "${note.title}"...`);
    try {
      const res = await ai.analyzeText(note.content, settings);
      const updated = notes.map(n => n.id === id ? { ...n, ...res, updatedAt: new Date().toISOString() } : n);
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('success', 'Анализ завершен');
    } catch (e) { addLog('error', 'Ошибка анализа ИИ'); }
  };

  const moveToTrash = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const restoreNote = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'new' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const hardDelete = async (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNote = async (n: Note) => {
    const updated = notes.map(x => x.id === n.id ? n : x);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const reanalyzeAll = async () => {
    addLog('info', 'Запуск пакетной переиндексации...');
    const updated = [...notes];
    for (let i = 0; i < updated.length; i++) {
      try {
        const res = await ai.analyzeText(updated[i].content, settings);
        updated[i] = { ...updated[i], ...res };
      } catch (e) {}
    }
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', 'База знаний обновлена');
  };

  // Fix: Implement system check
  const runSystemCheck = async () => {
    addLog('info', 'Проверка связи с ИИ-провайдером...');
    const result = await ai.testConnection(settings);
    if (result.success) {
      addLog('success', result.message);
    } else {
      addLog('error', 'Ошибка проверки', result.message);
    }
  };

  // Fix: Implement position update for workspace
  const updateNotePosition = async (id: string, x: number, y: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  // Fix: Implement size update for workspace
  const updateNoteSize = async (id: string, w: number, h: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  return (
    <NotesContext.Provider value={{ 
      notes, settings, isLoading, logs, filterTag, setFilterTag, addNote, processLargeText, updateNote, moveToTrash, restoreNote, hardDelete,
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck, updateNotePosition, updateNoteSize
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useEffect, useRef, useState } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import * as d3 from 'https://cdn.jsdelivr.net/npm/d3@7/+esm';
import { useNavigate } from 'react-router-dom';
import { getTagColor } from '../utils/tagColors.ts';
import { BrainCircuit, Layers, Share2, RotateCcw } from 'lucide-react';

const GraphView: React.FC = () => {
  const { notes } = useNotes();
  const navigate = useNavigate();
  const svgRef = useRef<SVGSVGElement>(null);
  const [mode, setMode] = useState<'neural' | 'tree'>('neural');

  useEffect(() => {
    if (!svgRef.current || notes.length === 0) return;

    const width = svgRef.current.clientWidth;
    const height = svgRef.current.clientHeight;

    // Fix: Removed isRead and isUsed which do not exist on Note type
    const nodes = notes.map(n => ({ 
        id: n.id, 
        title: n.title, 
        group: n.category,
        color: getTagColor(n.category).text
    }));

    const links: any[] = [];
    notes.forEach((n, i) => {
      notes.slice(i + 1).forEach(m => {
        const commonTags = n.tags.filter(t => m.tags.includes(t));
        if (commonTags.length > 0) {
          links.push({ source: n.id, target: m.id, value: commonTags.length + 3 });
        } else if (n.category === m.category) {
          links.push({ source: n.id, target: m.id, value: 1 });
        }
      });
    });

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const g = svg.append("g");
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 8])
      .on("zoom", (event) => g.attr("transform", event.transform));

    svg.call(zoom);

    if (mode === 'neural') {
        const simulation = d3.forceSimulation(nodes as any)
            .force("link", d3.forceLink(links).id((d: any) => d.id).distance(150))
            .force("charge", d3.forceManyBody().strength(-300))
            .force("center", d3.forceCenter(width / 2, height / 2))
            .force("collision", d3.forceCollide().radius(50));

        const link = g.append("g")
            .attr("stroke", "#cbd5e1")
            .attr("stroke-opacity", 0.3)
            .selectAll("line")
            .data(links)
            .join("line")
            .attr("stroke-width", d => Math.sqrt(d.value) * 1.5);

        const node = g.append("g")
            .selectAll("g")
            .data(nodes)
            .join("g")
            .attr("cursor", "pointer")
            .on("click", (e, d: any) => navigate(`/editor/${d.id}`))
            .call(d3.drag<any, any>()
                .on("start", (e, d) => { if (!e.active) simulation.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; })
                .on("drag", (e, d) => { d.fx = e.x; d.fy = e.y; })
                .on("end", (e, d) => { if (!e.active) simulation.alphaTarget(0); d.fx = null; d.fy = null; }));

        node.append("circle").attr("r", 12).attr("fill", (d: any) => d.color).attr("stroke", "#fff").attr("stroke-width", 2);
        node.append("text").attr("dy", 25).attr("text-anchor", "middle").attr("font-size", "10px").attr("font-weight", "800").text(d => d.title.slice(0, 15));

        simulation.on("tick", () => {
            link.attr("x1", (d: any) => d.source.x).attr("y1", (d: any) => d.source.y).attr("x2", (d: any) => d.target.x).attr("y2", (d: any) => d.target.y);
            node.attr("transform", (d: any) => `translate(${d.x},${d.y})`);
        });
    } else {
        // Simple Hierarchical Mode (Group by Category)
        const categories = Array.from(new Set(notes.map(n => n.category)));
        const catNodes = categories.map((cat, i) => ({ id: `cat-${i}`, title: cat, isCat: true, color: getTagColor(cat).text }));
        const allNodes = [...catNodes, ...nodes];
        const catLinks = notes.map(n => ({ source: `cat-${categories.indexOf(n.category)}`, target: n.id, value: 1 }));

        const simulation = d3.forceSimulation(allNodes as any)
            .force("link", d3.forceLink(catLinks).id((d: any) => d.id).distance(80))
            .force("charge", d3.forceManyBody().strength(-200))
            .force("center", d3.forceCenter(width / 2, height / 2));

        const link = g.append("g").attr("stroke", "#e2e8f0").selectAll("line").data(catLinks).join("line").attr("stroke-width", 1);
        const node = g.append("g").selectAll("g").data(allNodes).join("g").attr("cursor", "pointer")
            .on("click", (e, d: any) => !d.isCat && navigate(`/editor/${d.id}`));

        node.append("circle").attr("r", (d: any) => d.isCat ? 20 : 8).attr("fill", (d: any) => d.color);
        node.append("text").attr("dy", 30).attr("text-anchor", "middle").attr("font-size", (d: any) => d.isCat ? "12px" : "8px").attr("font-weight", "bold").text(d => d.title);

        simulation.on("tick", () => {
            link.attr("x1", (d: any) => d.source.x).attr("y1", (d: any) => d.source.y).attr("x2", (d: any) => d.target.x).attr("y2", (d: any) => d.target.y);
            node.attr("transform", (d: any) => `translate(${d.x},${d.y})`);
        });
    }
  }, [notes, navigate, mode]);

  return (
    <div className="flex-1 flex flex-col h-screen overflow-hidden bg-white dark:bg-slate-900 transition-colors">
      <div className="px-12 py-10 flex justify-between items-end relative z-10">
        <div>
            <h2 className="text-3xl font-black text-gray-900 dark:text-white leading-none">Карта Сознания</h2>
            <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mt-2">Визуализация {mode === 'neural' ? 'ассоциаций' : 'структуры'}</p>
        </div>
        <div className="flex gap-2 bg-gray-50 dark:bg-slate-800 p-2 rounded-2xl">
            <button onClick={() => setMode('neural')} className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${mode === 'neural' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-gray-600'}`}>
                <Share2 size={14} /> Нейронная
            </button>
            <button onClick={() => setMode('tree')} className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${mode === 'tree' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-gray-400 hover:text-gray-600'}`}>
                <Layers size={14} /> Дерево
            </button>
        </div>
      </div>
      <div className="flex-1 relative bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] dark:bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:32px_32px]">
        <svg ref={svgRef} className="w-full h-full" />
      </div>
    </div>
  );
};

export default GraphView;

import React, { useState, useMemo } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { NotesProvider, useNotes } from './contexts/NotesContext.tsx';
import Sidebar from './components/Sidebar.tsx';
import NotesPage from './pages/NotesPage.tsx';
import NoteEditor from './pages/NoteEditor.tsx';
import GraphView from './pages/GraphView.tsx';
import ChatPage from './pages/ChatPage.tsx';
import SettingsPage from './pages/SettingsPage.tsx';
import IdeasPage from './pages/IdeasPage.tsx';
import TrashPage from './pages/TrashPage.tsx';
import AudioRecorder from './components/AudioRecorder.tsx';
import { Send, Loader2, Mic, X, Hash, BarChart3, Zap } from 'lucide-react';
import { getTagColor } from './utils/tagColors.ts';

const QuickIdeasPanel: React.FC = () => {
  const { addNote, notes } = useNotes();
  const [idea, setIdea] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRecorder, setShowRecorder] = useState(false);

  const activeNotes = notes.filter(n => n.status !== 'trash');

  const activeTags = useMemo(() => {
    const counts: Record<string, number> = {};
    activeNotes.forEach(n => n.tags.forEach(t => counts[t] = (counts[t] || 0) + 1));
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 8);
  }, [activeNotes]);

  const stats = useMemo(() => ({
    total: activeNotes.length,
    new: activeNotes.filter(n => n.status === 'new').length,
    finished: activeNotes.filter(n => n.status === 'finished').length,
  }), [activeNotes]);

  const handleSaveIdea = async () => {
    if (!idea.trim()) return;
    setIsSaving(true);
    // Fix: Fourth argument must be a boolean (useAI). AI will categorize it if useAI is true.
    await addNote(idea, `Идея: ${idea.slice(0, 20)}`, 'manual', true);
    setIdea('');
    setIsSaving(false);
  };

  return (
    <div className="w-80 bg-white dark:bg-[#080c14] border-l border-gray-100 dark:border-slate-800 h-screen flex flex-col hidden xl:flex transition-colors shrink-0 z-10">
      <div className="p-6 border-b border-gray-50 dark:border-slate-800">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-black text-[10px] uppercase tracking-widest text-gray-400 flex items-center gap-2">
            <Zap size={14} className="text-amber-500" /> Быстрый фокус
          </h3>
          <button onClick={() => setShowRecorder(true)} className="p-2 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl transition-all">
            <Mic size={18} />
          </button>
        </div>
        <div className="relative group">
          <textarea 
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="Запишите мысль..."
            className="w-full h-28 p-4 bg-gray-50 dark:bg-slate-800/50 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 text-sm font-medium text-gray-700 dark:text-slate-200 placeholder:text-gray-300 dark:placeholder:text-slate-600 resize-none transition-all"
          />
          <button 
            onClick={handleSaveIdea}
            disabled={isSaving || !idea.trim()}
            className="absolute bottom-3 right-3 p-2.5 bg-blue-600 text-white rounded-xl shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-all disabled:opacity-30 active:scale-95"
          >
            {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        <section>
          <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
            <Hash size={12} /> Популярное
          </h4>
          <div className="flex flex-wrap gap-2">
            {activeTags.map(([tag, count]) => {
              const colors = getTagColor(tag);
              return (
                <div key={tag} style={{ color: colors.text, backgroundColor: colors.bg }} className="px-3 py-1.5 rounded-xl transition-all flex items-center gap-2 border border-black/5">
                  <span className="text-[10px] font-black italic">#{tag}</span>
                  <span className="text-[8px] font-black bg-white/50 px-1.5 rounded-md">{count}</span>
                </div>
              );
            })}
          </div>
        </section>
      </div>

      <div className="p-6 bg-gray-50 dark:bg-[#06080c] border-t border-gray-100 dark:border-slate-800">
        <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
          <BarChart3 size={12} /> Аналитика
        </h4>
        <div className="grid grid-cols-2 gap-3">
          <div className="p-3 bg-white dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-800 shadow-sm">
            <span className="block text-[8px] font-black text-blue-500 uppercase">База</span>
            <span className="text-xl font-black dark:text-white">{stats.total}</span>
          </div>
          <div className="p-3 bg-white dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-800 shadow-sm">
            <span className="block text-[8px] font-black text-green-500 uppercase">Финал</span>
            <span className="text-xl font-black dark:text-white">{stats.finished}</span>
          </div>
        </div>
      </div>

      {showRecorder && (
        <div className="fixed inset-0 z-[100] bg-black/40 backdrop-blur-sm flex items-center justify-center p-6">
            <div className="relative max-w-md w-full animate-slide-up">
                <button onClick={() => setShowRecorder(false)} className="absolute -top-4 -right-4 bg-white dark:bg-slate-800 p-2 rounded-full shadow-xl text-gray-400 hover:text-red-500 z-10"><X size={20}/></button>
                <AudioRecorder onComplete={() => setShowRecorder(false)} />
            </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <NotesProvider>
      <HashRouter>
        <div className="flex h-screen bg-gray-50 dark:bg-slate-950 overflow-hidden transition-colors">
          <Sidebar />
          <main className="flex-1 overflow-y-auto relative custom-scrollbar">
            <Routes>
              <Route path="/" element={<NotesPage />} />
              <Route path="/ideas" element={<IdeasPage />} />
              <Route path="/editor/:id" element={<NoteEditor />} />
              <Route path="/graph" element={<GraphView />} />
              <Route path="/chat" element={<ChatPage />} />
              <Route path="/trash" element={<TrashPage />} />
              <Route path="/settings" element={<SettingsPage />} />
            </Routes>
          </main>
          <QuickIdeasPanel />
        </div>
      </HashRouter>
    </NotesProvider>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { useNavigate } from 'react-router-dom';
import { Maximize2, Move, Link2, ExternalLink, Clock, Sparkles } from 'lucide-react';
import { getTagColor } from '../utils/tagColors.ts';

const Workspace: React.FC = () => {
  const { notes, updateNotePosition } = useNotes();
  const navigate = useNavigate();
  const containerRef = useRef<HTMLDivElement>(null);

  // Fix: activeNotes should react to notes updates
  const activeNotes = useMemo(() => notes.filter(n => n.status !== 'trash' && n.status !== 'archived'), [notes]);

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if ((e.target as HTMLElement).closest('.resize-handle')) return;
    setDraggingId(id);
    const note = notes.find(n => n.id === id);
    // Fix: Added check for note and position
    if (note && note.position) {
      setOffset({ x: e.clientX - note.position.x, y: e.clientY - note.position.y });
    }
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (draggingId) {
      updateNotePosition(draggingId, e.clientX - offset.x, e.clientY - offset.y);
    }
  };

  const handleMouseUp = () => setDraggingId(null);

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [draggingId, offset]);

  return (
    <div ref={containerRef} className="flex-1 h-screen relative overflow-hidden bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] dark:bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:40px_40px] transition-colors">
      <div className="absolute top-10 left-12 z-10">
        <h2 className="text-3xl font-black dark:text-white">Пространство</h2>
        <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mt-2 flex items-center gap-2">
            <Move size={12} className="text-blue-500" /> Перетаскивайте и связывайте идеи
        </p>
      </div>

      <div className="absolute inset-0">
        {activeNotes.map(note => {
          const colors = getTagColor(note.category);
          return (
            <div
              key={note.id}
              onMouseDown={(e) => handleMouseDown(e, note.id)}
              style={{
                // Fix: Added null safety for position and size
                left: note.position?.x ?? 0,
                top: note.position?.y ?? 0,
                width: note.size?.w ?? 300,
                height: note.size?.h ?? 250,
                zIndex: draggingId === note.id ? 100 : 1
              }}
              className="absolute bg-white dark:bg-slate-900 rounded-[2rem] border border-gray-100 dark:border-slate-800 shadow-xl shadow-black/5 flex flex-col group cursor-grab active:cursor-grabbing transition-shadow hover:shadow-2xl overflow-hidden"
            >
              <div className="px-6 py-4 flex items-center justify-between border-b border-gray-50 dark:border-slate-800">
                <span style={{ color: colors.text, backgroundColor: colors.bg }} className="text-[8px] font-black uppercase px-2 py-0.5 rounded-md">
                    {note.category}
                </span>
                <button onClick={() => navigate(`/editor/${note.id}`)} className="p-1.5 text-gray-300 hover:text-blue-500 rounded-lg transition-colors">
                    <Maximize2 size={14} />
                </button>
              </div>

              <div className="p-6 flex-1 overflow-hidden">
                <h3 className="font-extrabold text-sm mb-2 dark:text-white line-clamp-1">{note.title}</h3>
                <p className="text-xs text-gray-500 dark:text-slate-400 leading-relaxed line-clamp-4">{note.content}</p>
              </div>

              <div className="px-6 py-4 bg-gray-50/50 dark:bg-slate-800/50 flex items-center justify-between">
                <div className="flex gap-1">
                    {note.tags.slice(0, 2).map(t => <span key={t} className="text-[8px] text-gray-400 font-bold">#{t}</span>)}
                </div>
                <div className="flex items-center gap-2 text-[8px] font-black text-gray-300 uppercase tracking-widest">
                    <Clock size={10}/> {new Date(note.createdAt).toLocaleDateString()}
                </div>
              </div>

              <div className="absolute bottom-1 right-1 cursor-nwse-resize opacity-0 group-hover:opacity-100 transition-opacity p-1 text-gray-300 resize-handle">
                <Maximize2 size={12} className="rotate-90" />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

