  const { notes, addNote, updateNote, runAIAnalysis, setNoteStatus } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [isSaving, setIsSaving] = useState(false);
  const [note, setNote] = useState<any>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
      }
    }
  }, [id, notes]);

  const handleSave = async (useAI = false) => {
    setIsSaving(true);
    if (id === 'new') {
      await addNote(content, title, 'manual', useAI);
    } else if (note) {
      await updateNote({ ...note, title, content });
      if (useAI) await runAIAnalysis(note.id);
    }
    setIsSaving(false);
    navigate('/');
  };

  const changeStatus = async (status: NoteStatus) => {
    if (note) {
      await setNoteStatus(note.id, status);
      setNote({ ...note, status });
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] transition-colors">
