        <div className="flex items-center gap-4">
          {note && (
            <div className="flex bg-gray-50 dark:bg-slate-900 p-1.5 rounded-2xl gap-1">
              <button onClick={() => changeStatus('in-work')} className={`p-3 rounded-xl transition-all ${note.status === 'in-work' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`} title="В работу"><PlayCircle size={18}/></button>
              <button onClick={() => changeStatus('finished')} className={`p-3 rounded-xl transition-all ${note.status === 'finished' ? 'bg-green-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`} title="Готово"><CheckCircle2 size={18}/></button>
