          >
            <Sparkles size={18}/> {note?.tags.length ? 'Переанализировать' : 'Магия ИИ'}
          </button>

          <button 
            onClick={() => handleSave(false)} 
            disabled={isSaving}
            className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-blue-700 shadow-xl shadow-blue-500/20 active:scale-95 transition-all"
          >
            Сохранить
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 p-16 overflow-y-auto">
          {viewMode === 'edit' ? (
            <textarea 
              className="w-full h-full bg-transparent border-none focus:outline-none text-xl leading-relaxed dark:text-slate-300 resize-none font-medium placeholder:text-gray-100"
