export default SettingsPage;

export type NoteStatus = 'new' | 'in-work' | 'read' | 'finished' | 'trash' | 'archived';

export interface Note {
  id: string;
  title: string;
  content: string;
  tags: string[];
  category: string;
  summary: string;
  links: string[];
  createdAt: string;
  updatedAt: string;
  status: NoteStatus;
  sourceType?: 'manual' | 'ocr' | 'audio' | 'telegram' | 'split';
  position?: { x: number; y: number };
  size?: { w: number; h: number };
}

export enum AIProvider {
  Ollama = 'Ollama',
  LMStudio = 'LM Studio',
  OpenRouter = 'OpenRouter',
  Gemini = 'Gemini'
}

export interface Settings {
  provider: AIProvider;
  url: string;
  model: string;
  apiKey: string;
  theme: 'light' | 'dark';
  transcriptionModel: string;
  // Telegram Integration
  tgToken: string;
  tgChatId: string;
  tgLastUpdateId: number;
}

export interface TelegramMessage {
  id: number;
  text: string;
  date: string;
  from: string;
  type: 'text' | 'photo' | 'document';
}

export interface AppLog {
  id: string;
  timestamp: string;
  level: 'info' | 'error' | 'warn' | 'success';
  message: string;
  details?: string;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  sources?: string[];
}

import { get, set } from 'https://cdn.jsdelivr.net/npm/idb-keyval@6/+esm';
import { Note, Settings, AIProvider } from '../types.ts';

const NOTES_KEY = 'screenmind_notes';
const SETTINGS_KEY = 'screenmind_settings';

export const saveNotes = async (notes: Note[]) => {
  await set(NOTES_KEY, notes);
};

export const getNotes = async (): Promise<Note[]> => {
  const notes = await get(NOTES_KEY);
  return notes || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  provider: AIProvider.Ollama,
  url: 'http://localhost:11434',
  model: 'mistral',
  transcriptionModel: 'whisper-large-v3',
  apiKey: '',
  theme: 'light',
  tgToken: '',
  tgChatId: '',
  tgLastUpdateId: 0
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return settings || getDefaultSettings();
};

export const exportData = async () => {
  const notes = await getNotes();
  const settings = await getSettings();
  const data = JSON.stringify({ notes, settings, version: '2.8', exportedAt: new Date().toISOString() }, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `screenmind_v2.8_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  telegramMessages: TelegramMessage[];
  setFilterTag: (tag: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<TelegramMessage[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s] = await Promise.all([storage.getNotes(), storage.getSettings()]);
      setNotes(n);
      setSettings(s);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
      addLog('success', 'ScreenMind Engine v2.8 Инициализирован');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true) => {
    let analysis = { tags: [], category: 'Новое', summary: '' };
    if (useAI) {
      addLog('info', 'ИИ анализирует контент...');
      try { analysis = await ai.analyzeText(content, settings); } catch (e) { addLog('warn', 'ИИ не доступен, сохраняю без анализа'); }
    }

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: analysis.category || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      sourceType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: 100 + Math.random() * 200, y: 100 + Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', `Создано: ${newNote.title}`);
  };

  const syncTelegram = async () => {
    if (!settings.tgToken) {
      addLog('warn', 'Telegram токен не настроен');
      return;
    }
    addLog('info', 'Синхронизация с Telegram...');
    try {
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${settings.tgLastUpdateId + 1}`);
      const data = await response.json();
      if (data.ok && data.result.length > 0) {
        const newMsgs: TelegramMessage[] = data.result
          .filter((u: any) => u.message && (u.message.text || u.message.caption))
          .map((u: any) => ({
            id: u.update_id,
            text: u.message.text || u.message.caption,
            from: u.message.from.first_name || 'Anonymous',
            date: new Date(u.message.date * 1000).toISOString(),
            type: 'text'
          }));

        setTelegramMessages(prev => [...newMsgs, ...prev]);
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
        addLog('success', `Получено ${newMsgs.length} сообщений из Telegram`);
      } else {
        addLog('info', 'Новых сообщений в Telegram нет');
      }
    } catch (e) {
      addLog('error', 'Ошибка связи с Telegram', String(e));
    }
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'Разбиение текста на смысловые блоки...');
    try {
      const blocks = await ai.splitLargeText(text, settings);
      const newNotes: Note[] = blocks.map((b: any) => ({
        id: crypto.randomUUID(),
        title: b.title,
        content: b.content,
        tags: b.tags || [],
        category: b.category || 'Импорт',
        summary: '',
        status: 'new',
        sourceType: 'split',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        links: [],
        position: { x: 100 + Math.random() * 300, y: 100 + Math.random() * 300 },
        size: { w: 300, h: 250 }
      }));
      const updated = [...newNotes, ...notes];
      setNotes(updated);
      await storage.saveNotes(updated);
      addLog('success', `Импортировано ${newNotes.length} блоков`);
    } catch (e) {
      addLog('error', 'ИИ не смог разбить текст автоматически');
      await addNote(text, 'Сырой импорт', 'manual', false);
    }
  };

  const runSystemCheck = async () => {
    addLog('info', `Проверка ${settings.provider}...`);
    const res = await ai.testConnection(settings);
    if (res.success) addLog('success', res.message);
    else addLog('error', res.message);
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
    addLog('info', 'Настройки сохранены');
  };

  const reanalyzeAll = async () => {
    addLog('info', 'Начат глобальный переанализ базы...');
    const updated = [...notes];
    for (let i = 0; i < updated.length; i++) {
      try {
        const res = await ai.analyzeText(updated[i].content, settings);
        updated[i] = { ...updated[i], ...res, updatedAt: new Date().toISOString() };
      } catch (e) {
        addLog('warn', `Не удалось проанализировать: ${updated[i].title}`);
      }
    }
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', 'База знаний успешно переиндексирована');
  };

  const moveToTrash = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const restoreNote = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'new' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const hardDelete = async (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNote = async (n: Note) => {
    const updated = notes.map(x => x.id === n.id ? n : x);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNotePosition = async (id: string, x: number, y: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNoteSize = async (id: string, w: number, h: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const runAIAnalysis = async (id: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return;
    try {
      const res = await ai.analyzeText(note.content, settings);
      const updated = notes.map(n => n.id === id ? { ...n, ...res, updatedAt: new Date().toISOString() } : n);
      setNotes(updated);
      await storage.saveNotes(updated);
    } catch (e) {}
  };

  return (
    <NotesContext.Provider value={{ 
      notes, settings, isLoading, logs, filterTag, telegramMessages,
      setFilterTag, addNote, processLargeText, updateNote, moveToTrash, restoreNote, hardDelete,
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck, updateNotePosition, updateNoteSize, syncTelegram
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

