import NoteEditor from './pages/NoteEditor.tsx';
import GraphView from './pages/GraphView.tsx';
import ChatPage from './pages/ChatPage.tsx';
import SettingsPage from './pages/SettingsPage.tsx';
import IdeasPage from './pages/IdeasPage.tsx';
import TrashPage from './pages/TrashPage.tsx';
import TelegramPage from './pages/TelegramPage.tsx';
import AudioRecorder from './components/AudioRecorder.tsx';
import { Send, Loader2, Mic, X, Hash, BarChart3, Zap } from 'lucide-react';
import { getTagColor } from './utils/tagColors.ts';

const QuickIdeasPanel: React.FC = () => {
  const { addNote, notes } = useNotes();
  const [idea, setIdea] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRecorder, setShowRecorder] = useState(false);

  const activeNotes = notes.filter(n => n.status !== 'trash');

  const activeTags = useMemo(() => {
    const counts: Record<string, number> = {};
    activeNotes.forEach(n => n.tags.forEach(t => counts[t] = (counts[t] || 0) + 1));
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 8);
  }, [activeNotes]);

  const stats = useMemo(() => ({
    total: activeNotes.length,
    new: activeNotes.filter(n => n.status === 'new').length,
    finished: activeNotes.filter(n => n.status === 'finished').length,
  }), [activeNotes]);

  const handleSaveIdea = async () => {
    if (!idea.trim()) return;
    setIsSaving(true);
    await addNote(idea, `Идея: ${idea.slice(0, 20)}`, 'manual', true);
    setIdea('');
    setIsSaving(false);
  };

  return (
    <div className="w-80 bg-white dark:bg-[#080c14] border-l border-gray-100 dark:border-slate-800 h-screen flex flex-col hidden xl:flex transition-colors shrink-0 z-10">
      <div className="p-6 border-b border-gray-50 dark:border-slate-800">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-black text-[10px] uppercase tracking-widest text-gray-400 flex items-center gap-2">
            <Zap size={14} className="text-amber-500" /> Быстрый фокус
          </h3>
          <button onClick={() => setShowRecorder(true)} className="p-2 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-xl transition-all">
            <Mic size={18} />
          </button>
        </div>
        <div className="relative group">
          <textarea 
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="Запишите мысль..."
            className="w-full h-28 p-4 bg-gray-50 dark:bg-slate-800/50 border-none rounded-2xl focus:ring-2 focus:ring-blue-500/20 text-sm font-medium text-gray-700 dark:text-slate-200 placeholder:text-gray-300 dark:placeholder:text-slate-600 resize-none transition-all"
          />
          <button 
            onClick={handleSaveIdea}
            disabled={isSaving || !idea.trim()}
            className="absolute bottom-3 right-3 p-2.5 bg-blue-600 text-white rounded-xl shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-all disabled:opacity-30 active:scale-95"
          >
            {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        <section>
          <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
            <Hash size={12} /> Популярное
          </h4>
          <div className="flex flex-wrap gap-2">
            {activeTags.map(([tag, count]) => {
              const colors = getTagColor(tag);
              return (
                <div key={tag} style={{ color: colors.text, backgroundColor: colors.bg }} className="px-3 py-1.5 rounded-xl transition-all flex items-center gap-2 border border-black/5">
                  <span className="text-[10px] font-black italic">#{tag}</span>
                  <span className="text-[8px] font-black bg-white/50 px-1.5 rounded-md">{count}</span>
                </div>
              );
            })}
          </div>
        </section>
      </div>

      <div className="p-6 bg-gray-50 dark:bg-[#06080c] border-t border-gray-100 dark:border-slate-800">
        <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
          <BarChart3 size={12} /> Аналитика
        </h4>
        <div className="grid grid-cols-2 gap-3">
          <div className="p-3 bg-white dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-800 shadow-sm">
            <span className="block text-[8px] font-black text-blue-500 uppercase">База</span>
            <span className="text-xl font-black dark:text-white">{stats.total}</span>
          </div>
          <div className="p-3 bg-white dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-800 shadow-sm">
            <span className="block text-[8px] font-black text-green-500 uppercase">Финал</span>
            <span className="text-xl font-black dark:text-white">{stats.finished}</span>
          </div>
        </div>
      </div>

      {showRecorder && (
        <div className="fixed inset-0 z-[100] bg-black/40 backdrop-blur-sm flex items-center justify-center p-6">
            <div className="relative max-w-md w-full animate-slide-up">
                <button onClick={() => setShowRecorder(false)} className="absolute -top-4 -right-4 bg-white dark:bg-slate-800 p-2 rounded-full shadow-xl text-gray-400 hover:text-red-500 z-10"><X size={20}/></button>
                <AudioRecorder onComplete={() => setShowRecorder(false)} />
            </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <NotesProvider>
      <HashRouter>
        <div className="flex h-screen bg-gray-50 dark:bg-slate-950 overflow-hidden transition-colors">
          <Sidebar />
          <main className="flex-1 overflow-y-auto relative custom-scrollbar">
            <Routes>
              <Route path="/" element={<NotesPage />} />
              <Route path="/telegram" element={<TelegramPage />} />
              <Route path="/ideas" element={<IdeasPage />} />
              <Route path="/editor/:id" element={<NoteEditor />} />
              <Route path="/graph" element={<GraphView />} />
              <Route path="/chat" element={<ChatPage />} />
              <Route path="/trash" element={<TrashPage />} />
              <Route path="/settings" element={<SettingsPage />} />
            </Routes>
          </main>
          <QuickIdeasPanel />
        </div>
      </HashRouter>
