import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  try {
    return JSON.parse(str);
  } catch (e) {
    const match = str.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (inner) { throw new Error("Invalid JSON structure"); }
    }
    const arrMatch = str.match(/\[[\s\S]*\]/);
    if (arrMatch) {
      try { return JSON.parse(arrMatch[0]); } catch (inner) { throw new Error("Invalid JSON Array structure"); }
    }
    throw new Error("No JSON found in AI response");
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part, i) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline hover:text-blue-600 transition-colors">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  const url = `https://www.google.com/search?q=${encodeURIComponent(query)}`;
  window.open(url, '_blank');
};

export const testConnection = async (settings: Settings): Promise<{success: boolean, message: string}> => {
  try {
    if (settings.provider === AIProvider.Gemini) {
      const key = settings.apiKey || process.env.API_KEY;
      if (!key) return { success: false, message: "API ключ Gemini не задан" };
      const ai = new GoogleGenAI({ apiKey: key });
      const response = await ai.models.generateContent({
        model: settings.model || 'gemini-3-flash-preview',
        contents: 'ping',
      });
      return { success: !!response.text, message: "Gemini API доступен" };
    }

    if (settings.provider === AIProvider.OpenRouter) {
      if (!settings.apiKey) return { success: false, message: "API ключ OpenRouter не задан" };
      const res = await fetch("https://openrouter.ai/api/v1/auth/key", {
        headers: { "Authorization": `Bearer ${settings.apiKey}` }
      });
      return res.ok ? { success: true, message: "OpenRouter авторизован" } : { success: false, message: "Ошибка ключа OpenRouter" };
    }

    const url = settings.url.replace(/\/$/, '');
    const endpoint = settings.provider === AIProvider.Ollama ? `${url}/api/tags` : `${url}/v1/models`;
    const res = await fetch(endpoint, { method: 'GET' });
    return res.ok ? { success: true, message: `Связь с ${settings.provider} установлена` } : { success: false, message: `Ошибка: ${res.status}` };
  } catch (e: any) {
    return { success: false, message: e.message || "Ошибка сети" };
  }
};

async function callAI(prompt: string, settings: Settings, isJson: boolean) {
  if (settings.provider === AIProvider.Gemini) {
    const key = settings.apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: settings.model || 'gemini-3-flash-preview',
      contents: prompt,
      config: isJson ? { responseMimeType: "application/json" } : undefined
    });
    return isJson ? extractJSON(response.text || '{}') : response.text;
  }

  const isOllama = settings.provider === AIProvider.Ollama;
  const isOR = settings.provider === AIProvider.OpenRouter;

  let url = settings.url.replace(/\/$/, '');
  if (isOllama) url += '/api/generate';
  else if (isOR) url = 'https://openrouter.ai/api/v1/chat/completions';
  else url += '/v1/chat/completions';

  const body: any = isOllama 
    ? { model: settings.model, prompt, stream: false, format: isJson ? 'json' : undefined }
    : { 
        model: settings.model, 
        messages: [{ role: 'user', content: prompt }],
        response_format: isJson ? { type: 'json_object' } : undefined 
      };

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (settings.apiKey) headers['Authorization'] = `Bearer ${settings.apiKey}`;
  if (isOR) {
    headers['HTTP-Referer'] = window.location.origin;
    headers['X-Title'] = 'ScreenMind2';
  }

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`Ошибка API: ${res.status} ${await res.text()}`);

  const data = await res.json();
  const resultStr = isOllama ? data.response : data.choices[0].message.content;
  return isJson ? extractJSON(resultStr) : resultStr;
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `Проанализируй текст и верни ТОЛЬКО JSON объект: {"tags": ["тег1"], "category": "Категория", "summary": "Резюме"}. Текст: ${text}`;
  return await callAI(prompt, settings, true);
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Разбей этот текст на блоки. Верни ТОЛЬКО JSON массив: [{"title": "Заголовок", "content": "Текст", "category": "Категория", "tags": ["тег"]}]. Текст: ${text}`;
  return await callAI(prompt, settings, true);
};

export const chatWithNotes = async (query: string, context: string, settings: Settings): Promise<string> => {
  const prompt = `Используй КОНТЕКСТ для ответа на ВОПРОС.\n\nКОНТЕКСТ:\n${context}\n\nВОПРОС: ${query}`;
  return await callAI(prompt, settings, false) as string;
};

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
