        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={handleCopy}
            className="p-4 bg-gray-50 dark:bg-slate-800 rounded-2xl text-gray-500 hover:bg-gray-100 transition-all flex items-center gap-2 text-[10px] font-black uppercase tracking-widest"
          >
            {isCopied ? <Check size={18} className="text-green-500"/> : <Copy size={18}/>} {isCopied ? 'Ок' : 'Копировать'}
          </button>

          <button 
            onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')}
            className="flex items-center gap-3 px-6 py-4 bg-gray-100 dark:bg-slate-800 rounded-2xl text-gray-600 dark:text-slate-400 font-black uppercase text-[10px] tracking-widest hover:bg-gray-200 transition-all"
          >
            {viewMode === 'edit' ? <><Eye size={18}/> Просмотр</> : <><Edit3 size={18}/> Правка</>}
          </button>

          <button 
            onClick={() => handleSave(false)} 
            disabled={isSaving}
            className="flex items-center gap-3 px-10 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-blue-700 shadow-2xl shadow-blue-500/30 active:scale-95 transition-all"
          >
            <Save size={18}/> Сохранить
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 p-16 overflow-y-auto custom-scrollbar">
          {viewMode === 'edit' ? (
            <textarea 
              className="w-full h-full bg-transparent border-none focus:outline-none text-2xl leading-relaxed dark:text-slate-300 resize-none font-medium placeholder:text-gray-100 min-h-[600px]"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="О чем вы думаете сейчас?.."
            />
          ) : (
            <div 
              className="prose dark:prose-invert max-w-none text-2xl leading-relaxed dark:text-slate-200 font-medium whitespace-pre-wrap animate-in fade-in duration-300"
              dangerouslySetInnerHTML={{ __html: ai.linkify(content || 'Пустота...') }}
            />
          )}
        </div>

        {/* Интегрированный Чат */}
        <div className="w-[450px] border-l border-gray-100 dark:border-slate-900 flex flex-col bg-gray-50/20 dark:bg-slate-950/20 p-8 gap-8">
          <div className="flex-1 bg-white dark:bg-slate-900 rounded-[3rem] border border-gray-100 dark:border-slate-800 flex flex-col overflow-hidden shadow-2xl">
            <header className="p-6 border-b border-gray-50 dark:border-slate-800 flex items-center justify-between">
              <span className="text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-3">
                <Sparkles size={16}/> Контекстный Разум
              </span>
              <button onClick={() => setChatMessages([])} className="text-[9px] font-black text-gray-300 hover:text-red-500 uppercase transition-colors">Сброс</button>
            </header>

            <div ref={chatScrollRef} className="flex-1 p-8 overflow-y-auto space-y-6 text-sm font-medium scroll-smooth">
              {chatMessages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 text-gray-300 italic gap-6 opacity-30">
                  <MessageSquare size={48} />
                  Обсудите эту заметку с ИИ ассистентом
                </div>
              )}
              {chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-5 rounded-[1.8rem] ${
                    msg.role === 'user' ? 'bg-blue-600 text-white shadow-xl' : 'bg-gray-50 dark:bg-slate-800 text-gray-700 dark:text-slate-200 border border-gray-100 dark:border-slate-700 shadow-sm'
                  }`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isChatLoading && (
                <div className="flex justify-start">
                  <div className="bg-gray-50 dark:bg-slate-800 p-5 rounded-[1.8rem] flex gap-2">
                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" />
                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:0.2s]" />
                    <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:0.4s]" />
                  </div>
                </div>
              )}
            </div>

            <div className="p-6 border-t border-gray-50 dark:border-slate-800 bg-white dark:bg-slate-900 relative">
              <input 
                className="w-full pl-8 pr-16 py-5 bg-gray-50 dark:bg-slate-950 rounded-[1.8rem] text-sm font-bold border-none focus:ring-4 focus:ring-blue-500/10 transition-all"
                placeholder="Спросите об этой мысли..."
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChat()}
              />
              <button 
                onClick={handleChat}
                disabled={isChatLoading || !chatInput.trim()}
                className="absolute right-10 top-1/2 -translate-y-1/2 p-3 bg-blue-600 text-white rounded-2xl shadow-xl hover:scale-105 transition-all disabled:opacity-30"
              >
                <Send size={20}/>
              </button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-800 space-y-6 shadow-sm">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-3">
              <Hash size={14} className="text-blue-500"/> Мета-структура
            </h4>
            <div className="flex justify-between items-center pb-2 border-b border-gray-50 dark:border-slate-800">
              <span className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Категория</span>
              <span className="text-xs font-black dark:text-white uppercase tracking-wider text-blue-600">{note?.category || 'Новое'}</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {note?.tags.map((t: string) => (
                  <span key={t} className="px-4 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-xl text-[10px] font-black text-blue-600 dark:text-blue-400 uppercase tracking-tight">#{t}</span>
              ))}
              {!note?.tags.length && <span className="text-[10px] text-gray-300 italic">Теги не определены</span>}
            </div>
            <button 
              onClick={() => handleSave(true)}
              className="w-full py-4 bg-amber-50 text-amber-600 dark:bg-amber-900/10 dark:text-amber-500 rounded-2xl font-black uppercase text-[9px] tracking-[0.2em] hover:bg-amber-100 transition-all flex items-center justify-center gap-3"
            >
              <Sparkles size={14}/> Переанализировать через ИИ
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

