import { get, set } from 'https://cdn.jsdelivr.net/npm/idb-keyval@6/+esm';
import { Note, Settings, AIProvider } from '../types.ts';

const NOTES_KEY = 'screenmind_notes';
const SETTINGS_KEY = 'screenmind_settings';

export const saveNotes = async (notes: Note[]) => {
  await set(NOTES_KEY, notes);
};

export const getNotes = async (): Promise<Note[]> => {
  const notes = await get(NOTES_KEY);
  return notes || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  provider: AIProvider.Ollama,
  url: 'http://localhost:11434',
  model: 'mistral',
  apiKey: '',
  theme: 'light',
  ocrProvider: AIProvider.Gemini,
  ocrModel: 'gemini-2.5-flash-image',
  ocrApiKey: '',
  ocrUrl: '',
  transProvider: AIProvider.Ollama,
  transModel: 'whisper-large-v3',
  transApiKey: '',
  transUrl: 'http://localhost:11434',
  tgToken: '',
  tgChatId: '',
  tgLastUpdateId: 0
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return settings || getDefaultSettings();
};

export const exportData = async () => {
  const notes = await getNotes();
  const settings = await getSettings();
  const data = JSON.stringify({ notes, settings, version: '2.9', exportedAt: new Date().toISOString() }, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `screenmind_v2.9_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus } from '../types.ts';
import { 
  ChevronLeft, Trash2, Eye, Edit3, Sparkles, Globe, 
  CheckCircle2, PlayCircle, Search, Send, Loader2, ExternalLink, Hash, Save, Copy, Check, MessageSquare, X, Plus
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [newTag, setNewTag] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [isSaving, setIsSaving] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [note, setNote] = useState<any>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'ai', text: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
      }
    }
  }, [id, notes]);

  useEffect(() => {
    chatScrollRef.current?.scrollTo(0, chatScrollRef.current.scrollHeight);
  }, [chatMessages]);

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (id === 'new') {
      await addNote(content, title || 'Без названия', 'manual', useAI);
    } else if (note) {
      await updateNote({ ...note, title, content, tags });
      if (useAI) await runAIAnalysis(note.id);
    }
    setIsSaving(false);
    navigate('/');
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const addManualTag = (e?: React.KeyboardEvent) => {
    if (e && e.key !== 'Enter') return;
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()]);
      setNewTag('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter(t => t !== tagToRemove));
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const context = `Заметка: ${title}\nТекст: ${content}`;
      const response = await ai.chatWithNotes(userMsg, context, settings);
      setChatMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setChatMessages(prev => [...prev, { role: 'ai', text: 'Ошибка ИИ. Проверьте настройки.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] transition-colors overflow-hidden">
      <div className="flex items-center justify-between px-10 py-6 border-b border-gray-100 dark:border-slate-900 bg-white/80 dark:bg-slate-950/80 backdrop-blur-xl z-20">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all"><ChevronLeft size={24}/></button>
          <input 
            className="text-4xl font-black bg-transparent border-none focus:outline-none dark:text-white w-full max-w-4xl tracking-tight placeholder:text-gray-200" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок..."
          />
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => ai.openInGoogle(title || content.slice(0, 50))}
            className="p-4 bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400 rounded-2xl hover:bg-amber-100 transition-all flex items-center gap-3 text-[10px] font-black uppercase tracking-widest"
          >
            <ExternalLink size={18}/> Google Search
          </button>

          <button 
            onClick={handleCopy}
            className="p-4 bg-gray-50 dark:bg-slate-800 rounded-2xl text-gray-500 hover:bg-gray-100 transition-all flex items-center gap-2 text-[10px] font-black uppercase tracking-widest"
          >
