import React, { useState } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { ImageIcon, Loader2, ScanLine, Sparkles, Plus, FileText, CheckCircle2 } from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const OcrPage: React.FC = () => {
  const { addNote, settings, addLog } = useNotes();
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (!file || !file.type.startsWith('image/')) return;
    processFile(file);
  };

  const processFile = async (file: File) => {
    setIsLoading(true);
    addLog('info', `Запущен OCR для ${file.name}`);

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = reader.result as string;
        const text = await ai.performOCR(base64, file.type, settings);
        setResult(text);
        await addNote(text, `Скан: ${file.name}`, 'ocr', true);
        addLog('success', 'Текст успешно извлечен и сохранен');
        setIsLoading(false);
      };
      reader.readAsDataURL(file);
    } catch (err) {
