import { get, set } from 'https://cdn.jsdelivr.net/npm/idb-keyval@6/+esm';
import { Note, Settings, AIProvider, Goal } from '../types.ts';

const NOTES_KEY = 'screenmind_notes';
const SETTINGS_KEY = 'screenmind_settings';
const GOALS_KEY = 'screenmind_goals';

export const saveNotes = async (notes: Note[]) => {
  await set(NOTES_KEY, notes);
};

export const getNotes = async (): Promise<Note[]> => {
  const notes = await get(NOTES_KEY);
  return notes || [];
};

export const saveGoals = async (goals: Goal[]) => {
  await set(GOALS_KEY, goals);
};

export const getGoals = async (): Promise<Goal[]> => {
  const goals = await get(GOALS_KEY);
  return goals || [];
};

export const saveSettings = async (settings: Settings) => {
  await set(SETTINGS_KEY, settings);
};

export const getDefaultSettings = (): Settings => ({
  provider: AIProvider.Ollama,
  url: 'http://localhost:11434',
  model: 'mistral',
  apiKey: '',
  theme: 'light',
  ocrProvider: AIProvider.Gemini,
  ocrModel: 'gemini-2.5-flash-image',
  ocrApiKey: '',
  ocrUrl: '',
  transProvider: AIProvider.Ollama,
  transModel: 'whisper-large-v3',
  transApiKey: '',
  transUrl: 'http://localhost:11434',
  tgToken: '',
  tgChatId: '',
  tgLastUpdateId: 0
});

export const getSettings = async (): Promise<Settings> => {
  const settings = await get(SETTINGS_KEY);
  return settings || getDefaultSettings();
};

export const exportData = async () => {
  const notes = await getNotes();
  const settings = await getSettings();
  const goals = await getGoals();
  const data = JSON.stringify({ notes, settings, goals, version: '2.9.8', exportedAt: new Date().toISOString() }, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `screenmind_backup_${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    if (data.goals) await saveGoals(data.goals);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  telegramMessages: TelegramMessage[];
  setFilterTag: (tag: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  addGoal: (title: string, description: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<TelegramMessage[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
      addLog('success', 'ScreenMind Engine v2.9.8 Инициализирован');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true) => {
    let analysis = { tags: [], category: 'Новое', summary: '' };
    if (useAI) {
      addLog('info', 'ИИ анализирует контент...');
      try { analysis = await ai.analyzeText(content, settings); } catch (e) { addLog('warn', 'ИИ не доступен, сохраняю без анализа'); }
    }

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: title || content.slice(0, 40),
      content,
      tags: analysis.tags || [],
      category: analysis.category || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      sourceType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: 100 + Math.random() * 200, y: 100 + Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', `Создано: ${newNote.title}`);
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = {
      id: crypto.randomUUID(),
      title,
      description,
      createdAt: new Date().toISOString(),
      color: `hsl(${Math.random() * 360}, 70%, 50%)`
    };
    const updated = [newGoal, ...goals];
    setGoals(updated);
    await storage.saveGoals(updated);
    addLog('success', `Новая цель: ${title}`);
  };

  const deleteGoal = async (id: string) => {
    const updated = goals.filter(g => g.id !== id);
    setGoals(updated);
    await storage.saveGoals(updated);
  };

  const syncTelegram = async () => {
    if (!settings.tgToken) {
      addLog('warn', 'Telegram токен не настроен');
      return;
    }
    addLog('info', 'Синхронизация с Telegram...');
    try {
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${settings.tgLastUpdateId + 1}`);
      const data = await response.json();
      if (data.ok && data.result.length > 0) {
        const newMsgs: TelegramMessage[] = data.result
          .filter((u: any) => u.message && (u.message.text || u.message.caption))
          .map((u: any) => ({
            id: u.update_id,
            text: u.message.text || u.message.caption,
            from: u.message.from.first_name || 'Anonymous',
            date: new Date(u.message.date * 1000).toISOString(),
            type: 'text'
          }));

        setTelegramMessages(prev => [...newMsgs, ...prev]);
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
        addLog('success', `Получено ${newMsgs.length} сообщений из Telegram`);
      }
    } catch (e) {
      addLog('error', 'Ошибка связи с Telegram');
    }
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
    addLog('info', 'Настройки сохранены');
  };

  const moveToTrash = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const restoreNote = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'new' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const hardDelete = async (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNote = async (n: Note) => {
    const updated = notes.map(x => x.id === n.id ? n : x);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNotePosition = async (id: string, x: number, y: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNoteSize = async (id: string, w: number, h: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const runAIAnalysis = async (id: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return;
    try {
      const res = await ai.analyzeText(note.content, settings);
      const updated = notes.map(n => n.id === id ? { ...n, ...res, updatedAt: new Date().toISOString() } : n);
      setNotes(updated);
      await storage.saveNotes(updated);
    } catch (e) {}
  };

  const runSystemCheck = async () => {
    const res = await ai.testConnection(settings);
    if (res.success) addLog('success', res.message);
    else addLog('error', res.message);
  };

  const reanalyzeAll = async () => {
    addLog('info', 'Глобальная индексация...');
    const updated = [...notes];
    for (let i = 0; i < updated.length; i++) {
       try {
         const res = await ai.analyzeText(updated[i].content, settings);
         updated[i] = { ...updated[i], ...res };
       } catch {}
    }
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', 'База знаний синхронизирована');
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, telegramMessages,
      setFilterTag, addNote, processLargeText: async () => {}, updateNote, moveToTrash, restoreNote, hardDelete,
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck, updateNotePosition, updateNoteSize, syncTelegram, addGoal, deleteGoal
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { ImageIcon, Loader2, ScanLine, Sparkles, Plus, FileText, CheckCircle2, Files } from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const OcrPage: React.FC = () => {
  const { addNote, settings, addLog } = useNotes();
  const [isProcessing, setIsProcessing] = useState(false);
  const [queue, setQueue] = useState<number>(0);
  const [results, setResults] = useState<string[]>([]);

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    const files = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/'));
    if (files.length > 0) processFiles(files);
  };

  const processFiles = async (files: File[]) => {
    setIsProcessing(true);
    setQueue(files.length);
    addLog('info', `Начата пакетная обработка: ${files.length} изображений`);

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setQueue(files.length - i);
      try {
        const text = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onload = async () => {
            const base64 = reader.result as string;
            const res = await ai.performOCR(base64, file.type, settings);
            resolve(res);
          };
          reader.readAsDataURL(file);
        });

        await addNote(text, `Скан: ${file.name}`, 'ocr', true);
        setResults(prev => [text, ...prev]);
        addLog('success', `Обработано: ${file.name}`);
      } catch (err) {
        addLog('error', `Ошибка файла ${file.name}`);
      }
    }

    setIsProcessing(false);
    setQueue(0);
  };

  const onFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []).filter(f => f.type.startsWith('image/'));
    if (files.length > 0) processFiles(files);
  };

  return (
    <div className="p-12 max-w-5xl mx-auto min-h-screen animate-in fade-in duration-500">
      <header className="mb-16">
        <div className="flex items-center gap-3 text-blue-600 font-black text-[11px] uppercase tracking-[0.4em]">
          <ScanLine size={16} /> Vision Batch Engine
        </div>
        <h2 className="text-6xl font-black dark:text-white mt-2 tracking-tighter">Скан-центр</h2>
        <p className="text-gray-500 mt-4 text-lg">Перетащите сразу несколько скриншотов. ИИ создаст отдельные заметки для каждого.</p>
      </header>

      <div 
        onDragOver={(e) => e.preventDefault()}
        onDrop={handleDrop}
        className={`relative h-[300px] border-4 border-dashed rounded-[3rem] flex flex-col items-center justify-center transition-all group ${
          isProcessing 
          ? 'bg-blue-50 border-blue-400 dark:bg-blue-950/20' 
          : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800 hover:border-blue-400 hover:bg-blue-50/30'
        }`}
      >
        <input 
          type="file" 
          multiple
          className="absolute inset-0 opacity-0 cursor-pointer" 
          accept="image/*"
          onChange={onFileInput}
        />

        {isProcessing ? (
          <div className="flex flex-col items-center gap-6">
            <Loader2 className="animate-spin text-blue-600" size={64} />
            <p className="text-xl font-black text-blue-600 uppercase tracking-widest animate-pulse">
              Осталось: {queue} {queue === 1 ? 'файл' : 'файла'}
            </p>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-6 text-center px-8">
            <div className="p-8 bg-blue-50 dark:bg-blue-900/20 rounded-[2rem] text-blue-600 group-hover:scale-110 transition-transform">
              <Files size={64} />
            </div>
            <div>
              <p className="text-2xl font-black dark:text-white uppercase tracking-tighter">Бросьте пачку фото</p>
              <p className="text-gray-400 font-medium mt-2">Мульти-загрузка поддерживается</p>
            </div>
          </div>
        )}
      </div>

      <div className="mt-12 space-y-4">
        {results.map((res, i) => (
          <div key={i} className="p-6 bg-white dark:bg-slate-900 border border-gray-100 dark:border-slate-800 rounded-3xl animate-in slide-in-from-bottom flex gap-4">
             <div className="w-10 h-10 bg-green-50 rounded-xl flex items-center justify-center text-green-600 shrink-0"><CheckCircle2 size={20}/></div>
             <p className="text-sm font-medium line-clamp-2 text-gray-600 dark:text-slate-300 italic">"{res.slice(0, 150)}..."</p>
          </div>
        ))}
      </div>
    </div>
  );
};

