export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.notes) await saveNotes(data.notes);
    if (data.settings) await saveSettings(data.settings);
    if (data.goals) await saveGoals(data.goals);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  try {
    return JSON.parse(str);
  } catch (e) {
    const match = str.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (inner) { throw new Error("Invalid JSON structure"); }
    }
    const arrMatch = str.match(/\[[\s\S]*\]/);
    if (arrMatch) {
      try { return JSON.parse(arrMatch[0]); } catch (inner) { throw new Error("Invalid JSON Array structure"); }
    }
    throw new Error("No JSON found in AI response");
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part, i) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline hover:text-blue-600 transition-colors">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  const url = `https://www.google.com/search?q=${encodeURIComponent(query)}`;
  window.open(url, '_blank');
};

/**
 * Универсальный вызов ИИ с передачей конкретных параметров провайдера
 */
async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string
) {
  if (provider === AIProvider.Gemini) {
    const key = apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: model || 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: isJson ? "application/json" : undefined
      }
    });
    return isJson ? extractJSON(response.text || '{}') : response.text;
  }

  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;

  let url = baseUrl.replace(/\/$/, '');
  if (isOllama) url += '/api/generate';
  else if (isOR) url = 'https://openrouter.ai/api/v1/chat/completions';
  else url += '/v1/chat/completions';

  const body: any = isOllama 
    ? { model: model, prompt: systemInstruction ? `${systemInstruction}\n\n${prompt}` : prompt, stream: false, format: isJson ? 'json' : undefined }
    : { 
        model: model, 
        messages: [
          ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
          { role: 'user', content: prompt }
        ],
        response_format: isJson ? { type: 'json_object' } : undefined 
      };

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`Ошибка API: ${res.status}`);

  const data = await res.json();
  const resultStr = isOllama ? data.response : data.choices[0].message.content;
  return isJson ? extractJSON(resultStr) : resultStr;
}

export const testConnection = async (settings: Settings): Promise<{success: boolean, message: string}> => {
  try {
    const res = await callAI("ping", settings.provider, settings.model, settings.apiKey, settings.url, false);
    return { success: true, message: "Связь с основным ИИ установлена" };
  } catch (e: any) {
    return { success: false, message: e.message || "Ошибка сети" };
  }
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings): Promise<string> => {
  const prompt = "Извлеки весь текст из этого изображения. Верни только текст без комментариев.";

  if (settings.ocrProvider === AIProvider.Gemini) {
    const key = settings.ocrApiKey || settings.apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: settings.ocrModel || 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data.split(',')[1] || base64Data, mimeType } },
          { text: prompt }
        ]
      }
    });
    return response.text || "Текст не обнаружен";
  }

  if (settings.ocrProvider === AIProvider.Ollama) {
    const url = settings.ocrUrl || settings.url;
    const res = await fetch(`${url.replace(/\/$/, '')}/api/generate`, {
      method: 'POST',
      body: JSON.stringify({
        model: settings.ocrModel,
        prompt: prompt,
        images: [base64Data.split(',')[1] || base64Data],
        stream: false
      })
    });
    const data = await res.json();
    return data.response;
  }

  throw new Error("Провайдер OCR не поддерживает изображения в данной версии");
};

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `Проанализируй текст и верни ТОЛЬКО JSON объект: {"tags": ["тег1"], "category": "Категория", "summary": "Резюме"}. Текст: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true);
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Разбей этот текст на смысловые блоки. Верни ТОЛЬКО JSON массив: [{"title": "Заголовок", "content": "Текст", "category": "Категория", "tags": ["тег"]}]. Текст: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true);
};

export const chatWithNotes = async (query: string, context: string, settings: Settings): Promise<string> => {
  const prompt = `Используй КОНТЕКСТ для ответа.\n\nКОНТЕКСТ:\n${context}\n\nВОПРОС: ${query}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, false) as string;
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings): Promise<string> => {
  const systemPrompt = `Ты — ScreenMind Agent, технический ассистент приложения.
Используй свою конфигурацию ИИ. 

ТВОИ ЗНАНИЯ:
1. База знаний: ${appData.notesCount} заметок.
2. Цели: ${appData.goalsCount} активных целей.
3. Логи системы: предоставлены ниже.

ТВОЯ ЗАДАЧА: помогать с настройками провайдеров (Ollama, Gemini, OpenRouter), объяснять структуру данных (IndexedDB) и анализировать ошибки в логах.

ЛОГИ ПРИЛОЖЕНИЯ:
${JSON.stringify(appData.logs.slice(0, 10), null, 2)}`;

  // Используем выделенные настройки агента
  return await callAI(
    query, 
    settings.agentProvider, 
    settings.agentModel, 
    settings.agentApiKey, 
    settings.agentUrl || settings.url, 
    false, 
    systemPrompt
  ) as string;
};

