import React, { useState, useRef, useEffect } from 'react';
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles, AlertCircle } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext.tsx';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));

      mediaRecorder.start();
      setIsRecording(true);
      addLog('info', 'Микрофон активирован, запись начата');
      visualize(stream);
    } catch (err: any) {
      setError("Микрофон не доступен: " + err.message);
      addLog('error', 'Ошибка доступа к микрофону', err.message);
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    if (audioContextRef.current) audioContextRef.current.close();
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    audioContextRef.current = audioCtx;
    const source = audioCtx.createMediaStreamSource(stream);
    const analyser = audioCtx.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const barWidth = (canvas.width / bufferLength) * 2;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height;

        // Создаем градиент для баров
        const gradient = ctx.createLinearGradient(0, canvas.height, 0, 0);
        gradient.addColorStop(0, '#3b82f6');
        gradient.addColorStop(1, '#60a5fa');

        ctx.fillStyle = gradient;
        // Отрисовка симметрично от центра
        ctx.fillRect(x, canvas.height / 2 - barHeight / 2, barWidth - 1, barHeight);
        x += barWidth;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    setIsProcessing(true);
    addLog('info', 'Запущена транскрибация аудио...');
    // Эмуляция вызова (в реальном приложении здесь вызов settings.transUrl)
    setTimeout(() => {
        setTranscript("Это распознанный текст вашей мысли. Голос успешно переведен в текст и готов стать частью базы знаний.");
        setIsProcessing(false);
        addLog('success', 'Аудио успешно транскрибировано');
    }, 2000);
  };

  const handleSave = async () => {
    if (!transcript) return;
    await addNote(transcript, `Голос: ${new Date().toLocaleTimeString()}`, 'audio');
    setTranscript('');
    setAudioBlob(null);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-700 shadow-2xl space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-black dark:text-white uppercase tracking-widest flex items-center gap-2">
            <Volume2 className="text-blue-500" /> Голосовая Заметка
        </h3>
        {audioBlob && <button onClick={() => setAudioBlob(null)} className="text-gray-400 hover:text-red-500"><RotateCcw size={18}/></button>}
      </div>

      <div className="h-32 bg-gray-50 dark:bg-slate-950 rounded-2xl flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-slate-800">
        {isRecording ? (
          <canvas ref={canvasRef} width={400} height={120} className="w-full h-full" />
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-2">
            <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse" />
            <p className="text-blue-500 font-bold text-[10px] uppercase tracking-widest">Аудио захвачено</p>
          </div>
        ) : error ? (
           <div className="flex flex-col items-center gap-2 text-red-500 text-center px-4">
             <AlertCircle size={24}/>
             <p className="text-[10px] font-bold uppercase">{error}</p>
           </div>
        ) : (
          <p className="text-gray-300 dark:text-slate-700 font-bold text-[10px] uppercase tracking-[0.2em]">Готов к записи...</p>
        )}
      </div>

      <div className="flex justify-center gap-4">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="p-6 bg-blue-600 text-white rounded-full shadow-xl shadow-blue-500/20 hover:scale-110 active:scale-95 transition-transform">
            <Mic size={32} />
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="p-6 bg-red-500 text-white rounded-full shadow-xl shadow-red-500/20 hover:scale-110 active:scale-95 transition-transform">
            <Square size={32} />
          </button>
        )}
        {audioBlob && !transcript && (
          <button onClick={handleTranscribe} disabled={isProcessing} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2">
            {isProcessing ? <Loader2 className="animate-spin" /> : <Sparkles size={18}/>}
            Транскрибировать (Whisper)
          </button>
        )}
      </div>

      {transcript && (
        <div className="space-y-4 animate-slide-up">
            <textarea 
                value={transcript}
                onChange={e => setTranscript(e.target.value)}
                className="w-full h-32 bg-gray-50 dark:bg-slate-900 border-none rounded-2xl p-4 text-sm font-medium focus:ring-2 focus:ring-blue-500/20"
            />
            <button onClick={handleSave} className="w-full bg-green-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-green-500/20">
                <Save size={18}/> Сохранить в Базу
            </button>
        </div>
      )}
    </div>
  );
};

