import React, { useState, useRef, useEffect } from 'react';
import { Mic, Square, Loader2, Save, X, RotateCcw, Volume2, Sparkles, AlertCircle } from 'lucide-react';
import { useNotes } from '../contexts/NotesContext.tsx';

const AudioRecorder: React.FC<{ onComplete?: () => void }> = ({ onComplete }) => {
  const { addNote, addLog } = useNotes();
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [transcript, setTranscript] = useState('');
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const startRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => setAudioBlob(new Blob(chunks, { type: 'audio/webm' }));

      mediaRecorder.start();
      setIsRecording(true);
      addLog('info', 'Голосовой интерфейс активирован');
      visualize(stream);
    } catch (err: any) {
      setError("Микрофон не доступен: " + err.message);
      addLog('error', 'Ошибка доступа к микрофону', err.message);
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    streamRef.current?.getTracks().forEach(t => t.stop());
    setIsRecording(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    if (audioContextRef.current) audioContextRef.current.close();
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    audioContextRef.current = audioCtx;
    const source = audioCtx.createMediaStreamSource(stream);
    const analyser = audioCtx.createAnalyser();
    analyser.fftSize = 128; // Более крупные бары
    source.connect(analyser);

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);
      analyser.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const barWidth = (canvas.width / bufferLength) * 1.5;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height * 0.8;

        // Футуристичные неоновые бары
        const gradient = ctx.createLinearGradient(0, canvas.height, 0, 0);
        gradient.addColorStop(0, '#3b82f6');
        gradient.addColorStop(0.5, '#60a5fa');
        gradient.addColorStop(1, '#06b6d4');

        ctx.fillStyle = gradient;
        ctx.shadowBlur = 10;
        ctx.shadowColor = 'rgba(59, 130, 246, 0.5)';

        // Отрисовка закругленных баров
        const y = (canvas.height - barHeight) / 2;
        ctx.beginPath();
        ctx.roundRect(x, y, barWidth - 4, barHeight, 10);
        ctx.fill();

        x += barWidth + 2;
      }
    };
    draw();
  };

  const handleTranscribe = async () => {
    setIsProcessing(true);
    addLog('info', 'Декодирование голосовой волны...');
    // Эмуляция вызова (в будущем здесь будет Whisper API)
    setTimeout(() => {
        setTranscript("Анализ завершен. Голосовой поток переведен в текстовую форму и классифицирован нейросетью.");
        setIsProcessing(false);
        addLog('success', 'Транскрибация завершена успешно');
    }, 1500);
  };

  const handleSave = async () => {
    if (!transcript) return;
    // Сохраняем не только текст, но и помечаем как аудио-заметку
    await addNote(transcript, `Vocal: ${new Date().toLocaleTimeString('ru-RU')}`, 'audio');
    setTranscript('');
    setAudioBlob(null);
    onComplete?.();
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-8 backdrop-blur-xl relative overflow-hidden">
      <div className="absolute -top-10 -left-10 w-40 h-40 bg-blue-500/10 blur-3xl -z-10"></div>

      <div className="flex items-center justify-between">
        <h3 className="text-xl font-black dark:text-white uppercase tracking-[0.2em] flex items-center gap-3">
            <div className="p-2 bg-blue-500/10 rounded-xl text-blue-500"><Volume2 size={20} /></div>
            Vocal Interface
        </h3>
        {audioBlob && !isProcessing && (
          <button onClick={() => { setAudioBlob(null); setTranscript(''); }} className="p-2 text-gray-400 hover:text-red-500 transition-colors">
            <RotateCcw size={20}/>
          </button>
        )}
      </div>

      <div className="h-48 bg-gray-50 dark:bg-slate-950 rounded-[2.5rem] flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-100 dark:border-white/5 relative group shadow-inner">
        {isRecording ? (
          <canvas ref={canvasRef} width={600} height={180} className="w-full h-full p-6" />
        ) : audioBlob ? (
          <div className="flex flex-col items-center gap-4">
            <div className="w-5 h-5 bg-green-500 rounded-full animate-ping" />
            <p className="text-green-500 font-black text-[10px] uppercase tracking-widest shadow-green-500/20 shadow-lg">Audio Captured</p>
          </div>
        ) : error ? (
           <div className="flex flex-col items-center gap-3 text-red-500 text-center px-8 animate-in zoom-in">
             <AlertCircle size={32}/>
             <p className="text-[10px] font-black uppercase tracking-widest leading-relaxed">{error}</p>
           </div>
        ) : (
          <div className="flex flex-col items-center gap-4 opacity-30 group-hover:opacity-50 transition-opacity">
            <Mic size={48} className="text-gray-400" />
            <p className="text-gray-400 font-black text-[10px] uppercase tracking-[0.3em]">Ready for input...</p>
          </div>
        )}
      </div>

      <div className="flex justify-center gap-6">
        {!isRecording && !audioBlob && (
          <button onClick={startRecording} className="p-10 bg-blue-600 dark:bg-cyan-600 text-white rounded-full shadow-2xl shadow-blue-500/30 hover:scale-110 active:scale-95 transition-all group">
            <Mic size={40} className="group-hover:rotate-12 transition-transform" />
          </button>
        )}
        {isRecording && (
          <button onClick={stopRecording} className="p-10 bg-red-500 text-white rounded-full shadow-2xl shadow-red-500/30 hover:scale-110 active:scale-95 transition-all animate-pulse">
            <Square size={40} />
          </button>
        )}
        {audioBlob && !transcript && (
          <button 
            onClick={handleTranscribe} 
            disabled={isProcessing} 
            className="w-full bg-blue-600 dark:bg-cyan-600 text-white py-6 rounded-[2rem] font-black uppercase text-xs tracking-widest flex items-center justify-center gap-4 shadow-2xl shadow-blue-500/20 active:scale-[0.98] transition-all"
          >
            {isProcessing ? <Loader2 className="animate-spin" /> : <Sparkles size={20}/>}
            {isProcessing ? 'Analysing Frequencies...' : 'Decode Signal'}
          </button>
        )}
      </div>

      {transcript && (
        <div className="space-y-6 animate-in slide-in-from-bottom duration-500">
            <div className="relative">
              <textarea 
                  value={transcript}
                  onChange={e => setTranscript(e.target.value)}
                  className="w-full h-40 bg-gray-50 dark:bg-slate-950 border-none rounded-[2rem] p-6 text-sm font-medium focus:ring-4 focus:ring-blue-500/10 shadow-inner resize-none dark:text-slate-300"
              />
              <div className="absolute top-4 right-4 text-[9px] font-black text-blue-500 uppercase">Transcript</div>
            </div>
            <button 
              onClick={handleSave} 
              className="w-full bg-green-600 text-white py-6 rounded-[2rem] font-black uppercase text-xs tracking-widest flex items-center justify-center gap-4 shadow-2xl shadow-green-500/20 hover:bg-green-700 transition-all active:scale-95"
            >
                <Save size={20}/> Integrate into Knowledge Base
            </button>
        </div>
      )}
    </div>
  );
};

export default AudioRecorder;

