export const getTagColor = (tag: string) => {
  let hash = 0;
  for (let i = 0; i < tag.length; i++) {
    hash = tag.charCodeAt(i) + ((hash << 5) - hash);
  }

  const h = Math.abs(hash % 360);
  // Futurist palette: slightly lower saturation, vibrant but transparent
  return {
    bg: `hsla(${h}, 60%, 50%, 0.08)`,
    text: `hsla(${h}, 70%, 55%, 1)`,
    border: `hsla(${h}, 60%, 50%, 0.15)`
  };
};

