const StatusIcon = ({ status, className }: { status: NoteStatus, className?: string }) => {
  switch (status) {
    case 'new': return <Circle className={`${className} text-amber-500 fill-amber-500 shadow-[0_0_12px_rgba(245,158,11,0.6)]`} size={10} />;
    case 'in-work': return <PlayCircle className={`${className} text-blue-500 shadow-[0_0_12px_rgba(59,130,246,0.6)]`} size={16} />;
    case 'read': return <Eye className={`${className} text-slate-400`} size={16} />;
    case 'finished': return <CheckCircle2 className={`${className} text-green-500 shadow-[0_0_12px_rgba(34,197,94,0.6)]`} size={16} />;
    default: return null;
  }
};

const SourceIcon = ({ type }: { type?: Note['sourceType'] }) => {
  const className = "text-gray-400 dark:text-slate-500 group-hover:text-cyan-400 transition-colors duration-500";
  const size = 16;
  switch (type) {
    case 'ocr': return <ScanLine size={size} className={className} />;
    case 'telegram': return <Send size={size} className={className} />;
    case 'audio': return <Mic size={size} className={className} />;
    case 'split': return <Split size={size} className={className} />;
    default: return <Edit3 size={size} className={className} />;
  }
};

