export const testConnection = async (settings: Settings): Promise<{success: boolean, message: string}> => {
  try {
    const res = await callAI("ping", settings.provider, settings.model, settings.apiKey, settings.url, false);
    return { success: true, message: "Связь установлена" };
  } catch (e: any) {
    return { success: false, message: e.message || "Ошибка сети" };
  }
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings): Promise<string> => {
  const prompt = "Извлеки весь текст из этого изображения. Верни только текст без комментариев.";
  if (settings.ocrProvider === AIProvider.Gemini) {
    const key = settings.ocrApiKey || settings.apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: settings.ocrModel || 'gemini-3-flash-preview',
      contents: { parts: [{ inlineData: { data: base64Data.split(',')[1] || base64Data, mimeType } }, { text: prompt }] }
    });
    return response.text || "Текст не обнаружен";
  }
  return "OCR не поддерживается данным провайдером";
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings): Promise<string> => {
  const systemPrompt = `Ты — ScreenMind Agent. У тебя есть доступ к логам и статистике приложения. Помогай пользователю.`;
  return await callAI(query, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl || settings.url, false, systemPrompt) as string;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Note, Settings, AIProvider, AppLog, NoteStatus, TelegramMessage, Goal } from '../types.ts';
import * as storage from '../utils/storage.ts';
import * as ai from '../utils/aiAdapter.ts';

interface NotesContextType {
  notes: Note[];
  goals: Goal[];
  settings: Settings;
  isLoading: boolean;
  logs: AppLog[];
  filterTag: string | null;
  telegramMessages: TelegramMessage[];
  setFilterTag: (tag: string | null) => void;
  addNote: (content: string, title?: string, sourceType?: Note['sourceType'], useAI?: boolean) => Promise<void>;
  processLargeText: (text: string) => Promise<void>;
  updateNote: (note: Note) => Promise<void>;
  moveToTrash: (id: string) => Promise<void>;
  restoreNote: (id: string) => Promise<void>;
  hardDelete: (id: string) => Promise<void>;
  setNoteStatus: (id: string, status: NoteStatus) => Promise<void>;
  updateSettings: (s: Settings) => Promise<void>;
  addLog: (level: AppLog['level'], message: string, details?: string) => void;
  runAIAnalysis: (id: string) => Promise<void>;
  reanalyzeAll: () => Promise<void>;
  runSystemCheck: () => Promise<void>;
  updateNotePosition: (id: string, x: number, y: number) => Promise<void>;
  updateNoteSize: (id: string, w: number, h: number) => Promise<void>;
  syncTelegram: () => Promise<void>;
  addGoal: (title: string, description: string) => Promise<void>;
  deleteGoal: (id: string) => Promise<void>;
}

const NotesContext = createContext<NotesContextType | undefined>(undefined);

export const NotesProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [goals, setGoals] = useState<Goal[]>([]);
  const [settings, setSettings] = useState<Settings>(storage.getDefaultSettings());
  const [isLoading, setIsLoading] = useState(true);
  const [logs, setLogs] = useState<AppLog[]>([]);
  const [filterTag, setFilterTag] = useState<string | null>(null);
  const [telegramMessages, setTelegramMessages] = useState<TelegramMessage[]>([]);

  const addLog = (level: AppLog['level'], message: string, details?: string) => {
    setLogs(prev => [{ id: crypto.randomUUID(), timestamp: new Date().toISOString(), level, message, details }, ...prev].slice(0, 50));
  };

  useEffect(() => {
    const init = async () => {
      const [n, s, g] = await Promise.all([storage.getNotes(), storage.getSettings(), storage.getGoals()]);
      setNotes(n);
      setSettings(s);
      setGoals(g);
      setIsLoading(false);
      document.documentElement.classList.toggle('dark', s.theme === 'dark');
      addLog('success', 'ScreenMind Engine v3.1.0 Инициализирован');
    };
    init();
  }, []);

  const addNote = async (content: string, title?: string, sourceType: Note['sourceType'] = 'manual', useAI = true) => {
    let analysis = { tags: [], category: 'Новое', summary: '', title: title };
    if (useAI) {
      addLog('info', 'ИИ анализирует контент...');
      try { 
        analysis = await ai.analyzeText(content, settings); 
      } catch (e) { 
        addLog('warn', 'ИИ не доступен, сохраняю без анализа'); 
      }
    }

    const finalTitle = title || analysis.title || content.slice(0, 40);

    const newNote: Note = {
      id: crypto.randomUUID(),
      title: finalTitle,
      content,
      tags: analysis.tags || [],
      category: analysis.category || 'Общее',
      summary: analysis.summary || '',
      status: 'new',
      sourceType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      links: [],
      position: { x: 100 + Math.random() * 200, y: 100 + Math.random() * 200 },
      size: { w: 320, h: 280 }
    };
    const updated = [newNote, ...notes];
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', `Создано: ${newNote.title}`);
  };

  const processLargeText = async (text: string) => {
    addLog('info', 'ИИ анализирует и разделяет текст...');
    try {
      const blocks = await ai.splitLargeText(text, settings);
      if (Array.isArray(blocks)) {
        const newNotes: Note[] = blocks.map(block => ({
          id: crypto.randomUUID(),
          title: block.title || block.content.slice(0, 40),
          content: block.content,
          tags: block.tags || [],
          category: block.category || 'Импорт',
          summary: '',
          status: 'new',
          sourceType: 'split',
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          links: [],
          position: { x: 100 + Math.random() * 200, y: 100 + Math.random() * 200 },
          size: { w: 320, h: 280 }
        }));
        const updated = [...newNotes, ...notes];
        setNotes(updated);
        await storage.saveNotes(updated);
        addLog('success', `Импортировано ${newNotes.length} блоков`);
      }
    } catch (e) {
      addLog('error', 'Ошибка при обработке текста');
    }
  };

  const addGoal = async (title: string, description: string) => {
    const newGoal: Goal = {
      id: crypto.randomUUID(),
      title,
      description,
      createdAt: new Date().toISOString(),
      color: `hsl(${Math.random() * 360}, 70%, 50%)`
    };
    const updated = [newGoal, ...goals];
    setGoals(updated);
    await storage.saveGoals(updated);
    addLog('success', `Новая цель: ${title}`);
  };

  const deleteGoal = async (id: string) => {
    const updated = goals.filter(g => g.id !== id);
    setGoals(updated);
    await storage.saveGoals(updated);
  };

  const syncTelegram = async () => {
    if (!settings.tgToken) return;
    try {
      const response = await fetch(`https://api.telegram.org/bot${settings.tgToken}/getUpdates?offset=${settings.tgLastUpdateId + 1}`);
      const data = await response.json();
      if (data.ok && data.result.length > 0) {
        const newMsgs: TelegramMessage[] = data.result
          .filter((u: any) => u.message && (u.message.text || u.message.caption))
          .map((u: any) => ({
            id: u.update_id,
            text: u.message.text || u.message.caption,
            from: u.message.from.first_name || 'Anonymous',
            date: new Date(u.message.date * 1000).toISOString(),
            type: 'text'
          }));
        setTelegramMessages(prev => [...newMsgs, ...prev]);
        const lastId = data.result[data.result.length - 1].update_id;
        const newSettings = { ...settings, tgLastUpdateId: lastId };
        setSettings(newSettings);
        await storage.saveSettings(newSettings);
      }
    } catch (e) {}
  };

  const updateSettings = async (s: Settings) => {
    setSettings(s);
    await storage.saveSettings(s);
    document.documentElement.classList.toggle('dark', s.theme === 'dark');
  };

  const moveToTrash = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'trash' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const restoreNote = async (id: string) => {
    const updated = notes.map(n => n.id === id ? { ...n, status: 'new' as NoteStatus } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const hardDelete = async (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNote = async (n: Note) => {
    const updated = notes.map(x => x.id === n.id ? n : x);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const setNoteStatus = async (id: string, status: NoteStatus) => {
    const updated = notes.map(n => n.id === id ? { ...n, status } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNotePosition = async (id: string, x: number, y: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, position: { x, y } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const updateNoteSize = async (id: string, w: number, h: number) => {
    const updated = notes.map(n => n.id === id ? { ...n, size: { w, h } } : n);
    setNotes(updated);
    await storage.saveNotes(updated);
  };

  const runAIAnalysis = async (id: string) => {
    const note = notes.find(n => n.id === id);
    if (!note) return;
    try {
      const res = await ai.analyzeText(note.content, settings);
      const updated = notes.map(n => n.id === id ? { ...n, ...res, updatedAt: new Date().toISOString() } : n);
      setNotes(updated);
      await storage.saveNotes(updated);
    } catch (e) {}
  };

  const runSystemCheck = async () => {
    const res = await ai.testConnection(settings);
    if (res.success) addLog('success', res.message);
    else addLog('error', res.message);
  };

  const reanalyzeAll = async () => {
    addLog('info', 'Глобальная индексация...');
    const updated = [...notes];
    for (let i = 0; i < updated.length; i++) {
       try {
         const res = await ai.analyzeText(updated[i].content, settings);
         updated[i] = { ...updated[i], ...res };
       } catch {}
    }
    setNotes(updated);
    await storage.saveNotes(updated);
    addLog('success', 'База знаний синхронизирована');
  };

  return (
    <NotesContext.Provider value={{ 
      notes, goals, settings, isLoading, logs, filterTag, telegramMessages,
      setFilterTag, addNote, processLargeText, updateNote, moveToTrash, restoreNote, hardDelete,
      setNoteStatus, updateSettings, addLog, runAIAnalysis, reanalyzeAll,
      runSystemCheck, updateNotePosition, updateNoteSize, syncTelegram, addGoal, deleteGoal
    }}>
      {children}
    </NotesContext.Provider>
  );
};

export const useNotes = () => {
  const c = useContext(NotesContext);
  if (!c) throw new Error("useNotes error");
  return c;
};

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus } from '../types.ts';
import { 
  ChevronLeft, Trash2, Eye, Edit3, Sparkles, Globe, 
  CheckCircle2, PlayCircle, Search, Send, Loader2, ExternalLink, Hash, Save, Copy, Check, MessageSquare, X, Plus, Info, Layout
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [newTag, setNewTag] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [isSaving, setIsSaving] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [note, setNote] = useState<any>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'ai', text: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
      }
    }
  }, [id, notes]);

  useEffect(() => {
    chatScrollRef.current?.scrollTo(0, chatScrollRef.current.scrollHeight);
  }, [chatMessages]);

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (id === 'new') {
      // If title is missing, it will be generated by AI in the context
      await addNote(content, title, 'manual', useAI);
    } else if (note) {
      await updateNote({ ...note, title, content, tags });
      if (useAI) await runAIAnalysis(note.id);
    }
    setIsSaving(false);
    navigate('/');
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const addManualTag = (e?: React.KeyboardEvent) => {
    if (e && e.key !== 'Enter') return;
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()]);
      setNewTag('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter(t => t !== tagToRemove));
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const context = `Заметка: ${title}\nТекст: ${content}`;
      const response = await ai.chatWithNotes(userMsg, context, settings);
      setChatMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setChatMessages(prev => [...prev, { role: 'ai', text: 'Ошибка ИИ.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] transition-colors overflow-hidden">
      <div className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20">
        <div className="flex items-center gap-8 flex-1">
          <button onClick={() => navigate(-1)} className="p-5 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-[1.5rem] transition-all"><ChevronLeft size={28}/></button>
          <input 
            className="text-5xl font-black bg-transparent border-none focus:outline-none text-black dark:text-white w-full max-w-5xl tracking-tighter placeholder:text-gray-200" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок сгенерируется ИИ..."
          />
        </div>
        <div className="flex items-center gap-6">
          <button 
