import { getTagColor } from './utils/tagColors.ts';

const QuickIdeasPanel: React.FC = () => {
  const { addNote, notes, setFilterTag } = useNotes();
  const navigate = useNavigate();
  const [idea, setIdea] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRecorder, setShowRecorder] = useState(false);

  const activeNotes = notes.filter(n => n.status !== 'trash');

  const activeTags = useMemo(() => {
    const counts: Record<string, number> = {};
    activeNotes.forEach(n => n.tags.forEach(t => counts[t] = (counts[t] || 0) + 1));
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 10);
  }, [activeNotes]);

  const stats = useMemo(() => ({
    total: activeNotes.length,
    new: activeNotes.filter(n => n.status === 'new').length,
    finished: activeNotes.filter(n => n.status === 'finished').length,
  }), [activeNotes]);

  const handleSaveIdea = async () => {
    if (!idea.trim()) return;
    setIsSaving(true);
    // Auto title generation handled by addNote context
    await addNote(idea, undefined, 'manual', true);
    setIdea('');
    setIsSaving(false);
  };

  const handleTagAction = (tag: string) => {
    setFilterTag(tag);
    navigate('/');
  };

  return (
    <div className="w-80 bg-white dark:bg-[#080c14] border-l border-gray-100 dark:border-slate-800 h-screen flex flex-col hidden xl:flex transition-colors shrink-0 z-10">
      <div className="p-8 border-b border-gray-50 dark:border-slate-800">
        <div className="flex items-center justify-between mb-6">
          <h3 className="font-black text-[10px] uppercase tracking-[0.3em] text-gray-400 flex items-center gap-3">
            <Zap size={14} className="text-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.4)]" /> Быстрый Ввод
          </h3>
          <button 
            onClick={() => setShowRecorder(true)} 
            className="p-3 text-blue-600 bg-blue-50 dark:bg-blue-500/10 dark:text-cyan-400 hover:scale-110 rounded-2xl transition-all shadow-sm"
          >
            <Mic size={18} />
          </button>
        </div>
        <div className="relative group">
          <textarea 
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="Запишите квантовую мысль..."
            className="w-full h-32 p-5 bg-gray-50 dark:bg-slate-800/50 border-none rounded-[2rem] focus:ring-4 focus:ring-blue-500/10 text-sm font-bold text-gray-700 dark:text-slate-200 placeholder:text-gray-300 dark:placeholder:text-slate-600 resize-none transition-all shadow-inner"
          />
          <button 
            onClick={handleSaveIdea}
            disabled={isSaving || !idea.trim()}
            className="absolute bottom-4 right-4 p-3 bg-blue-600 dark:bg-cyan-600 text-white rounded-2xl shadow-xl shadow-blue-500/30 hover:bg-blue-700 active:scale-90 transition-all disabled:opacity-30"
          >
            {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scrollbar">
        <section>
          <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
            <Hash size={12} className="text-cyan-500" /> Популярные узлы
          </h4>
          <div className="flex flex-wrap gap-2.5">
            {activeTags.map(([tag, count]) => {
              const colors = getTagColor(tag);
              return (
                <button 
                  key={tag} 
                  onClick={() => handleTagAction(tag)}
                  style={{ color: colors.text, backgroundColor: colors.bg, borderColor: colors.border }} 
                  className="px-4 py-2 rounded-xl transition-all flex items-center gap-2.5 border-2 hover:scale-110 active:scale-95 shadow-sm group"
                >
                  <span className="text-[10px] font-black italic group-hover:rotate-6 transition-transform">#{tag}</span>
                  <span className="text-[8px] font-black bg-white/50 px-2 py-0.5 rounded-md opacity-60">{count}</span>
                </button>
              );
            })}
          </div>
        </section>

        {/* AI Insight section REMOVED per user request */}
      </div>

      <div className="p-8 bg-gray-50/50 dark:bg-[#06080c] border-t border-gray-100 dark:border-slate-800">
        <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
          <BarChart3 size={14} className="text-cyan-500" /> Neural Stats
        </h4>
        <div className="grid grid-cols-2 gap-4">
          <div className="p-5 bg-white dark:bg-slate-900 rounded-[1.8rem] border border-gray-100 dark:border-white/5 shadow-sm hover:shadow-md transition-shadow">
            <span className="block text-[9px] font-black text-blue-500 uppercase tracking-widest mb-1">Архив</span>
            <span className="text-2xl font-black dark:text-white font-mono">{stats.total}</span>
          </div>
          <div className="p-5 bg-white dark:bg-slate-900 rounded-[1.8rem] border border-gray-100 dark:border-white/5 shadow-sm hover:shadow-md transition-shadow">
            <span className="block text-[9px] font-black text-green-500 uppercase tracking-widest mb-1">Готово</span>
            <span className="text-2xl font-black dark:text-white font-mono">{stats.finished}</span>
          </div>
        </div>
      </div>

      {showRecorder && (
        <div className="fixed inset-0 z-[200] bg-slate-950/70 backdrop-blur-xl flex items-center justify-center p-6 animate-in fade-in duration-500">
            <div className="relative max-w-xl w-full animate-slide-up">
                <button onClick={() => setShowRecorder(false)} className="absolute -top-6 -right-6 bg-white dark:bg-slate-800 p-3 rounded-full shadow-2xl text-gray-400 hover:text-red-500 z-[210] border border-white/10 transition-colors"><X size={24}/></button>
                <AudioRecorder onComplete={() => setShowRecorder(false)} />
            </div>
        </div>
      )}
    </div>
  );
};

