import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus } from '../types.ts';
import { 
  ChevronLeft, Trash2, Eye, Edit3, Sparkles, Globe, 
  CheckCircle2, PlayCircle, Search, Send, Loader2, ExternalLink, Hash, Save, Copy, Check, MessageSquare, X, Plus, Info, Layout
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [newTag, setNewTag] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [isSaving, setIsSaving] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [note, setNote] = useState<any>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'ai', text: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
      }
    }
  }, [id, notes]);

  useEffect(() => {
    chatScrollRef.current?.scrollTo(0, chatScrollRef.current.scrollHeight);
  }, [chatMessages]);

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (id === 'new') {
      await addNote(content, title, 'manual', useAI);
    } else if (note) {
      await updateNote({ ...note, title, content, tags });
      if (useAI) await runAIAnalysis(note.id);
    }
    setIsSaving(false);
    navigate('/');
  };

  const addManualTag = (e?: React.KeyboardEvent) => {
    if (e && e.key !== 'Enter') return;
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()]);
      setNewTag('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter(t => t !== tagToRemove));
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const context = `Заметка: ${title}\nТекст: ${content}`;
      const response = await ai.chatWithNotes(userMsg, context, settings);
      setChatMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setChatMessages(prev => [...prev, { role: 'ai', text: 'Ошибка ИИ при анализе контекста.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] transition-colors overflow-hidden">
      {/* Шапка редактора */}
      <div className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-8 flex-1">
          <button onClick={() => navigate(-1)} className="p-5 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-[1.5rem] transition-all"><ChevronLeft size={28}/></button>
          <input 
            className="text-5xl font-black bg-transparent border-none focus:outline-none text-black dark:text-white w-full max-w-5xl tracking-tighter placeholder:text-gray-200" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок от ИИ..."
          />
        </div>
        <div className="flex items-center gap-6">
          <button 
            onClick={() => ai.openInGoogle(title || content.slice(0, 50))}
            className="px-6 py-4 bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400 rounded-2xl hover:scale-105 transition-all flex items-center gap-3 text-[10px] font-black uppercase tracking-widest"
          >
            <ExternalLink size={18}/> Поиск
          </button>
          <button 
            onClick={() => handleSave(false)} 
            disabled={isSaving}
            className="px-10 py-4 bg-blue-600 text-white rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest hover:shadow-2xl hover:shadow-blue-500/30 active:scale-95 transition-all flex items-center gap-3"
          >
            <Save size={18}/> Сохранить
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Основное поле ввода */}
        <div className="flex-1 p-20 overflow-y-auto custom-scrollbar bg-slate-50/20 dark:bg-transparent">
          {viewMode === 'edit' ? (
            <textarea 
              className="w-full h-full bg-transparent border-none focus:outline-none text-3xl leading-[1.5] text-black dark:text-white resize-none font-bold placeholder:text-gray-200 min-h-[700px] selection:bg-blue-500/20"
              value={content}
              onChange={e => setContent(e.target.value)}
              placeholder="Начните писать или вставьте текст..."
            />
          ) : (
            <div 
              className="prose dark:prose-invert max-w-none text-3xl leading-[1.5] text-black dark:text-white font-bold whitespace-pre-wrap animate-in fade-in duration-500"
              dangerouslySetInnerHTML={{ __html: ai.linkify(content || 'Контент пуст...') }}
            />
          )}
        </div>

        {/* Правая панель (Виджеты) */}
        <div className="w-[500px] border-l border-gray-100 dark:border-white/5 flex flex-col bg-gray-50/50 dark:bg-slate-950/20 p-8 gap-8 overflow-y-auto custom-scrollbar">

          {/* 1. Чат (Разум Заметки) */}
          <div className="bg-white dark:bg-slate-900 rounded-[3rem] border border-gray-100 dark:border-white/5 flex flex-col h-[480px] shrink-0 shadow-xl overflow-hidden">
            <header className="p-8 border-b border-gray-50 dark:border-white/5 flex items-center justify-between bg-slate-50/50 dark:bg-slate-800/20">
              <span className="text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-3">
                <MessageSquare size={16}/> Разум Заметки
              </span>
              {chatMessages.length > 0 && (
                <button onClick={() => setChatMessages([])} className="text-[9px] font-black text-gray-400 hover:text-red-500 uppercase transition-colors">Очистить</button>
              )}
            </header>
            <div ref={chatScrollRef} className="flex-1 p-8 overflow-y-auto space-y-6 text-sm font-bold dark:text-slate-200">
              {chatMessages.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center text-gray-400 opacity-40 space-y-4 px-4">
                  <Bot size={40}/>
