            </div>
            <div className="p-6 bg-slate-50/50 dark:bg-slate-800/10 border-t border-gray-50 dark:border-white/5">
              <div className="relative">
                <input 
                  className="w-full pl-6 pr-14 py-5 bg-white dark:bg-slate-950 rounded-[1.5rem] text-sm font-bold border-none shadow-inner dark:text-white focus:ring-4 focus:ring-blue-500/10 transition-all"
                  placeholder="Напишите вопрос..."
                  value={chatInput}
                  onChange={e => setChatInput(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && handleChat()}
