                  disabled={isChatLoading || !chatInput.trim()}
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-3 bg-blue-600 text-white rounded-xl hover:scale-105 active:scale-95 transition-all disabled:opacity-30 shadow-lg shadow-blue-500/20"
                >
