      {/* Шапка редактора */}
      <div className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-8 flex-1">
          <button onClick={() => navigate(-1)} className="p-5 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-[1.5rem] transition-all"><ChevronLeft size={28}/></button>
          <input 
            className="text-5xl font-black bg-transparent border-none focus:outline-none text-black dark:text-white w-full max-w-5xl tracking-tighter placeholder:text-gray-200" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок от ИИ..."
          />
        </div>
        <div className="flex items-center gap-6">
          <button 
            onClick={() => ai.openInGoogle(title || content.slice(0, 50))}
            className="px-6 py-4 bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400 rounded-2xl hover:scale-105 transition-all flex items-center gap-3 text-[10px] font-black uppercase tracking-widest"
          >
            <ExternalLink size={18}/> Поиск
          </button>
          <button 
            onClick={() => handleSave(false)} 
            disabled={isSaving}
            className="px-10 py-4 bg-blue-600 text-white rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest hover:shadow-2xl hover:shadow-blue-500/30 active:scale-95 transition-all flex items-center gap-3"
          >
            <Save size={18}/> Сохранить
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Основное поле ввода */}
        <div className="flex-1 p-20 overflow-y-auto custom-scrollbar bg-slate-50/20 dark:bg-transparent">
          {viewMode === 'edit' ? (
            <textarea 
