        {/* Рабочая область */}
        <div className="flex-1 p-20 overflow-y-auto custom-scrollbar bg-slate-50/10 dark:bg-transparent">
          {viewMode === 'edit' ? (
            <textarea 
              className="w-full h-full bg-transparent border-none focus:outline-none text-3xl leading-relaxed text-black dark:text-slate-100 resize-none font-bold placeholder:text-gray-200 min-h-[700px] selection:bg-blue-500/20"
