import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  try {
    return JSON.parse(str);
  } catch (e) {
    // Продвинутый поиск JSON в строке
    const jsonMatch = str.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { return JSON.parse(jsonMatch[0]); } catch (inner) {}
    }
    const arrayMatch = str.match(/\[[\s\S]*\]/);
    if (arrayMatch) {
      try { return JSON.parse(arrayMatch[0]); } catch (inner) {}
    }
    console.warn("Could not parse AI response as JSON:", str);
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part, i) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline hover:text-blue-600 transition-colors">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  const url = `https://www.google.com/search?q=${encodeURIComponent(query)}`;
  window.open(url, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string
) {
  if (provider === AIProvider.Gemini) {
    const key = apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: model || 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction,
        responseMimeType: isJson ? "application/json" : undefined
      }
    });
    return isJson ? extractJSON(response.text || '{}') : response.text;
  }

  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;

  let url = baseUrl.replace(/\/$/, '');
  if (isOllama) url += '/api/generate';
  else if (isOR) url = 'https://openrouter.ai/api/v1/chat/completions';
  else {
    // Для кастомных OpenAI-совместимых провайдеров
    if (!url.endsWith('/v1/chat/completions') && !url.endsWith('/chat/completions')) {
        url += '/v1/chat/completions';
    }
  }

  const body: any = isOllama 
    ? { model: model, prompt: systemInstruction ? `${systemInstruction}\n\n${prompt}` : prompt, stream: false, format: isJson ? 'json' : undefined }
    : { 
        model: model, 
        messages: [
          ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
          { role: 'user', content: prompt }
        ],
        // Некоторые провайдеры падают на response_format, добавляем осторожно
        ...(isJson ? { response_format: { type: 'json_object' } } : {})
      };

  const headers: Record<string, string> = { 
    'Content-Type': 'application/json',
    ...(apiKey ? { 'Authorization': `Bearer ${apiKey}` } : {}),
    // Важно для OpenRouter
    ...(isOR ? { 
        'HTTP-Referer': window.location.origin,
        'X-Title': 'ScreenMind2 Ultra'
    } : {})
  };

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) {
    const errorText = await res.text();
    throw new Error(`Ошибка API (${res.status}): ${errorText || res.statusText}`);
  }

  const data = await res.json();
  const resultStr = isOllama ? data.response : data.choices[0].message.content;
  return isJson ? extractJSON(resultStr) : resultStr;
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `Проанализируй этот текст. Верни ТОЛЬКО JSON объект с полями:
"title" (придуманный заголовок, если его нет), 
"tags" (массив тегов), 
"category" (одна категория), 
"summary" (суть в 1 предложении).
Текст: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true);
};

// Fixed splitLargeText implementation
export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Раздели этот длинный текст на логические блоки (заметки). Каждый блок должен быть самостоятельным. Верни массив JSON объектов.
Текст: ${text}`;

  if (settings.provider === AIProvider.Gemini) {
    const key = settings.apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: settings.model || 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING },
              tags: { type: Type.ARRAY, items: { type: Type.STRING } },
              category: { type: Type.STRING }
            },
            required: ["title", "content", "tags", "category"]
          }
        }
      }
    });
    return JSON.parse(response.text || '[]');
  }

  const systemInstruction = `Раздели текст на логические блоки. Верни ТОЛЬКО массив JSON объектов с полями title, content, tags (массив строк), category.`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, systemInstruction);
};

export const chatWithNotes = async (query: string, context: string, settings: Settings): Promise<string> => {
  const prompt = `КОНТЕКСТ:\n${context}\n\nВОПРОС: ${query}`;
