  switch (type) {
    case 'ocr': return <ScanLine size={size} className={className} />;
    case 'telegram': return <Send size={size} className={className} />;
    case 'audio': return <Mic size={size} className={className} />;
    case 'split': return <Split size={size} className={className} />;
    default: return <Edit3 size={size} className={className} />;
  }
};

