import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus } from '../types.ts';
import { 
  ChevronLeft, Trash2, Eye, Edit3, Sparkles, Globe, 
  CheckCircle2, PlayCircle, Search, Send, Loader2, ExternalLink, Hash, Save, Copy, Check, MessageSquare, X, Plus, Info, Layout, Bot, Folder
} from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const NoteEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { notes, addNote, updateNote, runAIAnalysis, settings } = useNotes();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [category, setCategory] = useState('Общее');
  const [newTag, setNewTag] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [isSaving, setIsSaving] = useState(false);
  const [note, setNote] = useState<any>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<{role: 'user' | 'ai', text: string}[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (id && id !== 'new') {
      const found = notes.find(n => n.id === id);
      if (found) {
        setNote(found);
        setTitle(found.title);
        setContent(found.content);
        setTags(found.tags || []);
        setCategory(found.category || 'Общее');
      }
    }
  }, [id, notes]);

  useEffect(() => {
    chatScrollRef.current?.scrollTo(0, chatScrollRef.current.scrollHeight);
  }, [chatMessages]);

  const handleSave = async (useAI = false) => {
    if (!content.trim() && !title.trim()) return;
    setIsSaving(true);
    if (id === 'new') {
      await addNote(content, title, 'manual', useAI);
    } else if (note) {
      await updateNote({ ...note, title, content, tags, category });
      if (useAI) await runAIAnalysis(note.id);
    }
    setIsSaving(false);
    if (!useAI) navigate('/');
  };

  const addManualTag = (e?: React.KeyboardEvent) => {
    if (e && e.key !== 'Enter') return;
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()]);
      setNewTag('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter(t => t !== tagToRemove));
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const context = `Заметка: ${title}\nТекст: ${content}`;
      const response = await ai.chatWithNotes(userMsg, context, settings);
      setChatMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setChatMessages(prev => [...prev, { role: 'ai', text: 'Ошибка ИИ.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-[#020617] transition-colors overflow-hidden">
      {/* Шапка */}
      <div className="flex items-center justify-between px-12 py-8 border-b border-gray-100 dark:border-white/5 bg-white/80 dark:bg-slate-950/80 backdrop-blur-2xl z-20 shrink-0">
        <div className="flex items-center gap-6 flex-1">
          <button onClick={() => navigate(-1)} className="p-4 text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all"><ChevronLeft size={24}/></button>
          <input 
            className="text-4xl font-black bg-transparent border-none focus:outline-none text-black dark:text-white w-full tracking-tighter placeholder:text-gray-200" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            placeholder="Заголовок..."
          />
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => ai.openInGoogle(title || content.slice(0, 50))}
            className="px-6 py-4 bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400 rounded-2xl hover:scale-105 transition-all flex items-center gap-3 text-[10px] font-black uppercase tracking-widest border border-amber-200/50"
          >
            <Search size={18}/> Найти в Google
          </button>
          <button 
            onClick={() => handleSave(false)} 
            disabled={isSaving}
            className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest hover:shadow-xl active:scale-95 transition-all flex items-center gap-3"
          >
            <Save size={18}/> Сохранить
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Рабочая область */}
        <div className="flex-1 p-16 overflow-y-auto custom-scrollbar bg-slate-50/10 dark:bg-transparent">
          <textarea 
            className="w-full h-full bg-transparent border-none focus:outline-none text-4xl leading-snug text-black dark:text-white resize-none font-bold placeholder:text-gray-200 selection:bg-blue-500/20"
            value={content}
            onChange={e => setContent(e.target.value)}
            placeholder="Напишите здесь вашу мысль..."
          />
        </div>

        {/* Правая панель */}
        <div className="w-[480px] border-l border-gray-100 dark:border-white/5 flex flex-col bg-gray-50/50 dark:bg-slate-950/20 p-8 gap-6 overflow-y-auto custom-scrollbar">

          {/* Выбор Группы */}
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-gray-100 dark:border-white/5 shadow-md space-y-3">
             <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
               <Folder size={14} className="text-blue-500"/> Группа заметки
             </h4>
             <select 
               className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-xl font-black text-sm uppercase tracking-tight border-none focus:ring-4 focus:ring-blue-500/10 dark:text-white cursor-pointer"
               value={category}
               onChange={e => setCategory(e.target.value)}
             >
                {settings.customCategories.map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
             </select>
          </div>

          {/* Чат */}
          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-gray-100 dark:border-white/5 flex flex-col h-[350px] shrink-0 shadow-lg overflow-hidden">
            <header className="p-6 border-b border-gray-50 dark:border-white/5 flex items-center justify-between bg-slate-50/30">
              <span className="text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-2">
                <MessageSquare size={14}/> Разум Заметки
              </span>
            </header>
            <div ref={chatScrollRef} className="flex-1 p-6 overflow-y-auto space-y-4 text-sm font-bold dark:text-slate-300">
              {chatMessages.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center opacity-20 text-center gap-2">
                  <Bot size={40} />
                  <p className="text-[9px] uppercase tracking-widest">Задайте вопрос</p>
                </div>
              ) : chatMessages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-4 rounded-2xl ${
                    msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-slate-800'
                  }`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isChatLoading && <div className="animate-pulse flex gap-1"><div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div><div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div></div>}
            </div>
            <div className="p-4 bg-slate-50/30 border-t border-gray-50 dark:border-white/5">
              <div className="relative">
                <input 
                  className="w-full pl-5 pr-12 py-4 bg-white dark:bg-slate-950 rounded-xl text-sm font-bold border-none shadow-inner dark:text-white"
                  placeholder="Спросить..."
                  value={chatInput}
                  onChange={e => setChatInput(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && handleChat()}
                />
                <button 
                  onClick={handleChat} 
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-blue-600 text-white rounded-lg"
                >
                  <Send size={16}/>
                </button>
              </div>
            </div>
          </div>

          {/* AI-Интеллект */}
          <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-md space-y-4">
            <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-widest flex items-center gap-2">
              <Sparkles size={14} className="text-cyan-500" /> AI-Интеллект
            </h4>
            <div className="space-y-3">
              <div>
                <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Резюме</span>
                <p className="text-xs font-bold text-gray-700 dark:text-slate-300 mt-1 italic">
                  {note?.summary || 'Нажмите "Анализ" для получения выжимки.'}
                </p>
              </div>
            </div>
          </div>

          {/* Теги */}
          <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-gray-100 dark:border-white/5 space-y-6">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Hash size={14} className="text-blue-500"/> Нейро-теги
            </h4>
            <div className="flex flex-wrap gap-2">
              {tags.map((t: string) => (
                  <span key={t} className="px-3 py-1.5 bg-blue-500/5 dark:bg-blue-500/10 rounded-lg text-[9px] font-black text-blue-500 uppercase flex items-center gap-2 border border-blue-500/10">
                    #{t}
                    <button onClick={() => removeTag(t)} className="hover:text-red-500"><X size={10}/></button>
                  </span>
              ))}
            </div>
            <div className="relative">
              <input 
                className="w-full p-4 bg-gray-50 dark:bg-slate-950 rounded-xl text-[10px] font-black uppercase border-none dark:text-white"
                placeholder="Добавить тег..."
                value={newTag}
                onChange={e => setNewTag(e.target.value)}
                onKeyDown={addManualTag}
              />
              <button onClick={() => addManualTag()} className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-500"><Plus size={14}/></button>
            </div>
            <button 
              onClick={() => handleSave(true)}
              className="w-full py-4 bg-cyan-500/10 text-cyan-600 dark:text-cyan-400 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-cyan-500/20 transition-all flex items-center justify-center gap-2 border border-cyan-500/20 shadow-sm"
