const extractJSON = (str: string) => {
  if (!str) return {};
  try {
    // 1. Попытка прямого парсинга
    return JSON.parse(str.trim());
  } catch (e) {
    // 2. Поиск JSON внутри текста (модели часто добавляют пояснения)
    const jsonMatch = str.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { 
        let cleaned = jsonMatch[0]
          .replace(/```json/g, '')
          .replace(/```/g, '')
          .trim();
        return JSON.parse(cleaned); 
      } catch (inner) {
        console.error("Failed to parse extracted JSON:", inner);
      }
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string
) {
  // 1. Обработка Gemini (Google Native)
  if (provider === AIProvider.Gemini) {
    const key = apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    try {
      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err) {
      console.error("Gemini Error:", err);
      throw err;
    }
  }

  // 2. Универсальная обработка (Ollama, LM Studio, OpenRouter)
  const isOllama = provider === AIProvider.Ollama;

  let url = baseUrl.trim().replace(/\/$/, '');

  if (isOllama) {
    url += '/api/chat';
  } else {
    // Для LM Studio и других OpenAI-совместимых проверяем /v1
    if (!url.toLowerCase().endsWith('/v1') && !url.includes('/v1/')) {
       // Если пользователь просто ввел localhost:1234
       url += '/v1';
    }
    if (!url.includes('/chat/completions')) {
      url += '/chat/completions';
    }
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: prompt }
  ];

  const body: any = isOllama 
    ? { 
        model: model, 
        messages: messages,
        stream: false, 
        format: isJson ? 'json' : undefined 
      }
    : { 
        model: model, 
        messages: messages,
        ...(isJson ? { response_format: { type: 'json_object' } } : {})
      };

  const headers: Record<string, string> = { 
    'Content-Type': 'application/json',
    ...(apiKey ? { 'Authorization': `Bearer ${apiKey}` } : {})
  };

  try {
    const res = await fetch(url, { 
      method: 'POST', 
      headers, 
      body: JSON.stringify(body),
      // Увеличиваем таймаут для локальных моделей
      signal: AbortSignal.timeout(60000) 
    });

    if (!res.ok) {
      const errText = await res.text();
      throw new Error(`AI Provider ${provider} Error: ${res.status} - ${errText}`);
    }

    const data = await res.json();
    const resultStr = isOllama ? data.message.content : data.choices[0].message.content;

    if (isJson) {
      const parsed = extractJSON(resultStr);
      // Если пустой объект, возможно модель просто ответила текстом
      if (Object.keys(parsed).length === 0) {
        console.warn("Model returned empty JSON or text instead of JSON:", resultStr);
      }
      return parsed;
    }
    return resultStr;
  } catch (error: any) {
    console.error(`AI call failed for ${provider}:`, error);
    throw error;
  }
}

