export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  if (settings.ocrProvider === AIProvider.Gemini) {
    const key = settings.ocrApiKey || settings.apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
      model: settings.ocrModel || 'gemini-2.5-flash-image',
      contents: { 
        parts: [
          { inlineData: { data: base64Data.split(',')[1] || base64Data, mimeType } }, 
          { text: "Извлеки весь текст с картинки. Верни только чистый текст." }
        ] 
      }
    });
    return response.text || "Текст не распознан.";
  }
  return "OCR сейчас поддерживает только Gemini Vision.";
};

import React, { useState, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { ImageIcon, Loader2, ScanLine, Sparkles, Plus, FileText, CheckCircle2, Files, Upload, X } from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const OcrPage: React.FC = () => {
  const { addNote, settings, addLog } = useNotes();
  const [isProcessing, setIsProcessing] = useState(false);
  const [queue, setQueue] = useState<number>(0);
  const [results, setResults] = useState<{name: string, text: string}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    const files = Array.from(e.dataTransfer.files).filter((f: File) => f.type.startsWith('image/')) as File[];
    if (files.length > 0) processFiles(files);
  };

  const processFiles = async (files: File[]) => {
    setIsProcessing(true);
    setQueue(files.length);
    addLog('info', `Запущен OCR конвейер для ${files.length} объектов`);

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setQueue(files.length - i);
      try {
        const text = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = async () => {
            try {
              const base64 = reader.result as string;
              const res = await ai.performOCR(base64, file.type, settings);
              resolve(res);
            } catch (e) {
              reject(e);
            }
          };
          reader.onerror = () => reject(new Error("Ошибка чтения файла"));
          reader.readAsDataURL(file);
        });

        await addNote(text, `Скан: ${file.name}`, 'ocr', true);
        setResults(prev => [{ name: file.name, text }, ...prev]);
        addLog('success', `Файл ${file.name} интегрирован в базу`);
      } catch (err: any) {
        addLog('error', `Ошибка OCR (${file.name}): ${err.message}`);
      }
    }

    setIsProcessing(false);
    setQueue(0);
  };

  const onFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []).filter((f: File) => f.type.startsWith('image/')) as File[];
    if (files.length > 0) processFiles(files);
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="p-12 max-w-5xl mx-auto min-h-screen animate-in fade-in duration-500 pb-32">
      <header className="mb-16 flex justify-between items-end">
        <div>
          <div className="flex items-center gap-3 text-blue-600 font-black text-[11px] uppercase tracking-[0.4em]">
            <ScanLine size={16} /> Vision Batch Engine
          </div>
          <h2 className="text-6xl font-black dark:text-white mt-2 tracking-tighter">Скан-центр</h2>
          <p className="text-gray-500 mt-4 text-lg max-w-xl">Автоматическое распознавание и тегирование скриншотов через ИИ нового поколения.</p>
        </div>
        <button 
          onClick={triggerFileInput}
          disabled={isProcessing}
          className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 hover:bg-blue-700 shadow-xl transition-all disabled:opacity-50"
        >
          <Upload size={18}/> Выбрать файлы
        </button>
      </header>

      <div 
        onDragOver={(e) => { e.preventDefault(); e.currentTarget.classList.add('border-blue-500', 'bg-blue-50/50'); }}
        onDragLeave={(e) => { e.currentTarget.classList.remove('border-blue-500', 'bg-blue-50/50'); }}
        onDrop={(e) => { e.currentTarget.classList.remove('border-blue-500', 'bg-blue-50/50'); handleDrop(e); }}
        className={`relative h-[350px] border-4 border-dashed rounded-[4rem] flex flex-col items-center justify-center transition-all group overflow-hidden ${
          isProcessing 
          ? 'bg-blue-50 border-blue-400 dark:bg-blue-950/20' 
          : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800 hover:border-blue-400 hover:bg-blue-50/10'
        }`}
      >
        <input 
          ref={fileInputRef}
          type="file" 
          multiple
          className="hidden" 
          accept="image/*"
          onChange={onFileInput}
        />

        {isProcessing ? (
          <div className="flex flex-col items-center gap-8 animate-in zoom-in">
            <div className="relative">
                <Loader2 className="animate-spin text-blue-600" size={80} />
                <span className="absolute inset-0 flex items-center justify-center font-black text-sm text-blue-600">{queue}</span>
            </div>
            <div className="text-center">
              <p className="text-xl font-black text-blue-600 uppercase tracking-[0.2em] animate-pulse">
                Обработка потока...
              </p>
              <p className="text-[10px] text-gray-400 uppercase font-black mt-2">Не закрывайте вкладку</p>
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-8 text-center px-12">
            <div className="p-10 bg-blue-50 dark:bg-blue-900/20 rounded-[2.5rem] text-blue-600 group-hover:scale-110 transition-transform shadow-inner">
              <Files size={72} />
            </div>
            <div>
              <p className="text-3xl font-black dark:text-white uppercase tracking-tighter">Перетащите файлы сюда</p>
              <p className="text-gray-400 font-bold mt-3 uppercase text-[10px] tracking-widest">или нажмите кнопку «Выбрать файлы»</p>
            </div>
          </div>
        )}
      </div>

      {results.length > 0 && (
