import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();

  // 1. Попытка прямого парсинга
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    // 2. Поиск JSON блока с помощью регулярок (самый надежный способ для "болтливых" моделей)
    // Ищем содержимое между первой открывающей и последней закрывающей фигурной скобкой
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);

    if (match) {
      try {
        // Очистка от возможных markdown-оберток ```json ... ```
        const cleaned = match[0]
          .replace(/```json/g, '')
          .replace(/```/g, '')
          .trim();
        return JSON.parse(cleaned);
      } catch (inner) {
        console.error("Не удалось распарсить извлеченный JSON блок:", inner, "Блок:", match[0]);
      }
    }

    // 3. Крайний случай: если это массив (например для splitLargeText)
    const arrayRegex = /\[[\s\S]*\]/;
    const arrayMatch = trimmed.match(arrayRegex);
    if (arrayMatch) {
       try {
         const cleaned = arrayMatch[0].replace(/```json/g, '').replace(/```/g, '').trim();
         return JSON.parse(cleaned);
       } catch (inner) {}
    }

    console.warn("JSON не найден в ответе ИИ:", trimmed);
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string
) {
  // 1. Обработка Google Gemini
  if (provider === AIProvider.Gemini) {
    const key = apiKey || process.env.API_KEY;
    const ai = new GoogleGenAI({ apiKey: key });
    try {
      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err) {
      throw new Error(`Gemini Error: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 2. Обработка Ollama, LM Studio, OpenRouter
  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;

  let url = (baseUrl || '').trim().replace(/\/$/, '');

  if (isOllama) {
    if (!url) url = 'http://localhost:11434';
    url += '/api/chat';
  } else {
    // OpenAI-совместимые пути
    if (!url) url = isOR ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1';

    if (isOR && !url.includes('openrouter.ai/api/v1')) {
        url = 'https://openrouter.ai/api/v1';
    }

    if (!url.endsWith('/chat/completions')) {
        if (!url.includes('/v1') && !isOR) url += '/v1';
        url += '/chat/completions';
    }
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: prompt }
  ];

  // ВАЖНО: Удаляем response_format: { type: 'json_object' } для LM Studio/OpenRouter, 
  // так как многие локальные модели или старые версии API возвращают 400.
  // Мы полагаемся на extractJSON и жесткую инструкцию в промпте.
  const body: any = isOllama 
    ? { 
        model: model, 
        messages: messages,
        stream: false, 
        format: isJson ? 'json' : undefined 
      }
    : { 
        model: model, 
        messages: messages,
        // Оставляем пустым или text, чтобы избежать ошибки 400: 'must be json_schema or text'
        response_format: { type: 'text' }
      };

  const headers: Record<string, string> = { 
    'Content-Type': 'application/json',
    ...(apiKey ? { 'Authorization': `Bearer ${apiKey}` } : {}),
    ...(isOR ? { 
        'HTTP-Referer': window.location.origin, 
        'X-Title': 'ScreenMind2 Ultra' 
    } : {})
  };

  try {
    const res = await fetch(url, { 
      method: 'POST', 
      headers, 
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(90000) // Таймаут 90 сек
    });

    if (!res.ok) {
      const errBody = await res.text();
      throw new Error(`HTTP ${res.status}: ${errBody.slice(0, 150)}`);
    }

    const data = await res.json();
    const resultStr = isOllama ? data.message.content : data.choices[0].message.content;

    if (isJson) {
      const parsed = extractJSON(resultStr);
      // Если пустой объект, пробуем вернуть хотя бы структуру по умолчанию
      if (Object.keys(parsed).length === 0) {
        console.error("Модель не вернула валидный JSON:", resultStr);
        throw new Error("Не удалось получить структурированные данные от ИИ.");
      }
      return parsed;
    }
    return resultStr;
  } catch (error: any) {
    throw new Error(`${provider} Connection Failed: ${error.message}`);
  }
}

