  const prompt = `ВЫПОЛНИ АНАЛИЗ ТЕКСТА. ВЕРНИ ТОЛЬКО ЧИСТЫЙ JSON ОБЪЕКТ БЕЗ ТЕКСТА ДО И ПОСЛЕ.
  ФОРМАТ:
