    "summary": "суть в одно предложение"
  }
  ТЕКСТ ДЛЯ АНАЛИЗА: ${text}`;

  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Ты — системный анализатор. Твой ответ должен содержать ТОЛЬКО валидный JSON.");
