import React, { useState, useRef, useEffect, useMemo } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { useNavigate } from 'react-router-dom';
import { Maximize2, Move, Clock, Share2, ZoomIn, ZoomOut } from 'lucide-react';
import { getTagColor } from '../utils/tagColors.ts';

const Workspace: React.FC = () => {
  const { notes, updateNotePosition, updateNoteSize } = useNotes();
  const navigate = useNavigate();
  const containerRef = useRef<HTMLDivElement>(null);

  const activeNotes = useMemo(() => notes.filter(n => n.status !== 'trash'), [notes]);

  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if ((e.target as HTMLElement).closest('.resize-handle')) {
        setResizingId(id);
        const note = notes.find(n => n.id === id);
        setOffset({ x: e.clientX, y: e.clientY });
        return;
    }
    setDraggingId(id);
    const note = notes.find(n => n.id === id);
    if (note?.position) {
      setOffset({ x: e.clientX - note.position.x * zoom, y: e.clientY - note.position.y * zoom });
    }
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (draggingId) {
      updateNotePosition(draggingId, (e.clientX - offset.x) / zoom, (e.clientY - offset.y) / zoom);
    }
    if (resizingId) {
        const note = notes.find(n => n.id === resizingId);
        if (note?.size) {
            const dx = (e.clientX - offset.x) / zoom;
            const dy = (e.clientY - offset.y) / zoom;
            updateNoteSize(resizingId, Math.max(200, note.size.w + dx), Math.max(150, note.size.h + dy));
            setOffset({ x: e.clientX, y: e.clientY });
        }
    }
  };

  const handleMouseUp = () => {
    setDraggingId(null);
    setResizingId(null);
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [draggingId, resizingId, offset, zoom]);

  // Генерация связей (линий) между карточками
  const links = useMemo(() => {
    const result: { x1: number, y1: number, x2: number, y2: number, color: string }[] = [];
    for (let i = 0; i < activeNotes.length; i++) {
        for (let j = i + 1; j < activeNotes.length; j++) {
            const n1 = activeNotes[i];
            const n2 = activeNotes[j];
            const commonTags = n1.tags.filter(t => n2.tags.includes(t));
            if (commonTags.length > 0 || n1.category === n2.category) {
                if (n1.position && n2.position && n1.size && n2.size) {
                    result.push({
                        x1: n1.position.x + n1.size.w / 2,
                        y1: n1.position.y + n1.size.h / 2,
                        x2: n2.position.x + n2.size.w / 2,
                        y2: n2.position.y + n2.size.h / 2,
                        color: commonTags.length > 0 ? getTagColor(commonTags[0]).text : '#cbd5e1'
                    });
                }
            }
        }
    }
    return result;
  }, [activeNotes]);

  return (
    <div ref={containerRef} className="flex-1 h-screen relative overflow-hidden bg-[radial-gradient(#e2e8f0_1px,transparent_1px)] dark:bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:40px_40px] transition-colors">
      <div className="absolute top-10 left-12 z-20 flex flex-col gap-4">
        <div>
            <h2 className="text-3xl font-black dark:text-white">Нейронное Поле</h2>
            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mt-2 flex items-center gap-2">
                <Share2 size={12} className="text-blue-500" /> Связи формируются автоматически
            </p>
        </div>
        <div className="flex gap-2">
            <button onClick={() => setZoom(z => Math.max(0.2, z - 0.1))} className="p-3 bg-white dark:bg-slate-800 rounded-xl shadow-sm hover:text-blue-500"><ZoomOut size={16}/></button>
            <button onClick={() => setZoom(z => Math.min(2, z + 0.1))} className="p-3 bg-white dark:bg-slate-800 rounded-xl shadow-sm hover:text-blue-500"><ZoomIn size={16}/></button>
        </div>
      </div>

      <div className="absolute inset-0 origin-top-left transition-transform duration-75" style={{ transform: `scale(${zoom})` }}>
        {/* SVG Layer for Links */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {links.map((link, idx) => (
                <line 
                    key={idx}
                    x1={link.x1} y1={link.y1} x2={link.x2} y2={link.y2} 
                    stroke={link.color} strokeWidth="1" strokeOpacity="0.2"
                    strokeDasharray="5,5"
                />
            ))}
        </svg>

        {activeNotes.map(note => {
          const colors = getTagColor(note.category);
          return (
            <div
              key={note.id}
              onMouseDown={(e) => handleMouseDown(e, note.id)}
              style={{
                left: note.position?.x ?? 0,
                top: note.position?.y ?? 0,
                width: note.size?.w ?? 300,
                height: note.size?.h ?? 250,
                zIndex: draggingId === note.id ? 100 : 1
              }}
              className="absolute bg-white dark:bg-slate-900 rounded-[2rem] border border-gray-100 dark:border-slate-800 shadow-xl flex flex-col group cursor-grab active:cursor-grabbing transition-shadow hover:shadow-2xl overflow-hidden"
            >
              <div className="px-6 py-4 flex items-center justify-between border-b border-gray-50 dark:border-slate-800 shrink-0">
                <span style={{ color: colors.text, backgroundColor: colors.bg }} className="text-[8px] font-black uppercase px-2 py-0.5 rounded-md">
                    {note.category}
                </span>
                <button onClick={() => navigate(`/editor/${note.id}`)} className="p-1.5 text-gray-300 hover:text-blue-500 rounded-lg transition-colors">
                    <Maximize2 size={14} />
                </button>
              </div>

              <div className="p-6 flex-1 overflow-hidden pointer-events-none select-none">
                <h3 className="font-extrabold text-sm mb-2 dark:text-white line-clamp-1">{note.title}</h3>
                <p className="text-xs text-gray-500 dark:text-slate-400 leading-relaxed line-clamp-4">{note.content}</p>
              </div>

              <div className="px-6 py-4 bg-gray-50/50 dark:bg-slate-800/50 flex items-center justify-between shrink-0">
                <div className="flex gap-1 overflow-hidden">
                    {note.tags.slice(0, 2).map(t => <span key={t} className="text-[8px] text-gray-400 font-bold whitespace-nowrap">#{t}</span>)}
                </div>
                <div className="flex items-center gap-2 text-[8px] font-black text-gray-300 uppercase tracking-widest whitespace-nowrap">
                    <Clock size={10}/> {new Date(note.createdAt).toLocaleDateString()}
                </div>
              </div>

              <div className="absolute bottom-1 right-1 cursor-nwse-resize opacity-0 group-hover:opacity-100 transition-opacity p-2 text-gray-300 resize-handle">
                <Maximize2 size={12} className="rotate-90" />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Workspace;

import React, { useState, useRef } from 'react';
import { useNotes } from '../contexts/NotesContext.tsx';
import { Loader2, ScanLine, FileText, CheckCircle2, Files, Upload, X, AlertCircle } from 'lucide-react';
import * as ai from '../utils/aiAdapter.ts';

const OcrPage: React.FC = () => {
  const { addNote, settings, addLog } = useNotes();
  const [isProcessing, setIsProcessing] = useState(false);
  const [queue, setQueue] = useState<number>(0);
  const [results, setResults] = useState<{name: string, text: string}[]>([]);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    const files = Array.from(e.dataTransfer.files).filter((f: File) => f.type.startsWith('image/')) as File[];
    if (files.length > 0) processFiles(files);
  };

  const processFiles = async (files: File[]) => {
    setIsProcessing(true);
    setError(null);
    setQueue(files.length);
    addLog('info', `Запуск OCR для ${files.length} файлов`);

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setQueue(files.length - i);
      try {
        const base64 = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });

        const text = await ai.performOCR(base64, file.type, settings);
        await addNote(text, `Скан: ${file.name}`, 'ocr', true);
        setResults(prev => [{ name: file.name, text }, ...prev]);
        addLog('success', `OCR ${file.name} OK`);
      } catch (err: any) {
        setError(err.message);
        addLog('error', `OCR Error (${file.name}): ${err.message}`);
        break; // Stop batch on error to prevent cascading 429
      }
    }

    setIsProcessing(false);
    setQueue(0);
  };

  const onFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []).filter((f: File) => f.type.startsWith('image/')) as File[];
    if (files.length > 0) processFiles(files);
  };

  return (
    <div className="p-12 max-w-5xl mx-auto min-h-screen animate-in fade-in duration-500 pb-32">
      <header className="mb-16 flex justify-between items-end">
        <div>
          <div className="flex items-center gap-3 text-blue-600 font-black text-[11px] uppercase tracking-[0.4em]">
            <ScanLine size={16} /> Vision Intelligence
          </div>
          <h2 className="text-6xl font-black dark:text-white mt-2 tracking-tighter">Скан-центр</h2>
          <p className="text-gray-500 mt-4 text-lg max-w-xl">
            Движок: <span className="text-blue-600 font-black">{settings.ocrProvider} {settings.ocrModel}</span>
          </p>
        </div>
        <button 
          onClick={() => fileInputRef.current?.click()}
          disabled={isProcessing}
          className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 hover:bg-blue-700 shadow-xl transition-all disabled:opacity-50"
        >
          <Upload size={18}/> Выбрать файлы
        </button>
      </header>

      <div 
        onDragOver={(e) => { e.preventDefault(); e.currentTarget.classList.add('border-blue-500', 'bg-blue-50/50'); }}
        onDragLeave={(e) => { e.currentTarget.classList.remove('border-blue-500', 'bg-blue-50/50'); }}
        onDrop={(e) => { e.currentTarget.classList.remove('border-blue-500', 'bg-blue-50/50'); handleDrop(e); }}
        className={`relative h-[300px] border-4 border-dashed rounded-[4rem] flex flex-col items-center justify-center transition-all group overflow-hidden ${
          isProcessing ? 'bg-blue-50 border-blue-400 dark:bg-blue-950/20' : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800'
        }`}
      >
        <input ref={fileInputRef} type="file" multiple className="hidden" accept="image/*" onChange={onFileInput} />

        {isProcessing ? (
          <div className="flex flex-col items-center gap-8">
            <Loader2 className="animate-spin text-blue-600" size={60} />
            <p className="text-xl font-black text-blue-600 uppercase tracking-widest">Осталось: {queue}</p>
          </div>
        ) : error ? (
          <div className="flex flex-col items-center gap-4 text-red-500 px-12 text-center">
            <AlertCircle size={48} />
            <p className="font-black uppercase text-sm tracking-widest">{error}</p>
            <button onClick={() => setError(null)} className="text-[10px] font-black underline">Попробовать снова</button>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-6 text-center">
            <div className="p-8 bg-blue-50 dark:bg-blue-900/20 rounded-[2rem] text-blue-600">
              <Files size={48} />
            </div>
            <p className="text-2xl font-black dark:text-white uppercase tracking-tighter">Перетащите скрины сюда</p>
          </div>
        )}
      </div>

      {results.length > 0 && (
        <div className="mt-16 space-y-4 animate-in slide-in-from-bottom">
          <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-4">Распознано ({results.length})</h4>
          {results.map((res, i) => (
            <div key={i} className="p-6 bg-white dark:bg-slate-900 border border-gray-100 dark:border-slate-800 rounded-[2.5rem] flex items-center gap-6 shadow-sm">
               <CheckCircle2 className="text-green-500 shrink-0" size={24}/>
               <div className="flex-1 overflow-hidden">
                  <p className="font-black text-sm dark:text-white truncate uppercase mb-1">{res.name}</p>
                  <p className="text-xs text-gray-400 truncate italic">"{res.text.slice(0, 100)}..."</p>
               </div>
               <button onClick={() => navigate('/')} className="p-3 bg-gray-50 dark:bg-slate-800 rounded-xl text-gray-400 hover:text-blue-500 transition-colors">
                  <FileText size={18}/>
               </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

