        </div>
        <div className="flex gap-2">
            <button onClick={() => setZoom(z => Math.max(0.2, z - 0.1))} className="p-3 bg-white dark:bg-slate-800 rounded-xl shadow-sm hover:text-blue-500 transition-colors"><ZoomOut size={16}/></button>
            <button onClick={() => setZoom(z => Math.min(2, z + 0.1))} className="p-3 bg-white dark:bg-slate-800 rounded-xl shadow-sm hover:text-blue-500 transition-colors"><ZoomIn size={16}/></button>
            <button onClick={() => setZoom(1)} className="p-3 bg-white dark:bg-slate-800 rounded-xl shadow-sm hover:text-blue-500 transition-colors text-[10px] font-black uppercase">100%</button>
        </div>
      </div>

      <div className="absolute inset-0 origin-top-left transition-transform duration-75" style={{ transform: `scale(${zoom})` }}>
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {links.map((link, idx) => (
                <line 
                    key={idx}
                    x1={link.x1} y1={link.y1} x2={link.x2} y2={link.y2} 
                    stroke={link.color} strokeWidth="1.5" strokeOpacity="0.3"
                    strokeDasharray="8,8"
                    className="animate-[dash_20s_linear_infinite]"
                />
            ))}
        </svg>

        {activeNotes.map(note => {
          const colors = getTagColor(note.category);
          return (
            <div
              key={note.id}
              onMouseDown={(e) => handleMouseDown(e, note.id)}
              style={{
                left: note.position?.x ?? 0,
                top: note.position?.y ?? 0,
                width: note.size?.w ?? 300,
                height: note.size?.h ?? 250,
                zIndex: draggingId === note.id || resizingId === note.id ? 100 : 1
              }}
              className={`absolute bg-white dark:bg-slate-900 rounded-[2rem] border shadow-xl flex flex-col group cursor-grab active:cursor-grabbing transition-shadow hover:shadow-2xl overflow-hidden ${
                draggingId === note.id ? 'ring-2 ring-blue-500 shadow-2xl' : 'border-gray-100 dark:border-slate-800'
              }`}
            >
              <div className="px-6 py-4 flex items-center justify-between border-b border-gray-50 dark:border-slate-800 shrink-0">
                <span style={{ color: colors.text, backgroundColor: colors.bg }} className="text-[8px] font-black uppercase px-2 py-0.5 rounded-md">
                    {note.category}
                </span>
                <button 
                    onMouseDown={(e) => e.stopPropagation()} 
                    onClick={() => navigate(`/editor/${note.id}`)} 
                    className="p-1.5 text-gray-300 hover:text-blue-500 rounded-lg transition-colors"
