import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

export const openInGoogle = (query: string) => {
  if (!query) return;
  window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  imagePart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    const key = apiKey || process.env.API_KEY;
    // Всегда создаем новый экземпляр перед вызовом, чтобы использовать актуальный ключ из диалога
    const ai = new GoogleGenAI({ apiKey: key });
    try {
      const contents = imagePart 
        ? { parts: [{ inlineData: imagePart }, { text: prompt }] }
        : prompt;

      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: contents,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err: any) {
      const errorMsg = err.message || '';

      // Специальная обработка 404 согласно правилам разработки Gemini API
      if (errorMsg.includes('Requested entity was not found')) {
        if (typeof window !== 'undefined' && (window as any).aistudio?.openSelectKey) {
          await (window as any).aistudio.openSelectKey();
          throw new Error("Модель не найдена или требуется платный API ключ. Открыто окно выбора ключа. Пожалуйста, выберите ключ и повторите попытку.");
        }
      }

      if (errorMsg.includes('429')) {
        throw new Error("Лимит запросов исчерпан (429). Попробуйте позже или смените модель.");
      }

      throw new Error(`Gemini Error: ${errorMsg}`);
    }
  }

  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;
  let url = (baseUrl || '').trim().replace(/\/$/, '');

  if (isOllama) {
    if (!url) url = 'http://localhost:11434';
    url += '/api/chat';
  } else {
    if (!url) url = isOR ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1';
    if (!url.endsWith('/chat/completions')) {
        if (!url.includes('/v1') && !isOR) url += '/v1';
        url += '/chat/completions';
    }
  }

  const userContent: any[] = [{ type: 'text', text: prompt }];
  if (imagePart) {
    userContent.push({
      type: 'image_url',
      image_url: { url: `data:${imagePart.mimeType};base64,${imagePart.data}` }
    });
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: imagePart && !isOllama ? userContent : prompt }
  ];

  const body: any = { 
    model: model, 
    messages: messages,
    stream: false,
    ...(isOllama && isJson ? { format: 'json' } : {})
  };

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey && apiKey.trim() !== '') {
    headers['Authorization'] = `Bearer ${apiKey}`;
  }

  if (isOR) {
    headers['HTTP-Referer'] = window.location.origin;
    headers['X-Title'] = 'ScreenMind2';
  }

  try {
    const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
    if (res.status === 429) throw new Error("Лимит запросов (429). Смените провайдера или модель.");
    if (!res.ok) {
        const errText = await res.text();
        throw new Error(`HTTP ${res.status}: ${errText.slice(0, 100)}`);
    }

    const data = await res.json();
    const content = isOllama ? data.message.content : data.choices[0].message.content;
    return isJson ? extractJSON(content) : content;
  } catch (error: any) {
    if (error.name === 'TypeError' && error.message === 'Failed to fetch') {
        const hint = isOllama 
            ? ". Проверьте, запущен ли Ollama и установлена ли переменная OLLAMA_ORIGINS='*'" 
            : ". Проверьте сетевое соединение или настройки CORS на сервере.";
        throw new Error(`${provider}: Ошибка подключения (Failed to fetch)${hint}`);
    }
    throw new Error(`${provider}: ${error.message}`);
  }
}

