import { useNotes } from '../contexts/NotesContext.tsx';
import { NoteStatus, Note, LibraryView, CardSize } from '../types.ts';
import { 
  Search, Trash2, Sparkles, ChevronRight, 
  X, FileText, Grid, List, Layers, 
  ChevronUp, ChevronDown, Plus, Edit3, Share2, ZoomIn, Info
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { getTagColor } from '../utils/tagColors.ts';

const NotesPage: React.FC = () => {
  const { 
    notes, filterTag, setFilterTag, filterCategory, setFilterCategory, 
    processLargeText, settings, updateSettings, deleteCategory 
  } = useNotes();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const matchesSearch = n.title.toLowerCase().includes(search.toLowerCase()) || n.content.toLowerCase().includes(search.toLowerCase());
    const matchesTag = !filterTag || n.tags.includes(filterTag);
    const matchesCategory = !filterCategory || n.category === filterCategory;
    return matchesSearch && matchesTag && matchesCategory && n.status !== 'trash';
  }), [notes, search, filterTag, filterCategory]);

  const handleImport = async () => {
    if (!importText.trim()) return;
    await processLargeText(importText);
    setImportText('');
    setShowImport(false);
  };

  const reorderCategory = (cat: string, direction: 'up' | 'down') => {
    const idx = settings.customCategories.indexOf(cat);
    const newCats = [...settings.customCategories];
    const target = direction === 'up' ? idx - 1 : idx + 1;
    if (target >= 0 && target < newCats.length) {
      [newCats[idx], newCats[target]] = [newCats[target], newCats[idx]];
      updateSettings({ ...settings, customCategories: newCats });
    }
  };

  // Logic for Neural Connections Lines
  const [links, setLinks] = useState<{x1:number, y1:number, x2:number, y2:number, color:string}[]>([]);

  useEffect(() => {
    if (settings.libraryView !== 'neural' || !containerRef.current) {
        setLinks([]);
        return;
    }

    const calculateLinks = () => {
        const newLinks: any[] = [];
        const cardElements = containerRef.current?.querySelectorAll('[data-note-id]');
        if (!cardElements) return;

        const rectMap = new Map();
        cardElements.forEach(el => {
            const id = el.getAttribute('data-note-id');
            rectMap.set(id, el.getBoundingClientRect());
        });

        const containerRect = containerRef.current!.getBoundingClientRect();

        for (let i = 0; i < filteredNotes.length; i++) {
            for (let j = i + 1; j < filteredNotes.length; j++) {
                const n1 = filteredNotes[i];
                const n2 = filteredNotes[j];
                const commonTags = n1.tags.filter(t => n2.tags.includes(t));

                if (commonTags.length > 0 || n1.category === n2.category) {
                    const r1 = rectMap.get(n1.id);
                    const r2 = rectMap.get(n2.id);
                    if (r1 && r2) {
                        newLinks.push({
                            x1: r1.left + r1.width/2 - containerRect.left,
                            y1: r1.top + r1.height/2 - containerRect.top,
                            x2: r2.left + r2.width/2 - containerRect.left,
                            y2: r2.top + r2.height/2 - containerRect.top,
                            color: commonTags.length > 0 ? getTagColor(commonTags[0]).text : '#3b82f6'
                        });
                    }
                }
            }
        }
        setLinks(newLinks);
    };

    const timer = setTimeout(calculateLinks, 100);
    window.addEventListener('resize', calculateLinks);
    return () => {
        clearTimeout(timer);
        window.removeEventListener('resize', calculateLinks);
    };
  }, [filteredNotes, settings.libraryView, settings.cardSize]);

  const gridCols = {
    sm: 'grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4',
    md: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8',
    lg: 'grid-cols-1 md:grid-cols-1 lg:grid-cols-2 gap-12'
  }[settings.cardSize];

  return (
    <div className="p-8 max-w-[1600px] mx-auto min-h-screen relative animate-in fade-in duration-700">
      <header className="flex flex-col gap-8 mb-12">
        <div className="flex flex-col md:flex-row items-end justify-between gap-8">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className="text-blue-500 font-black text-[10px] uppercase tracking-[0.4em] flex items-center gap-2">
                <Sparkles size={14}/> Neural Knowledge Base
              </span>
            </div>
            <h2 className="text-6xl font-black dark:text-white tracking-tighter">Библиотека</h2>
          </div>

          <div className="flex items-center gap-4 bg-white dark:bg-slate-900 p-3 rounded-[2rem] border dark:border-slate-800 shadow-xl">
            <div className="flex bg-gray-100 dark:bg-slate-800 p-1 rounded-xl">
              <button onClick={() => updateSettings({...settings, libraryView: 'grid'})} className={`p-2 rounded-lg ${settings.libraryView === 'grid' ? 'bg-white dark:bg-slate-700 text-blue-500 shadow-sm' : 'text-gray-400'}`}><Grid size={18}/></button>
              <button onClick={() => updateSettings({...settings, libraryView: 'list'})} className={`p-2 rounded-lg ${settings.libraryView === 'list' ? 'bg-white dark:bg-slate-700 text-blue-500 shadow-sm' : 'text-gray-400'}`}><List size={18}/></button>
              <button onClick={() => updateSettings({...settings, libraryView: 'neural'})} className={`p-2 rounded-lg ${settings.libraryView === 'neural' ? 'bg-white dark:bg-slate-700 text-blue-500 shadow-sm' : 'text-gray-400'}`}><Layers size={18}/></button>
            </div>
            <div className="h-6 w-px bg-gray-200 dark:bg-slate-700 mx-2" />
            <div className="flex gap-1">
              {(['sm', 'md', 'lg'] as CardSize[]).map(size => (
                <button 
                    key={size} onClick={() => updateSettings({...settings, cardSize: size})}
                    className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase transition-all ${settings.cardSize === size ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-slate-800 text-gray-400'}`}
