import { Settings, AIProvider } from '../types.ts';
import { GoogleGenAI, Type } from "@google/genai";

const extractJSON = (str: string) => {
  if (!str) return {};
  const trimmed = str.trim();
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    const jsonRegex = /\{[\s\S]*\}/;
    const match = trimmed.match(jsonRegex);
    if (match) {
      try {
        const cleaned = match[0].replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned);
      } catch (inner) {}
    }
    return {};
  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  imagePart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    // FIX: Strictly follow guidelines: Use process.env.API_KEY directly for Google GenAI SDK initialization.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const contents = imagePart 
        ? { parts: [{ inlineData: imagePart }, { text: prompt }] }
        : prompt;

      // FIX: Using recommended models and direct .text property access for GenerateContentResponse
      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: contents,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err: any) {
      const errorMsg = err.message || '';

      // FIX: Handle 404/Requested entity was not found and trigger API key selection if applicable
      if (errorMsg.includes('Requested entity was not found') || errorMsg.includes('404')) {
        if (typeof window !== 'undefined' && (window as any).aistudio?.openSelectKey) {
          await (window as any).aistudio.openSelectKey();
          throw new Error("Gemini: Ресурс не найден. Открыто окно выбора ключа. Выберите проект с включенным биллингом.");
        }
      }
      throw new Error(`Gemini Error: ${errorMsg}`);
    }
  }

  // Local / OpenAI-like providers logic
  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;
  let url = (baseUrl || '').trim().replace(/\/$/, '');

  if (isOllama) {
    if (!url) url = 'http://localhost:11434';
    url += '/api/chat';
  } else {
    if (!url) url = isOR ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1';
    if (!url.endsWith('/chat/completions')) {
        if (!url.includes('/v1') && !isOR) url += '/v1';
        url += '/chat/completions';
    }
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: prompt }
  ];

  const body: any = { 
    model, 
    messages, 
    stream: false,
    ...(isOllama && isJson ? { format: 'json' } : {})
  };

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  try {
    const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
    const data = await res.json();
    return isJson ? extractJSON(isOllama ? data.message.content : data.choices[0].message.content) : (isOllama ? data.message.content : data.choices[0].message.content);
  } catch (error: any) {
    throw new Error(`${provider}: ${error.message}`);
  }
}

