  return await callAI(
    "Extract all text clearly. Return raw text only.",
    settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined,
    { data: dataOnly, mimeType }
  );
};

export const transcribeAudio = async (audioBlob: Blob, settings: Settings) => {
  const base64 = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(audioBlob);
  });
  return await callAI("Transcribe this audio.", settings.transProvider, settings.transModel, settings.transApiKey, settings.transUrl, false, undefined, { data: base64, mimeType: 'audio/webm' });
};

