  }
};

export const linkify = (text: string) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part) => {
    if (part.match(urlRegex)) {
      return `<a href="${part}" target="_blank" rel="noopener noreferrer" class="text-blue-500 underline">${part}</a>`;
    }
    return part;
  }).join('');
};

async function callAI(
  prompt: string, 
  provider: AIProvider, 
  model: string, 
  apiKey: string, 
  baseUrl: string, 
  isJson: boolean, 
  systemInstruction?: string,
  imagePart?: { data: string, mimeType: string }
) {
  if (provider === AIProvider.Gemini) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const contents = imagePart 
        ? { parts: [{ inlineData: imagePart }, { text: prompt }] }
        : prompt;

      const response = await ai.models.generateContent({
        model: model || 'gemini-3-flash-preview',
        contents: contents,
        config: {
          systemInstruction,
          responseMimeType: isJson ? "application/json" : undefined
        }
      });
      return isJson ? extractJSON(response.text || '{}') : response.text;
    } catch (err: any) {
      if (err.message?.includes('Requested entity was not found') || err.message?.includes('404')) {
        if (typeof window !== 'undefined' && (window as any).aistudio?.openSelectKey) {
          await (window as any).aistudio.openSelectKey();
        }
      }
      throw err;
    }
  }

  // Local/OpenRouter fallback
  const isOllama = provider === AIProvider.Ollama;
  const isOR = provider === AIProvider.OpenRouter;
  let url = (baseUrl || '').trim().replace(/\/$/, '');

  if (isOllama) {
    if (!url) url = 'http://localhost:11434';
    url += '/api/chat';
  } else {
    if (!url) url = isOR ? 'https://openrouter.ai/api/v1' : 'http://localhost:1234/v1';
    if (!url.endsWith('/chat/completions')) {
        if (!url.includes('/v1') && !isOR) url += '/v1';
        url += '/chat/completions';
    }
  }

  const messages = [
    ...(systemInstruction ? [{ role: 'system', content: systemInstruction }] : []),
    { role: 'user', content: prompt }
  ];

  const body: any = { model, messages, stream: false, ...(isOllama && isJson ? { format: 'json' } : {}) };
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json();
  const content = isOllama ? data.message.content : data.choices[0].message.content;
  return isJson ? extractJSON(content) : content;
}

export const analyzeText = async (text: string, settings: Settings) => {
  const prompt = `JSON ONLY: { "title": "...", "tags": ["..."], "category": "...", "summary": "..." }. Categories: ${settings.customCategories.join(',')}. TEXT: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Master Knowledge Synthesizer.");
};

export const splitLargeText = async (text: string, settings: Settings) => {
  const prompt = `Split text into semantic parts (max ${settings.splitChunkSize} chars). Return JSON ARRAY of objects: [{ "title": "...", "content": "...", "tags": [], "category": "...", "summary": "..." }]. TEXT: ${text}`;
  return await callAI(prompt, settings.provider, settings.model, settings.apiKey, settings.url, true, "Semantic Splitter.");
};

export const chatWithNotes = async (query: string, context: string, settings: Settings) => {
  return await callAI(`Context: ${context}\nQuery: ${query}`, settings.provider, settings.model, settings.apiKey, settings.url, false);
};

export const chatWithAgent = async (query: string, appData: any, settings: Settings) => {
  return await callAI(`App State: ${JSON.stringify(appData)}\nQuery: ${query}`, settings.agentProvider, settings.agentModel, settings.agentApiKey, settings.agentUrl, false, "System Mind Agent.");
};

export const performOCR = async (base64Data: string, mimeType: string, settings: Settings) => {
  return await callAI("Extract all text.", settings.ocrProvider, settings.ocrModel, settings.ocrApiKey, settings.ocrUrl, false, undefined, { data: base64Data.split(',')[1] || base64Data, mimeType });
};

export const transcribeAudio = async (audioBlob: Blob, settings: Settings) => {
  const base64 = await new Promise<string>(r => { const reader = new FileReader(); reader.onload = () => r((reader.result as string).split(',')[1]); reader.readAsDataURL(audioBlob); });
  return await callAI("Transcribe audio.", settings.transProvider, settings.transModel, settings.transApiKey, settings.transUrl, false, undefined, { data: base64, mimeType: 'audio/webm' });
};

export const testConnection = async (settings: Settings) => {
  try { await callAI("ping", settings.provider, settings.model, settings.apiKey, settings.url, false); return { success: true, message: "OK" }; }
  catch (e: any) { return { success: false, message: e.message }; }
};

