    case 'new': return <Circle size={12} className={`text-blue-500 ${className}`} />;
    case 'in-work': return <PlayCircle size={12} className={`text-amber-500 ${className}`} />;
    case 'read': return <Eye size={12} className={`text-cyan-500 ${className}`} />;
    case 'finished': return <CheckCircle2 size={12} className={`text-green-500 ${className}`} />;
    default: return <Circle size={12} className={className} />;
  }
