const NotesPage: React.FC = () => {
  const { 
    notes, filterTag, setFilterTag, filterCategory, setFilterCategory, 
    processLargeText, settings, updateSettings, deleteCategory, moveToTrash, setNoteStatus, reanalyzeAll
  } = useNotes();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');
  const [isReindexing, setIsReindexing] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const filteredNotes = useMemo(() => notes.filter(n => {
    const matchesSearch = n.title.toLowerCase().includes(search.toLowerCase()) || n.content.toLowerCase().includes(search.toLowerCase());
    const matchesTag = !filterTag || n.tags.includes(filterTag);
    const matchesCategory = !filterCategory || n.category === filterCategory;
    return matchesSearch && matchesTag && matchesCategory && n.status !== 'trash';
  }), [notes, search, filterTag, filterCategory]);

  const handleReindex = async () => {
    setIsReindexing(true);
    await reanalyzeAll();
    setIsReindexing(false);
  };

  const reorderCategory = (cat: string, direction: 'up' | 'down') => {
    const idx = settings.customCategories.indexOf(cat);
    const newCats = [...settings.customCategories];
    const target = direction === 'up' ? idx - 1 : idx + 1;
    if (target >= 0 && target < newCats.length) {
      [newCats[idx], newCats[target]] = [newCats[target], newCats[idx]];
      updateSettings({ ...settings, customCategories: newCats });
    }
  };

  // Lines Logic
  const [links, setLinks] = useState<{x1:number, y1:number, x2:number, y2:number, color:string}[]>([]);
  useEffect(() => {
    if (settings.libraryView !== 'neural' || !containerRef.current) { setLinks([]); return; }
    const calculateLinks = () => {
        const newLinks: any[] = [];
        const cardElements = containerRef.current?.querySelectorAll('[data-note-id]');
        if (!cardElements) return;
        const rectMap = new Map();
        cardElements.forEach(el => rectMap.set(el.getAttribute('data-note-id'), el.getBoundingClientRect()));
        const containerRect = containerRef.current!.getBoundingClientRect();
        for (let i = 0; i < filteredNotes.length; i++) {
            for (let j = i + 1; j < filteredNotes.length; j++) {
                const n1 = filteredNotes[i];
                const n2 = filteredNotes[j];
                const commonTags = n1.tags.filter(t => n2.tags.includes(t));
                if (commonTags.length > 0 || n1.category === n2.category) {
                    const r1 = rectMap.get(n1.id); const r2 = rectMap.get(n2.id);
                    if (r1 && r2) {
                        newLinks.push({
                            x1: r1.left + r1.width/2 - containerRect.left, y1: r1.top + r1.height/2 - containerRect.top,
                            x2: r2.left + r2.width/2 - containerRect.left, y2: r2.top + r2.height/2 - containerRect.top,
                            color: commonTags.length > 0 ? getTagColor(commonTags[0]).text : '#3b82f6'
                        });
                    }
                }
            }
        }
        setLinks(newLinks);
    };
    const timer = setTimeout(calculateLinks, 100);
    window.addEventListener('resize', calculateLinks);
    return () => { clearTimeout(timer); window.removeEventListener('resize', calculateLinks); };
  }, [filteredNotes, settings.libraryView, settings.cardSize]);

  const gridCols = { sm: 'grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4', md: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6', lg: 'grid-cols-1 md:grid-cols-1 lg:grid-cols-2 gap-10' }[settings.cardSize];

