      <header className="flex flex-col gap-6 mb-12">
        <div className="flex flex-col md:flex-row items-end justify-between gap-6">
          <div className="space-y-2">
            <span className="text-blue-500 font-black text-[10px] uppercase tracking-[0.4em] flex items-center gap-2">
              <Sparkles size={14}/> Neural Knowledge Base
            </span>
            <h2 className="text-6xl font-black dark:text-white tracking-tighter">Библиотека</h2>
          </div>
          <div className="flex items-center gap-4 bg-white dark:bg-slate-900 p-2 rounded-[2rem] border dark:border-slate-800 shadow-xl">
            <button onClick={handleReindex} disabled={isReindexing} className="p-3 text-gray-400 hover:text-blue-500 transition-all rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800">
               <RefreshCw size={20} className={isReindexing ? 'animate-spin text-blue-500' : ''} />
            </button>
            <div className="h-6 w-px bg-gray-100 dark:bg-slate-800" />
            <div className="flex bg-gray-100 dark:bg-slate-800 p-1 rounded-xl">
              <button onClick={() => updateSettings({...settings, libraryView: 'grid'})} className={`p-2 rounded-lg ${settings.libraryView === 'grid' ? 'bg-white dark:bg-slate-700 text-blue-500 shadow-sm' : 'text-gray-400'}`}><Grid size={18}/></button>
              <button onClick={() => updateSettings({...settings, libraryView: 'list'})} className={`p-2 rounded-lg ${settings.libraryView === 'list' ? 'bg-white dark:bg-slate-700 text-blue-500 shadow-sm' : 'text-gray-400'}`}><List size={18}/></button>
              <button onClick={() => updateSettings({...settings, libraryView: 'neural'})} className={`p-2 rounded-lg ${settings.libraryView === 'neural' ? 'bg-white dark:bg-slate-700 text-blue-500 shadow-sm' : 'text-gray-400'}`}><Layers size={18}/></button>
            </div>
            <div className="flex gap-1 p-1">
              {(['sm', 'md', 'lg'] as CardSize[]).map(size => (
                <button key={size} onClick={() => updateSettings({...settings, cardSize: size})} className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase transition-all ${settings.cardSize === size ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>{size}</button>
              ))}
            </div>
            <button onClick={() => setShowImport(true)} className="p-4 bg-blue-600 text-white rounded-2xl shadow-lg hover:scale-105 transition-all"><Plus size={20}/></button>
          </div>
        </div>

        <div className="flex items-center gap-3 overflow-x-auto pb-4 no-scrollbar">
          {settings.customCategories.map((cat) => (
            <div key={cat} className="group relative shrink-0">
              <button onClick={() => setFilterCategory(filterCategory === cat ? null : cat)} className={`px-5 py-3 rounded-2xl border-2 font-black text-[10px] uppercase transition-all ${filterCategory === cat ? 'bg-blue-600 border-blue-600 text-white shadow-xl' : 'bg-white dark:bg-slate-900 border-gray-100 dark:border-slate-800 dark:text-white'}`}>{cat}</button>
              <div className="absolute -top-3 left-1/2 -translate-x-1/2 flex opacity-0 group-hover:opacity-100 transition-all bg-white dark:bg-slate-800 rounded-lg shadow-xl border dark:border-slate-700 p-1 z-20">
                <button onClick={() => reorderCategory(cat, 'up')} className="p-1 hover:text-blue-500"><ChevronUp size={14}/></button>
                <button onClick={() => reorderCategory(cat, 'down')} className="p-1 hover:text-blue-500"><ChevronDown size={14}/></button>
                <button onClick={() => deleteCategory(cat)} className="p-1 hover:text-red-500"><X size={14}/></button>
              </div>
            </div>
          ))}
        </div>
      </header>

      <div ref={containerRef} className="relative min-h-[500px]">
        {settings.libraryView === 'neural' && (
            <svg className="absolute inset-0 pointer-events-none z-0 w-full h-full overflow-visible">
                {links.map((link, idx) => <line key={idx} x1={link.x1} y1={link.y1} x2={link.x2} y2={link.y2} stroke={link.color} strokeWidth="1.5" strokeOpacity="0.15" strokeDasharray="6,6" />)}
            </svg>
        )}
        <div className={`grid ${settings.libraryView === 'list' ? 'grid-cols-1 gap-4' : gridCols} relative z-10`}>
          {filteredNotes.map(note => (
            <div key={note.id} data-note-id={note.id} onClick={() => navigate(`/editor/${note.id}`)} className={`bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-gray-100 dark:border-slate-800 shadow-sm hover:shadow-2xl transition-all cursor-pointer group flex flex-col h-full`}>
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                    <div className="flex p-1 bg-gray-50 dark:bg-slate-800 rounded-lg">
                        {(['new', 'in-work', 'read', 'finished'] as NoteStatus[]).map(s => (
                            <button key={s} onClick={(e) => { e.stopPropagation(); setNoteStatus(note.id, s); }} className={`p-1 rounded ${note.status === s ? 'bg-white dark:bg-slate-700 shadow-sm' : 'opacity-30'}`}><StatusIcon status={s}/></button>
                        ))}
                    </div>
                    <span className="text-[8px] font-black uppercase text-gray-400">{note.category}</span>
                </div>
                <button onClick={(e) => { e.stopPropagation(); moveToTrash(note.id); }} className="p-2 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={14}/></button>
