            {logs.map(log => <div key={log.id} className="text-slate-400 border-l-2 border-slate-800 pl-4 py-0.5"><span className="opacity-30">[{new Date(log.timestamp).toLocaleTimeString()}]</span> <span className={`font-black uppercase ${log.level === 'error' ? 'text-red-500' : 'text-blue-500'}`}>{log.level}:</span> {log.message}</div>)}
        </div>
      </section>
    </div>
  );
};

export default SettingsPage;
